'    x02: seqid',
'}, {',
'    success: function(data) {',
'     // alert(data.observaciones )',
'',
'        $s("P3_OBSERVACIONES",data.observaciones);',
'        $s("P3_ST_RESOLUCION",data.st_resolucion);',
'        $s("P3_SP_RESOLUCION",data.tp_resolucion);',
'        $s("P3_MOVIMIENTOS",data.origen);',
