'        $s("P3_TIPO_DOC",data.tipo_doc_id);',
'',
'        $s("P3_CODCIA",data.codcia);  ',
'        $s("P3_CODEMPRESA",data.codempresa);  ',
'        $s("P3_IDPROCESO",data.idproceso);  ',
'        $s("P3_IDPOLIZA",data.idpoliza);',
'        $s("P3_NOMBRE",data.nombre);',
'        //alert(data.nombre)',
'',
'       // apex.items.P1_EMPNO.value = data.nombre;',
'',
'        apex.region("Historico_Riesgo").refresh();',
'    }',
'    });',
'  });',
'});',
''))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'18'
