wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(239001401371196214)
,p_plug_name=>unistr('Hist\00F3rico de Riesgos')
,p_region_name=>'Historico_Riesgo'
,p_parent_plug_id=>wwv_flow_imp.id(239001253110196212)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>40
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select CODEMPRESA,',
'       CODCIA,',
'       ID_PROCESO,',
'       IDPOLIZA,',
'       CODCLIENTE,',
'       CODASEGURADO,',
'       ORIGEN,',
'       ST_RESOLUCION,',
'       FE_ESTATUS,',
'       TP_RESOLUCION,',
