wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(244046938030679029)
,p_plug_name=>unistr('Administraci\00F3n de Riesgos PLD')
,p_region_name=>'Admin_Riesgos'
,p_parent_plug_id=>wwv_flow_imp.id(239001253110196212)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select CODEMPRESA,',
'       CODCIA,',
'       ID_PROCESO,',
'       IDPOLIZA,',
'       STSPOLIZA,',
'       CODCLIENTE,',
'       CODASEGURADO,',
'       ORIGEN,',
'       TIPO_DOC_IDENTIFICACION,',
'       NUM_DOC_IDENTIFICACION,',
'       NOMBRE,',
'       ST_RESOLUCION,',
'       FE_ESTATUS,',
'       TP_RESOLUCION,',
'       OBSERVACIONES,',
'       FECHA_PROCESO,',
'       USUARIO,',
'       CASE ',
'  WHEN ST_RESOLUCION in (''APRO'',''ALTO'')  THEN ',
'    ''<button class="fa fa-edit" disabled>',
'     </span>',
'    </button>''',
'  ELSE ',
'  ''<a href="'' || APEX_PAGE.GET_URL(',
'                      p_page   => 2,',
'                      p_clear_cache => 2,',
'                      p_items  => ''P2_CODCIA,P2_CODEMPRESA,P2_ID_PROCESO,P2_CODASEGURADO,P2_IDPOLIZA'',',
'                      p_values => CODCIA || '','' || CODEMPRESA || '','' || ID_PROCESO || '','' || CODASEGURADO || '','' || IDPOLIZA',
'                   ) || ',
'      ''" class="fa fa-edit" title="Editar">',
'       ',
'       </a>''',
'      ',
'END AS Editar,',
'       apex_item.radiogroup(1,codempresa||'':''|| codcia||'':''|| id_proceso||'':''||idpoliza||'':''||codasegurado||'':'')Selecionar,',
'       apex_item.checkbox2 (2,codempresa||'':''|| codcia||'':''|| id_proceso||'':''||idpoliza||'':''||codasegurado||'':'')Selecionar_procesar',
'  from ADMON_RIESGO',
'  where ST_RESOLUCION IN (SELECT column_value',
'                           FROM TABLE(APEX_STRING.SPLIT(:P3_ST_RESOLUCION_B, '',''))',
'                          UNION',
'                         SELECT column_value',
'                           FROM TABLE(APEX_STRING.SPLIT(:P3_ST_RESOLUCION_INICIAL, '','')))',
'    and (idpoliza = :P3_CONSECUTIVO or :P3_CONSECUTIVO  is null)',
'    and (tp_resolucion = :P3_TP_RESOLUCION or :P3_TP_RESOLUCION IS NULL)',
'    and (trunc(fecha_proceso)  >=  TO_DATE(:P3_FECHA_DESDE,''DD/MM/RRRR'') OR TO_DATE(:P3_FECHA_DESDE,''MM/DD/RRRR'') is null)',
'    AND ( trunc(fecha_proceso)  <= TO_DATE(:P3_FECHA_HASTA,''DD/MM/RRRR'') or TO_DATE(:P3_FECHA_HASTA,''DD/MM/RRRR'') is null)',
'    and (NUM_DOC_IDENTIFICACION = :P3_RFC OR :P3_RFC IS NULL)',
'  order by FE_ESTATUS asc'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P3_ST_RESOLUCION_INICIAL,P3_ST_RESOLUCION_B,P3_CONSECUTIVO,P3_FECHA_DESDE,P3_FECHA_HASTA,P3_TP_RESOLUCION,P3_RFC'
,p_prn_page_header=>unistr('Administraci\00F3n de Riesgos PLD')
,p_landmark_type=>'exclude_landmark'
);
