);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(244757744475205492)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Actualiza Masivo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'  v_codempresa     admon_riesgo.codempresa%type;',
'  v_codcia         admon_riesgo.codcia%type;',
'  v_id_proceso     admon_riesgo.id_proceso%type;',
'  v_idpoliza       admon_riesgo.idpoliza%type;',
'  v_codasegurado   admon_riesgo.codasegurado%type;',
'',
'  v_codcliente    admon_riesgo.codcliente%type;',
'  v_tipo_doc      admon_riesgo.tipo_doc_identificacion%type;',
'  v_num_doc       admon_riesgo.num_doc_identificacion%type;',
'',
'  STATUS_DE_POLIZA  varchar2(100);',
'  CUANTOSHAY        number;',
'  	W_CUENTA_NORMAL        NUMBER;',
'	W_CUENTA_REPRESENTANTE NUMBER;',
'	W_CUENTA_ENDOSO        NUMBER;',
'	W_CUENTA_BLOQUEADOS    NUMBER := 0;',
'	nDummy								 NUMBER;',
'',
'  cursor c_datos is ',
'  select codempresa,',
'        codcia,',
'        id_proceso,',
'        idpoliza,',
'        stspoliza,',
'        codcliente,',
'        codasegurado,',
'        origen,',
'        tipo_doc_identificacion,',
'        num_doc_identificacion,',
'        nombre,',
'        st_resolucion,',
'        fe_estatus,',
'        tp_resolucion,',
'        observaciones,',
'        fecha_proceso,',
'        usuario',
'   from admon_riesgo',
'  where codempresa = v_codempresa',
'    and codcia = v_codcia',
'    and id_proceso = v_id_proceso',
'    and idpoliza = v_idpoliza',
'    and codasegurado = v_codasegurado;',
'',
'    tDatos c_datos%rowtype;',
'         ',
'BEGIN',
'',
'  FOR i IN 1 .. APEX_APPLICATION.G_F02.COUNT LOOP',
'',
'    begin',
'      select substr(APEX_APPLICATION.G_F02(i), 1, instr(APEX_APPLICATION.G_F02(i), '':'') - 1) p1,',
'             substr(APEX_APPLICATION.G_F02(i), instr(APEX_APPLICATION.G_F02(i), '':'', 1, 1) + 1, instr(APEX_APPLICATION.G_F02(i), '':'', 1, 2) - instr(APEX_APPLICATION.G_F02(i), '':'', 1, 1) - 1) p3,',
'             substr(APEX_APPLICATION.G_F02(i), instr(APEX_APPLICATION.G_F02(i), '':'', 1, 2) + 1, instr(APEX_APPLICATION.G_F02(i), '':'', 1, 3) - instr(APEX_APPLICATION.G_F02(i), '':'', 1, 2) - 1) p3,',
'             substr(APEX_APPLICATION.G_F02(i), instr(APEX_APPLICATION.G_F02(i), '':'', 1, 3) + 1, instr(APEX_APPLICATION.G_F02(i), '':'', 1, 4) - instr(APEX_APPLICATION.G_F02(i), '':'', 1, 3) - 1) p4,',
'             substr(APEX_APPLICATION.G_F02(i), instr(APEX_APPLICATION.G_F02(i), '':'', 1, 4) + 1, instr(APEX_APPLICATION.G_F02(i), '':'', 1, 5) - instr(APEX_APPLICATION.G_F02(i), '':'', 1, 4) - 1) p5',
'        into v_codempresa,',
'             v_codcia,',
'             v_id_proceso,',
'             v_idpoliza,',
'             v_codasegurado',
'        from dual;',
'    exception',
'      when others then',
'        v_codempresa := null;',
'         v_codcia := null;',
'         v_id_proceso := null;',
'         v_idpoliza := null;',
'         v_codasegurado := null;',
'    end;',
'   ',
'    open c_datos;',
'    loop ',
'    fetch c_datos into tdatos;',
'    exit when c_datos%notfound;',
'',
'  v_codcliente   := tdatos.CODCLIENTE;',
'  v_tipo_doc    := tdatos.tipo_doc_identificacion;',
'  v_num_doc     := tdatos.num_doc_identificacion;',
'',
'   OC_ADMON_RIESGO_H.INSERTA(tdatos.CODCIA,',
'                              tdatos.CODEMPRESA,',
'                              tdatos.ID_PROCESO,',
'                              tdatos.IDPOLIZA,',
'                              tdatos.CODCLIENTE,',
'                              tdatos.CODASEGURADO,',
'                              tdatos.ORIGEN,                             ',
'                              tdatos.ST_RESOLUCION,',
'                              tdatos.TP_RESOLUCION);',
'',
' BEGIN',
'    SELECT STSPOLIZA',
'      INTO  STATUS_DE_POLIZA',
'      FROM POLIZAS  ',
'     WHERE IDPOLIZA      = tdatos.IDPOLIZA;',
'   EXCEPTION WHEN OTHERS THEN',
'   	  STATUS_DE_POLIZA := ''PEND'';',
'   END;	',
'     ',
'    SELECT COUNT(*)',
'      INTO CUANTOSHAY',
'      FROM ADMON_RIESGO  ',
'     WHERE IDPOLIZA      = tdatos.IDPOLIZA;',
'    --',
'',
'    SELECT COUNT(*)',
'      INTO W_CUENTA_BLOQUEADOS',
'      FROM ADMON_RIESGO  ',
'     WHERE IDPOLIZA      = tdatos.IDPOLIZA',
'       AND ST_RESOLUCION = ''BLOQ'';',
'    --    ',
'',
'    SELECT COUNT(*)',
'      INTO W_CUENTA_NORMAL',
'      FROM ADMON_RIESGO  ',
'     WHERE IDPOLIZA      = tdatos.IDPOLIZA',
'       AND ST_RESOLUCION = ''PEND'';',
'    --    ',
'   	SELECT COUNT(*)',
'      INTO W_CUENTA_REPRESENTANTE',
'      FROM ADMON_RIESGO_H',
'     WHERE IDPOLIZA      = tdatos.IDPOLIZA',
'       AND ST_RESOLUCION = ''PENR'';',
'    --',
'   	SELECT COUNT(*)',
'      INTO W_CUENTA_ENDOSO',
'      FROM ADMON_RIESGO',
'     WHERE IDPOLIZA      = tdatos.IDPOLIZA',
'       AND ST_RESOLUCION = ''PENT'';',
'    ',
'    IF CUANTOSHAY > 1 THEN ',
'		    IF W_CUENTA_BLOQUEADOS = 0 THEN    ',
'				    IF W_CUENTA_NORMAL = 1 THEN',
'				    	 IF STATUS_DE_POLIZA != ''EMI'' THEN',
'				    	 --',
'						       UPDATE POLIZAS',
'						          SET STSPOLIZA       = ''SOL'',',
'						              PLDSTAPROBADA   = ''S'',',
'						              PLDUSUARIOAPROB = :app_user',
'						        WHERE IDPOLIZA      = tdatos.IDPOLIZA',
'						          AND CODCIA        = tdatos.CODCIA',
'						          AND STSPOLIZA     = ''PLD''',
'						          AND PLDSTAPROBADA IS NULL;',
'						       --',
'						       STANDARD.COMMIT;',
'						   --',
'						   END IF;',
'				    END IF;',
'				    --',
'				    IF W_CUENTA_ENDOSO = 1 THEN',
'				    	 --',
'				       UPDATE ENDOSOS ',
'				          SET STSENDOSO     = ''SOL'',',
'				              PLDSTAPROBADA   = ''S'',',
'				              PLDUSUARIOAPROB = :app_user',
'				        WHERE IDPOLIZA = tdatos.IDPOLIZA',
'				          AND IDENDOSO = tdatos.CODCLIENTE',
'				          AND STSENDOSO = ''PLD'';',
'				       --',
'				       STANDARD.COMMIT;',
'				       --',
'				    END IF;',
'				    --',
'				    IF W_CUENTA_REPRESENTANTE > 0 THEN',
'				    	 --',
'				       UPDATE REP_LEGAL_PNJ R',
'				          SET R.ESTADO = ''ACT''',
'				        WHERE R.TIPO_DOC_REP_LEGAL = tdatos.TIPO_DOC_IDENTIFICACION',
'				          AND R.NUM_DOC_REP_LEGAL  = tdatos.NUM_DOC_IDENTIFICACION;',
'				       --',
'				       STANDARD.COMMIT;',
'				       --',
'				    END IF;',
'		  --',
'				  END IF;',
'		  --',
'',
'		    END IF;',
'    end loop;',
'    close c_datos;',
'',
'     UPDATE ADMON_RIESGO A',
'       SET  ST_RESOLUCION = :P3_WS_ST_RESOLUCION,',
'            TP_RESOLUCION = :P3_WS_TP_RESOLUCION,',
'            OBSERVACIONES = OBSERVACIONES||'' - ''||:P3_WS_OBSERVACIONES',
'     WHERE  codempresa  = v_codempresa',
'       and codcia       = v_codcia',
'       and id_proceso   = v_id_proceso',
'       and idpoliza     = v_idpoliza',
'       and codasegurado = v_codasegurado;',
'',
'       if SQL%ROWCOUNT > 0 then ',
'          ',
'DECLARE',
'	W_CUENTA_NORMAL        NUMBER;',
'	W_CUENTA_REPRESENTANTE NUMBER;',
'	W_CUENTA_ENDOSO        NUMBER;',
'	W_CUENTA_BLOQUEADOS    NUMBER := 0;',
'	W_CUENTA_TODOS			   NUMBER := 0;	',
'	W_ESTATUSPOL		       POLIZAS.STSPOLIZA%TYPE;',
'	W_ESTABLOQUEADA	       VARCHAR2(1);	',
'	nDummy								 NUMBER;',
'	',
'		',
'BEGIN',
'	--',
'	W_CUENTA_NORMAL        := 0;',
'	W_CUENTA_REPRESENTANTE := 0;',
'	W_CUENTA_ENDOSO        := 0;',
'	--',
'    --',
'    ',
'    SELECT COUNT(*)',
'      INTO W_CUENTA_BLOQUEADOS',
'      FROM ADMON_RIESGO  ',
'     WHERE IDPOLIZA      = v_idpoliza',
'       AND ST_RESOLUCION = ''BLOQ'';',
'    --',
'    SELECT COUNT(*)',
'      INTO W_CUENTA_TODOS',
'      FROM ADMON_RIESGO  ',
'     WHERE IDPOLIZA      = v_idpoliza;',
'    --',
'    SELECT COUNT(*)',
'      INTO W_CUENTA_NORMAL',
'      FROM ADMON_RIESGO  ',
'     WHERE IDPOLIZA      = v_idpoliza',
'       AND ST_RESOLUCION = ''PEND''; ',
'    --    ',
'   	SELECT COUNT(*)',
'      INTO W_CUENTA_REPRESENTANTE',
'      FROM ADMON_RIESGO_H',
'     WHERE IDPOLIZA      = v_idpoliza',
'       AND ST_RESOLUCION = ''PENR'';',
'    --',
'   	SELECT COUNT(*)',
'      INTO W_CUENTA_ENDOSO',
'      FROM ADMON_RIESGO',
'     WHERE IDPOLIZA      = v_idpoliza',
'       AND ST_RESOLUCION = ''PENT'';',
'    --',
'',
'    IF STATUS_DE_POLIZA = ''PRE'' THEN',
'    	  W_ESTATUSPOL := ''PRE'';',
'    ELSE',
'    	IF STATUS_DE_POLIZA = ''EMI'' THEN',
'    	  W_ESTATUSPOL := ''EMI'';',
'    	ELSE  ',
'    	 W_ESTATUSPOL := ''SOL'';',
'    	END IF;',
'    END IF;	 ',
'                	     	 ',
'    IF W_CUENTA_BLOQUEADOS = 0 THEN',
'    	 IF CUANTOSHAY >= 1 THEN',
'',
'		    	 --',
'		       UPDATE POLIZAS',
'		          SET STSPOLIZA       = W_ESTATUSPOL,',
'		              PLDSTAPROBADA   = ''S'',',
'		              PLDUSUARIOAPROB = :app_user',
'		        WHERE IDPOLIZA      = v_idpoliza',
'		          AND CODCIA        = v_CODCIA;',
'		       --',
'		       STANDARD.COMMIT;',
'		       --',
'--		    END IF;',
'		    --',
'--		    IF W_CUENTA_ENDOSO = 1 THEN',
'		    	 --',
'		       UPDATE ENDOSOS ',
'		          SET STSENDOSO     = ''SOL'',',
'		              PLDSTAPROBADA   = ''S'',',
'		              PLDUSUARIOAPROB = :app_user',
'		        WHERE IDPOLIZA = v_idpoliza',
'		          AND IDENDOSO = v_CODCLIENTE;',
'		       --',
'		       STANDARD.COMMIT;',
'		       --',
'--		    END IF;',
'		    --',
'--		    IF W_CUENTA_REPRESENTANTE > 0 THEN',
'		    	 --',
'		       UPDATE REP_LEGAL_PNJ R',
'		          SET R.ESTADO = ''ACT''',
'		        WHERE R.TIPO_DOC_REP_LEGAL = v_tipo_doc',
'		          AND R.NUM_DOC_REP_LEGAL  = v_num_doc;',
'		       --',
'		       STANDARD.COMMIT;',
'		       --',
'--		    END IF;',
'  	   END IF;',
'  --',
'    ELSE',
'  --  	 nDummy := ALERTA(''POST POR ELSE '');     	 	',
'       UPDATE POLIZAS',
'          SET STSPOLIZA       = ''PLD'',',
'              PLDSTAPROBADA   = '''',',
'              PLDUSUARIOAPROB = ''''',
'        WHERE IDPOLIZA      = v_idpoliza',
'          AND CODCIA        = v_CODCIA;',
'       --',
'       STANDARD.COMMIT;',
'       --',
'--		    END IF;',
'    --',
'--		    IF W_CUENTA_ENDOSO = 1 THEN',
'    	 --',
'       UPDATE ENDOSOS ',
'          SET STSENDOSO     = ''PLD'',',
'              PLDSTAPROBADA   = '''',',
'              PLDUSUARIOAPROB = ''''',
'        WHERE IDPOLIZA = v_IDPOLIZA',
'          AND IDENDOSO = v_CODCLIENTE;',
'       --',
'       STANDARD.COMMIT;',
'       --',
'--		    END IF;',
'    --',
'	 END IF;	',
'END;            ',
'       end if;',
'',
'  END LOOP;',
'',
'  :P3_WS_OBSERVACIONES := NULL;',
'  :P3_WS_ST_RESOLUCION := NULL;',
'  :P3_WS_TP_RESOLUCION := NULL;',
'exception ',
'when others then ',
'raise_application_error(-20100,dbms_utility.format_error_backtrace);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(239002825531196228)
,p_process_success_message=>unistr('Actualizaci\00F3n Masiva Ejecuta con \00C9xito')
,p_internal_uid=>32192169509884009
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(244758471560205499)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Ir Personas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_url VARCHAR2(4000);',
'BEGIN',
'   l_url := apex_util.prepare_url(',
'      p_url => ''f?p=102:50:&SESSION.::NO::P50_NUM_DOC,P50_TIPO_DOC,P50_PLD,P50_PLD_SINIESTROS:'' ||',
'               apex_util.url_encode(:P3_NUM_DOC) || '','' ||',
