'               ''S''|| '','' ||',
'               NULL',
'   );',
'   apex_util.redirect_url(p_url => l_url);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(239002954891196229)
,p_internal_uid=>32192896594884016
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(245355273154037493)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Busqueda'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P3_SP_RESOLUCION := null;',
':P3_ST_RESOLUCION := NULL;',
'--:P3_NOMBRE        := NULL;',
':P3_MOVIMIENTOS   := NULL;',
':P3_TIPO_PERSONA  := NULL;',
':P3_OBSERVACIONES := NULL;',
'',
'if :P3_ST_RESOLUCION_B IS NOT NULL THEN ',
'  :P3_ST_RESOLUCION_INICIAL := NULL;',
'ELSIF  :P3_ST_RESOLUCION_B IS  NULL THEN',
'',
'',
'  if (:P3_CONSECUTIVO IS NULL AND ',
'     :P3_ST_RESOLUCION_B IS NULL AND ',
'     :P3_TP_RESOLUCION IS NULL AND',
'     :P3_RFC IS NULL) THEN ',
'      :P3_ST_RESOLUCION_INICIAL := ''PEND,PENT,PENR'';',
'   ELSE ',
'    --RAISE_APPLICATION_ERROR(-20100,''ELSE'');',
'     SELECT LISTAGG(VL.CODVALOR,'','')',
'      INTO  :P3_ST_RESOLUCION_B',
'      FROM VALORES_DE_LISTAS VL',
'     WHERE VL.CODLISTA = ''CATSTRIE'';',
'   END IF;',
'END IF;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(245354629589037487)
,p_internal_uid=>32789698188716010
);
end;
/
begin
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(239002773331196227)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'administracion_riesgo_seleccionado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  v_codempresa     admon_riesgo.codempresa%type;',
'  v_codcia         admon_riesgo.codcia%type;',
'  v_id_proceso     admon_riesgo.id_proceso%type;',
'  v_idpoliza       admon_riesgo.idpoliza%type;',
'  v_codasegurado   admon_riesgo.codasegurado%type;',
'  v_nombre         admon_riesgo.nombre%type;',
'',
'  lv_observaciones              admon_riesgo.observaciones%type;',
'  lv_st_resolucion              admon_riesgo.st_resolucion%type;',
'  lv_tp_resolucion              admon_riesgo.tp_resolucion%type;',
'  lv_origen                     admon_riesgo.origen%type;',
'  lv_num_doc_identificacion    admon_riesgo.num_doc_identificacion%type;',
'  lv_tipo_doc_identificacion    admon_riesgo.tipo_doc_identificacion%type;',
'  vUrl varchar2(2000);',
'  lv_origen_poliza  varchar2(200);',
'  cTipoMovimiento   varchar2(400);',
'  cDescResolucion   varchar2(400);',
'  cDesctpResolucion varchar2(400);',
'begin',
'',
' ',
'  begin',
'      select substr(APEX_APPLICATION.G_x02, 1, instr(APEX_APPLICATION.G_x02, '':'') - 1) p1,',
'             substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 1) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - instr(APEX_APPLICATION.G_x02, '':'', 1, 1) - 1) p3,',
'             substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - 1) p3,',
'             substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - 1) p4,',
'             substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 5) - instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - 1) p5',
'        into v_codempresa,',
'             v_codcia,',
'             v_id_proceso,',
'             v_idpoliza,',
'             v_codasegurado',
'        from dual;',
'    exception',
'      when others then',
'        v_codempresa := null;',
'         v_codcia := null;',
'         v_id_proceso := null;',
'         v_idpoliza := null;',
'         v_codasegurado := null;',
'    end;',
'',
' ',
'  begin ',
'    select observaciones, ',
'           st_resolucion, ',
'           tp_resolucion, ',
'           origen,',
'           num_doc_identificacion,',
'           tipo_doc_identificacion, ',
'           CASE ',
'                                                                  WHEN CODCLIENTE IS NOT NULL THEN ',
'                                                                    ''ES UN CLIENTE - '' || CODCLIENTE',
'                                                                  WHEN CODASEGURADO IS NOT NULL THEN ',
'                                                                    ''ES UN ASEGURADO - '' || CODASEGURADO',
'                                                                  ELSE ',
'                                                                    NULL',
'                                                                END AS ORIGEN_POLIZA,nombre',
'      into lv_observaciones, lv_st_resolucion, lv_tp_resolucion, lv_origen,lv_num_doc_identificacion, lv_tipo_doc_identificacion, lv_origen_poliza,v_nombre',
'      from admon_riesgo',
'     where codempresa = v_codempresa',
'       and codcia = v_codcia',
'       and id_proceso = v_id_proceso',
'       and idpoliza = v_idpoliza',
'       and codasegurado = v_codasegurado;',
'  exception',
'    when others then ',
'    lv_observaciones := null;',
'    lv_tp_resolucion := null;',
'    lv_st_resolucion := null;',
'    lv_origen        := null;',
'    lv_origen_poliza := null;',
'    v_nombre         := null;',
'  end;',
'  ',
'  BEGIN',
'    SELECT VL.DESCVALLST ',
'      INTO cTipoMovimiento ',
'      FROM VALORES_DE_LISTAS VL',
'     WHERE VL.CODLISTA = ''CATORIGE''',
'       and codvalor = lv_origen;',
'  exception ',
'  when others then ',
'  cTipoMovimiento := null;',
'  END;',
'  ',
'  begin',
'  SELECT VL.DESCVALLST',
'   into cDescResolucion',
'  FROM VALORES_DE_LISTAS VL',
' WHERE VL.CODLISTA = ''CATSTRIE'' ',
'   and codvalor = lv_st_resolucion;',
'   exception ',
'   when others then ',
'    cDescResolucion := null;',
' end; ',
'',
'begin',
' SELECT VL.DESCVALLST',
' into cDesctpResolucion',
'  FROM VALORES_DE_LISTAS VL',
' WHERE VL.CODLISTA = ''CATRESOL''',
' and codvalor = lv_tp_resolucion;',
'   exception ',
'   when others then ',
'    cDesctpResolucion := null;',
' end; ',
'',
'  apex_json.open_object;',
'  apex_json.write(''observaciones'', lv_observaciones);',
'  apex_json.write(''st_resolucion'', cDescResolucion ); -- lv_st_resolucion);',
'  apex_json.write(''tp_resolucion'', cDesctpResolucion); --lv_tp_resolucion);',
