wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(245723765301775496)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Iniciar Page'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	cAplicacion	        VARCHAR2(40);',
'	cUsuario	          VARCHAR2(40);',
'	cAcceso		          VARCHAR2(2);',
'	cSupervisor         VARCHAR2(1);',
'	Dummy		            NUMBER;',
'	--Id_Alerta	          ALERT	:= Find_Alert(''ALERTA''); ',
'BEGIN',
'	cUsuario	          := :APP_USER;',
'	cAplicacion	        := ''CONSUQEQ'';',
'--	:GLOBAL.nCodCia := 1;',
' -- default_value (1,''global.ncodcia'');',
'	--',
'	--proc_TituloVentana(cAplicacion);',
'	--',
'	BEGIN',
'		SELECT U.Supervisor',
'		  INTO cSupervisor',
'		  FROM USUARIOS U',
'		 WHERE U.CodUsuario	= cUsuario',
'		   AND U.CodCia     = :CodCia;',
'	EXCEPTION',
'		WHEN NO_DATA_FOUND THEN',
'			 cSupervisor	:= ''N'';',
'	END;',
'',
'  IF cSupervisor = ''N'' THEN',
'		BEGIN',
'			SELECT ''SI''',
'			  INTO cAcceso',
'			  FROM USUARIOS U, ACCESOS_AUTORIZADOS A',
'			 WHERE U.CodCia     = :CodCia',
'			   AND U.CodUsuario	= cUsuario',
'			   AND A.CodGrupo	  = U.CodGrupo',
'			   AND A.CodCia     = :CodCia',
'			   AND A.CodAplica  = cAplicacion;',
'		EXCEPTION',
'			WHEN NO_DATA_FOUND THEN',
'				 cAcceso	:= ''NO'';',
'		END;',
'',
'		IF cAcceso = ''NO'' THEN',
unistr('			RAISE_APPLICATION_ERROR(-20100, '' No est\00E1 autorizado para utilizar esta aplicaci\00F3n.  Consulte a su Administrador de Sistemas'');'),
'		END IF;',
'	END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>33158190336454013
);
end;
