,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Actualizar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'',
'  v_rowid rowid;',
'',
'    cursor c_datos is ',
'  select ROWID RECORD_ID, ',
'        codcia,',
'        codempresa,',
'        id_proceso,',
'        idpoliza,',
'        stspoliza,',
'        codcliente,',
'        numsiniestro,',
'        origen,',
'        tipo_doc_identificacion,',
'        num_doc_identificacion,',
'        nombre_beneficiario,',
'        st_resolucion,',
'        fe_estatus,',
'        tp_resolucion,',
'        observaciones,',
'        fecha_proceso,',
'        usuario ',
'   from ADMON_RIESGO_SINIESTROS ',
'  where rowid = v_rowid; ',
'',
'  tCursor c_datos%rowtype;',
'   ',
'   ',
'begin',
'--FOR i IN 1 .. APEX_APPLICATION.G_F02.COUNT LOOP',
'',
' /* begin',
'      select substr(APEX_APPLICATION.G_F02(i), 1, instr(APEX_APPLICATION.G_F02(i), '':'') - 1) p1',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := NUll;',
'    end;*/',
'',
'  --  if v_rowid is not null then ',
'',
'',
'        OC_ADMON_RIESGO_SINIESTROS_H.INSERTA(:P5_CODCIA,',
'                              :P5_CODEMPRESA,',
'                              :P5_ID_PROCESO,',
'                              :P5_IDPOLIZA,',
'                              '''',',
'                              :P5_CODCLIENTE,',
'                              :P5_NUMSINIESTRO,',
'                              :P5_ORIGEN,',
'                              ''RFC'',      ',
'							  :P5_NUM_DOC_IDENTIFICACION,',
'							  :P5_NOMBRE_BENEFICIARIO,                                                     ',
'                              :P5_ST_RESOLUCION,',
'                              TRUNC(SYSDATE),',
'                              :P5_TP_RESOLUCION,',
'                              :P5_OBSERVACIONES,',
'                              TRUNC(SYSDATE),',
'                              :APP_USER);',
'',
'--    end if;',
'--END LOOP;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>44453919838971606
);
