unistr('// Espera a que la p\00E1gina est\00E9 lista'),
'$(document).ready(function () {',
'  // Delegar evento change sobre radio buttons dentro del reporte',
'  $("#ARSiniestros").on("change", "input[name=''f01'']", function (event) {',
'    ',
'    var elem = event.target; // este es el radio button clicado',
'    var marcado = $(elem).is('':checked'');',
'    var seqid = $(elem).parent().find("input[name=''f01'']").val();',
'',
'    console.log(''marcado: '' + marcado);',
'    console.log(''seqid: '' + seqid);',
'',
'    // Enviar el cambio a PL/SQL',
'apex.server.process("Registro Seleccionado", {',
'    x01: marcado,',
'    x02: seqid',
'}, {',
'    success: function(data) {',
'     // alert(data.observaciones )',
'',
'    $s("P7_ST_RESOLUCION",data.st_resolucion);',
'    $s("P7_MOVIMIENTOS", data.origen);',
'    $s("P7_TIPO_PERSONA", data.tp_resolucion);',
'    $s("P7_OBSERVACIONES", data.observaciones);',
'    $s("P7_TIPO_DOC", data.tipo_doc_identificacion);',
'    $s("P7_NUM_DOC", data.num_doc_identificacion);',
'     $s("P7_ORIGEN_POLIZA", data.origen_poliza);',
'    $s("P7_URL", data.url);',
'    ',
'        apex.region("Historico_RS").refresh();',
'    }',
'    });',
'  });',
'});',
''))
