 p_id=>wwv_flow_imp.id(245823929799418103)
,p_plug_name=>unistr('Administraci\00F3n de Riesgos Siniestros')
,p_region_name=>'ARSiniestros'
,p_parent_plug_id=>wwv_flow_imp.id(245784728091420623)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ROWID RecordId,',
'       CODCIA,',
'       CODEMPRESA,',
'       ID_PROCESO,',
'       IDPOLIZA,',
'       STSPOLIZA,',
'       CODCLIENTE,',
'       NUMSINIESTRO,',
'       ORIGEN,',
'       TIPO_DOC_IDENTIFICACION,',
'       NUM_DOC_IDENTIFICACION,',
'       NOMBRE_BENEFICIARIO,',
'       ST_RESOLUCION,',
'       FE_ESTATUS,',
'       TP_RESOLUCION,',
'       OBSERVACIONES,',
'       FECHA_PROCESO,',
'       USUARIO,',
'        apex_item.radiogroup(1,ROWID ||'':'')Selecionar,',
'         apex_item.checkbox2 (2,ROWID||'':'')Selecionar_procesar',
'  from ADMON_RIESGO_SINIESTROS',
'  where ST_RESOLUCION IN (SELECT column_value',
'                           FROM TABLE(APEX_STRING.SPLIT(:P7_ST_RESOLUCION_B, '',''))',
'                          UNION',
'                         SELECT column_value',
'                           FROM TABLE(APEX_STRING.SPLIT(:P7_ST_RESOLUCION_INICIAL, '','')))',
'      and idpoliza = NVL(:P7_CONSECUTIVO, IDPOLIZA)',
'   and (tp_resolucion = :P7_TP_RESOLUCION or :P7_TP_RESOLUCION is null)',
'    and (trunc(fecha_proceso)  >=  TO_DATE(:P7_FECHA_DESDE,''DD/MM/RRRR'') OR TO_DATE(:P7_FECHA_DESDE,''MM/DD/RRRR'') is null)',
'    AND ( trunc(fecha_proceso)  <= TO_DATE(:P7_FECHA_HASTA,''DD/MM/RRRR'') or TO_DATE(:P7_FECHA_HASTA,''DD/MM/RRRR'') is null)',
'    and NUM_DOC_IDENTIFICACION = nvl(:P7_RFC, NUM_DOC_IDENTIFICACION)',
'      order by FE_ESTATUS asc'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P7_ST_RESOLUCION_INICIAL,P7_ST_RESOLUCION_B,P7_CONSECUTIVO,P7_FECHA_DESDE,P7_FECHA_HASTA'
