wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(245950193639838821)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Actualiza_Masivo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'',
'  v_rowid rowid;',
'',
'    cursor c_datos is ',
'  select ROWID RECORD_ID, ',
'        codcia,',
'        codempresa,',
'        id_proceso,',
'        idpoliza,',
'        stspoliza,',
'        codcliente,',
'        numsiniestro,',
'        origen,',
'        tipo_doc_identificacion,',
'        num_doc_identificacion,',
'        nombre_beneficiario,',
'        st_resolucion,',
'        fe_estatus,',
'        tp_resolucion,',
'        observaciones,',
'        fecha_proceso,',
'        usuario ',
'   from ADMON_RIESGO_SINIESTROS ',
'  where rowid = v_rowid; ',
'',
'  tCursor c_datos%rowtype;',
'   ',
'   ',
'begin',
'FOR i IN 1 .. APEX_APPLICATION.G_F02.COUNT LOOP',
'',
'  begin',
'      select substr(APEX_APPLICATION.G_F02(i), 1, instr(APEX_APPLICATION.G_F02(i), '':'') - 1) p1',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := NUll;',
'    end;',
'',
'    if v_rowid is not null then ',
'',
'          BEGIN',
'        update ADMON_RIESGO_SINIESTROS',
'           set ST_RESOLUCION = :P7_WS_ST_RESOLUCION,',
'               TP_RESOLUCION = :P7_WS_TP_RESOLUCION,',
'               OBSERVACIONES = OBSERVACIONES||'' - ''||:P7_WS_OBSERVACIONES',
'         WHERE ROWID = v_rowid;',
'      END;',
'',
'    open c_datos;',
'    loop',
'    fetch c_datos into tCursor;',
'    exit when c_datos%notfound;',
'',
'        OC_ADMON_RIESGO_SINIESTROS_H.INSERTA(tCursor.CODCIA,',
'                              tCursor.CODEMPRESA,',
'                              tCursor.ID_PROCESO,',
'                              tCursor.IDPOLIZA,',
'                              '''',',
'                              tCursor.CODCLIENTE,',
'                              tCursor.NUMSINIESTRO,',
'                              tCursor.ORIGEN,',
'                              ''RFC'',      ',
'							  tCursor.NUM_DOC_IDENTIFICACION,',
'							  tCursor.NOMBRE_BENEFICIARIO,                                                     ',
'                              tCursor.ST_RESOLUCION,',
'                              TRUNC(SYSDATE),',
'                              tCursor.TP_RESOLUCION,',
'                              tCursor.OBSERVACIONES,',
'                              TRUNC(SYSDATE),',
'                              :APP_USER);',
'',
'',
'    end loop;',
'    close c_datos;',
'    end if;',
'END LOOP;',
':P7_WS_ST_RESOLUCION := '''';',
':P7_WS_TP_RESOLUCION := '''';',
':P7_WS_OBSERVACIONES := '''';',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(246451870378091775)
,p_process_success_message=>unistr('Proceso de actualizaci\00F3n, concluido')
,p_internal_uid=>33384618674517338
);
