wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(245946721919838786)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Registro Seleccionado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  v_codempresa     admon_riesgo.codempresa%type;',
'  v_codcia         admon_riesgo.codcia%type;',
'  v_id_proceso     admon_riesgo.id_proceso%type;',
'  v_idpoliza       admon_riesgo.idpoliza%type;',
'  v_numsiniestro   admon_riesgo.codasegurado%type;',
'',
'  cTipoMovimiento    varchar2(400);',
'  cDescResolucion    varchar2(400);',
'  cDesctpResolucion  varchar2(400);',
'  v_rowid          rowid;',
'',
'  v_origen_poliza varchar2(50);',
'',
'  vUrl varchar2(4000);',
'',
'  cursor c_datos is ',
'  select codcia,',
'        codempresa,',
'        id_proceso,',
'        idpoliza,',
'        stspoliza,',
'        codcliente,',
'        numsiniestro,',
'        origen,',
'        tipo_doc_identificacion,',
'        num_doc_identificacion,',
'        nombre_beneficiario,',
'        st_resolucion,',
'        fe_estatus,',
'        tp_resolucion,',
'        observaciones,',
'        fecha_proceso,',
'        usuario ',
'   from ADMON_RIESGO_SINIESTROS ',
'  where rowid = v_rowid; ',
'',
'  tCursor c_datos%rowtype;',
'   ',
'',
'begin ',
'',
'  begin',
'      select substr(APEX_APPLICATION.G_x02, 1, instr(APEX_APPLICATION.G_x02, '':'') - 1) p1',
'         --    substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 1) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - instr(APEX_APPLICATION.G_x02, '':'', 1, 1) - 1) p3,',
'           --  substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - 1) p3,',
'             --substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - 1) p4,',
'            -- substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 5) - instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - 1) p5',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := NUll;',
'    end;',
'',
'  if v_rowid is not null then ',
'    open c_datos;',
'    loop',
'    fetch c_datos into tCursor;',
'    exit when c_datos%notfound;',
'',
'    if tcursor.codcliente is not null then ',
'    v_origen_poliza := ''- ES UN CLIENTE -'';',
'    end if;',
'',
'  BEGIN',
'    SELECT VL.DESCVALLST ',
'      INTO cTipoMovimiento ',
'      FROM VALORES_DE_LISTAS VL',
'     WHERE VL.CODLISTA = ''CATORIGE''',
'       and codvalor = tcursor.origen;',
'  exception ',
'  when others then ',
'  cTipoMovimiento := null;',
'  END;',
'',
'    begin',
'  SELECT VL.DESCVALLST',
'   into cDescResolucion',
'  FROM VALORES_DE_LISTAS VL',
' WHERE VL.CODLISTA = ''CATSTRIE'' ',
'   and codvalor = tcursor.st_resolucion;',
'   exception ',
'   when others then ',
'    cDescResolucion := null;',
' end; ',
'',
'begin',
' SELECT VL.DESCVALLST',
' into cDesctpResolucion',
'  FROM VALORES_DE_LISTAS VL',
' WHERE VL.CODLISTA = ''CATRESOL''',
' and codvalor = tcursor.tp_resolucion;',
'   exception ',
'   when others then ',
'    cDesctpResolucion := null;',
