wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(246835586462746385)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Procesar Seleccionado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'',
'',
'  v_rowid          rowid;',
'',
'',
'cursor c_datos is ',
'  select codcia,',
'        codempresa,',
'        iddenuncia,',
'        folio_denuncia,',
'        codtiporeporte,',
'        codcanaldenuncia,',
'        fec_reporte,',
'        codcomportamiento,',
'        numpolunico,',
'        monto_denuncia,',
'        fec_deteccion,',
'        nom_reporta,',
'        correo_electronico,',
'        nombre_persona_reportada,',
'        apellido_paterno,',
'        apellido_materno,',
'        descripcion_denuncia,',
'        codusuario_alta,',
'        fec_alta,',
'        codusuario_mod,',
'        fec_modificacion,',
'        st_operacion,',
'        observaciones',
'  from PLD_OPE_PREOCUPANTES',
'  where rowid = v_rowid;',
'',
'  tcursor c_datos%rowtype;',
'',
'begin',
' IF APEX_APPLICATION.G_x01 = ''true'' THEN',
'    begin',
'      select substr(APEX_APPLICATION.G_x02, 1, instr(APEX_APPLICATION.G_x02, '':'') - 1) p1',
'         --    substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 1) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - instr(APEX_APPLICATION.G_x02, '':'', 1, 1) - 1) p3,',
'           --  substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - 1) p3,',
'             --substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - 1) p4,',
'            -- substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 5) - instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - 1) p5',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := NUll;',
'    end;',
'',
'    ',
'  if v_rowid is not null then ',
'    open c_datos;',
'    loop',
'    fetch c_datos into tCursor;',
'    exit when c_datos%notfound;',
'',
'      apex_json.open_object;',
'    apex_json.write(''codcia'',tcursor.codcia);',
'    apex_json.write(''codempresa'',tcursor.codempresa);',
'    apex_json.write(''iddenuncia'',tcursor.iddenuncia);',
'    apex_json.write(''folio_denuncia'',tcursor.folio_denuncia);',
'    apex_json.write(''codtiporeporte'',tcursor.codtiporeporte);',
'    apex_json.write(''codcanaldenuncia'',tcursor.codcanaldenuncia);',
'    apex_json.write(''fec_reporte'',tcursor.fec_reporte);',
'    apex_json.write(''codcomportamiento'',tcursor.codcomportamiento);',
'    apex_json.write(''numpolunico'',tcursor.numpolunico);',
'    apex_json.write(''monto_denuncia'',tcursor.monto_denuncia);',
'    apex_json.write(''fec_deteccion'',tcursor.fec_deteccion);',
'    apex_json.write(''nom_reporta'',tcursor.nom_reporta);',
'    apex_json.write(''correo_electronico'',tcursor.correo_electronico);',
'    apex_json.write(''nombre_persona_reportada'',tcursor.nombre_persona_reportada);',
'    apex_json.write(''apellido_paterno'',tcursor.apellido_paterno);',
'    apex_json.write(''apellido_materno'',tcursor.apellido_materno);',
'    apex_json.write(''descripcion_denuncia'',tcursor.descripcion_denuncia);',
'    apex_json.write(''codusuario_alta'',tcursor.codusuario_alta);',
'    apex_json.write(''fec_alta'',tcursor.fec_alta);',
'    apex_json.write(''codusuario_mod'',tcursor.codusuario_mod);',
'    apex_json.write(''fec_modificacion'',tcursor.fec_modificacion);',
'    apex_json.write(''st_operacion'',tcursor.st_operacion);',
'    apex_json.write(''observaciones'',tcursor.observaciones);',
'',
'   apex_json.close_object;',
'',
'    end loop;',
'    close c_datos;',
'  else',
'',
'   apex_json.open_object;',
'          apex_json.write(''codcia'','''');',
'    apex_json.write(''codempresa'','''');',
'    apex_json.write(''iddenuncia'','''');',
'    apex_json.write(''folio_denuncia'','''');',
'    apex_json.write(''codtiporeporte'','''');',
'    apex_json.write(''codcanaldenuncia'','''');',
'    apex_json.write(''fec_reporte'','''');',
'    apex_json.write(''codcomportamiento'','''');',
'    apex_json.write(''numpolunico'','''');',
'    apex_json.write(''monto_denuncia'','''');',
'    apex_json.write(''fec_deteccion'','''');',
'    apex_json.write(''nom_reporta'','''');',
'    apex_json.write(''correo_electronico'','''');',
'    apex_json.write(''nombre_persona_reportada'','''');',
'    apex_json.write(''apellido_paterno'','''');',
'    apex_json.write(''apellido_materno'','''');',
'    apex_json.write(''descripcion_denuncia'','''');',
'    apex_json.write(''codusuario_alta'','''');',
'    apex_json.write(''fec_alta'','''');',
'    apex_json.write(''codusuario_mod'','''');',
'    apex_json.write(''fec_modificacion'','''');',
'    apex_json.write(''st_operacion'','''');',
'    apex_json.write(''observaciones'','''');',
'   apex_json.close_object;',
'',
'  end if;',
'  else ',
'     apex_json.open_object;',
'          apex_json.write(''codcia'','''');',
'    apex_json.write(''codempresa'','''');',
'    apex_json.write(''iddenuncia'','''');',
'    apex_json.write(''folio_denuncia'','''');',
'    apex_json.write(''codtiporeporte'','''');',
'    apex_json.write(''codcanaldenuncia'','''');',
'    apex_json.write(''fec_reporte'','''');',
'    apex_json.write(''codcomportamiento'','''');',
'    apex_json.write(''numpolunico'','''');',
'    apex_json.write(''monto_denuncia'','''');',
'    apex_json.write(''fec_deteccion'','''');',
'    apex_json.write(''nom_reporta'','''');',
'    apex_json.write(''correo_electronico'','''');',
'    apex_json.write(''nombre_persona_reportada'','''');',
'    apex_json.write(''apellido_paterno'','''');',
'    apex_json.write(''apellido_materno'','''');',
'    apex_json.write(''descripcion_denuncia'','''');',
'    apex_json.write(''codusuario_alta'','''');',
'    apex_json.write(''fec_alta'','''');',
'    apex_json.write(''codusuario_mod'','''');',
'    apex_json.write(''fec_modificacion'','''');',
'    apex_json.write(''st_operacion'','''');',
'    apex_json.write(''observaciones'','''');',
'   apex_json.close_object;',
'  END IF;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>34270011497424902
);
end;
