 p_id=>wwv_flow_imp.id(246836362331746392)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRE-INSERT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'FUNCTION FUN_FOLIODENUNCIA RETURN VARCHAR2 IS',
'  CNUMCONSEC      VARCHAR2(3);',
'  CFOLIODENUNCIA  VARCHAR2(100);',
'  CANIOREPORTE    VARCHAR2(4);',
'  CNUMDENUNCIA    VARCHAR2(5);',
'  CTIPOREPORTE    VARCHAR2(5);',
'  NDUMMY          NUMBER;',
'BEGIN	',
'	CANIOREPORTE := SUBSTR(TO_CHAR(TO_DATE(:P9_FEC_REPORTE,''DD/MM/YYYY''),''DD/MM/YYYY''),7,4);',
'	CNUMDENUNCIA := LPAD(:P9_IDDENUNCIA,3,0);',
'	CTIPOREPORTE := TRIM(:P9_CODTIPOREPORTE);',
'	IF CTIPOREPORTE IS NOT NULL AND CNUMDENUNCIA IS NOT NULL AND CANIOREPORTE IS NOT NULL THEN',
'    CFOLIODENUNCIA := CTIPOREPORTE||''-''||CANIOREPORTE||''-''||CNUMDENUNCIA; ',
'  END IF;',
'  RETURN CFOLIODENUNCIA;',
'END;',
'',
'BEGIN',
'IF :P9_IDDENUNCIA IS NULL THEN  ',
'   SELECT NVL(MAX(IDDENUNCIA),0) + 1',
'    INTO   :P9_IDDENUNCIA',
'    FROM   PLD_OPE_PREOCUPANTES;',
'',
'   :P9_CODEMPRESA := 1;',
'END IF;',
' :P9_FOLIO_DENUNCIA := TRIM(FUN_FOLIODENUNCIA);',
' --PROC_VALIDACIONES; ',
' -- ',
' :P9_CODUSUARIO_ALTA := :APP_USER;',
' :P9_FEC_ALTA        := SYSDATE;',
' :P9_NOM_REPORTA     := OC_USUARIOS.NOMBRE_USUARIO(:CODCIA,USER);',
'',
'',
'',
'exception ',
'when others then ',
'raise_application_error(-20100, ''error ''||dbms_utility.format_error_backtrace ||''h''||FUN_FOLIODENUNCIA);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(246609601163489875)
,p_internal_uid=>34270787366424909
);
