,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select apex_item.radiogroup(1,ROWID ||'':'')Selecionar,',
'       apex_item.checkbox2 (2,ROWID||'':'')Selecionar_procesar,',
'       ROWID RECORD_ID,',
'       CODCIA,',
'       CODEMPRESA,',
'       IDDENUNCIA,',
'       FOLIO_DENUNCIA,',
'       CODTIPOREPORTE,',
'       CODCANALDENUNCIA,',
'       FEC_REPORTE,',
'       CODCOMPORTAMIENTO,',
'       NUMPOLUNICO,',
'       MONTO_DENUNCIA,',
'       FEC_DETECCION,',
'       NOM_REPORTA,',
'       CORREO_ELECTRONICO,',
'       NOMBRE_PERSONA_REPORTADA||'' ''|| APELLIDO_PATERNO||'' ''|| APELLIDO_MATERNO   NOMBRE_PERSONA_REPORTADA,',
'       APELLIDO_PATERNO,',
'       APELLIDO_MATERNO,',
'       DESCRIPCION_DENUNCIA,',
'       CODUSUARIO_ALTA,',
'       FEC_ALTA,',
'       CODUSUARIO_MOD,',
'       FEC_MODIFICACION,',
'       ST_OPERACION,',
'       OBSERVACIONES',
'  from PLD_OPE_PREOCUPANTES',
'  WHERE (FOLIO_DENUNCIA = :P10_FOLIO_DENUNCIA OR :P10_FOLIO_DENUNCIA IS NULL)',
'AND (:P10_FECHA_DESDE IS NULL OR FEC_REPORTE >= TO_CHAR(TO_DATE(:P10_FECHA_DESDE, ''DD/MM/YYYY''), ''MM/DD/YYYY''))',
'AND (:P10_FECHA_HASTA IS NULL OR FEC_REPORTE <= TO_CHAR(TO_DATE(:P10_FECHA_HASTA, ''DD/MM/YYYY''), ''MM/DD/YYYY''))',
'',
'    AND ST_OPERACION IN (SELECT column_value',
'                           FROM TABLE(APEX_STRING.SPLIT(:P10_ST_OPERACION_INICIAL, '',''))',
'                            UNION',
'                         SELECT column_value',
'                           FROM TABLE(APEX_STRING.SPLIT(:P10_WS_ST_OPERACION, '','')))',
'  ORDER BY IDDENUNCIA DESC'))
