wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(246837467117746403)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Acceso'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	cAplicacion	        VARCHAR2(40);',
'	cUsuario	          VARCHAR2(40);',
'	cAcceso		          VARCHAR2(2);',
'	cSupervisor         VARCHAR2(1);',
'	Dummy		            NUMBER;',
'	--Id_Alerta	          ALERT	:= Find_Alert(''ALERTA''); ',
'BEGIN',
'	cUsuario	          := :app_user;',
'	cAplicacion	        := ''DETOPEPR''; -- Get_Application_Property(Current_Form_Name);',
'--	:GLOBAL.nCodCia := 1;',
' -- default_value (1,''global.ncodcia'');',
'	--',
'	--proc_TituloVentana(cAplicacion);',
'	--',
'	BEGIN',
'		SELECT U.Supervisor',
'		  INTO cSupervisor',
'		  FROM USUARIOS U',
'		 WHERE U.CodUsuario	= cUsuario',
'		   AND U.CodCia     = :CodCia;',
'	EXCEPTION',
'		WHEN NO_DATA_FOUND THEN',
'			 cSupervisor	:= ''N'';',
'	END;',
'',
'  IF cSupervisor = ''N'' THEN',
'		BEGIN',
'			SELECT ''SI''',
'			  INTO cAcceso',
'			  FROM USUARIOS U, ACCESOS_AUTORIZADOS A',
'			 WHERE U.CodCia     = :CodCia',
'			   AND U.CodUsuario	= cUsuario',
'			   AND A.CodGrupo	  = U.CodGrupo',
'			   AND A.CodCia     = :CodCia',
'			   AND A.CodAplica  = cAplicacion;',
'		EXCEPTION',
'			WHEN NO_DATA_FOUND THEN',
'				 cAcceso	:= ''NO'';',
'		END;',
'',
'		IF cAcceso = ''NO'' THEN',
'			raise_application_error(-20100,',
unistr('					   cUsuario || '' No est\00E1 autorizado para utilizar esta aplicaci\00F3n.  Consulte a su Administrador de Sistemas'');'),
'',
'		END IF;',
'	END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>34271892152424920
);
