wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(246838287000746412)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Actualiza Masivo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'',
'v_rowid rowid;',
'',
'cursor c_datos is ',
'select rowId record_id, ',
'        codcia,',
'        codempresa,',
'        iddenuncia,',
'        folio_denuncia,',
'        codtiporeporte,',
'        codcanaldenuncia,',
'        fec_reporte,',
'        codcomportamiento,',
'        numpolunico,',
'        monto_denuncia,',
'        fec_deteccion,',
'        nom_reporta,',
'        correo_electronico,',
'        nombre_persona_reportada,',
'        apellido_paterno,',
'        apellido_materno,',
'        descripcion_denuncia,',
'        codusuario_alta,',
'        fec_alta,',
'        codusuario_mod,',
'        fec_modificacion,',
'        st_operacion,',
'        observaciones',
'from PLD_OPE_PREOCUPANTES',
'where rowid = v_rowid;',
'',
' tCursor c_datos%rowtype;',
'',
'',
'begin',
'',
'FOR i IN 1 .. APEX_APPLICATION.G_F02.COUNT LOOP',
'',
'    begin',
'      select substr(APEX_APPLICATION.G_F02(i), 1, instr(APEX_APPLICATION.G_F02(i), '':'') - 1) p1',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := NUll;',
'    end;',
'',
'',
'  if v_rowid is not null then ',
'    open c_datos;',
'    loop',
'    fetch c_datos into tCursor;',
'    exit when c_datos%notfound;',
'     ',
'       begin',
'        update PLD_OPE_PREOCUPANTES',
'           set ST_OPERACION = :P10_WS_ESTATUS,',
'               OBSERVACIONES = :P10_WS_OBSERVACIONES,',
'               CODUSUARIO_MOD = :appe_user,',
'               FEC_MODIFICACION = sysdate',
'         where ROWID = tCursor.RECORD_ID; ',
'       end;',
'    ',
'   end loop;',
'   close c_datos;',
'  end if;',
' end loop;',
' :P10_WS_ESTATUS := null;',
' :P10_WS_OBSERVACIONES := NULL;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(247134355812807390)
,p_process_success_message=>unistr('Proceso de actualizaci\00F3n, concluido')
,p_internal_uid=>34272712035424929
);
