,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Registro Seleccionado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'nIDPOLIZA polizas.IDPOLIZA%type;',
'vUrl    varchar2(4000);',
'v_rowid rowid;',
'',
'lv_CODTIPOREPORTE          PLD_OPE_PREOCUPANTES.CODTIPOREPORTE%type;',
'lv_NUMPOLUNICO             PLD_OPE_PREOCUPANTES.NUMPOLUNICO%type;',
'lv_IDOPERACION             number(20);',
'lv_NOMBRE_REPORTADA        varchar2(200);',
'lv_APE_PATERNO_REPORTADA   varchar2(50);',
'lv_APE_MATERNO_REPORTADA   varchar2(50);',
'',
'',
'cNOMTIPOREPORTE     varchar2(400);',
'cNOMCANALDENUNCIA    varchar2(400);',
'cNOMCOMPORTAMIENTO  varchar2(400);',
'',
'cursor c_datos is ',
'select codcia,',
'        codempresa,',
'        iddenuncia,',
'        folio_denuncia,',
'        codtiporeporte,',
'        codcanaldenuncia,',
'        fec_reporte,',
'        codcomportamiento,',
'        numpolunico,',
'        monto_denuncia,',
'        fec_deteccion,',
'        nom_reporta,',
'        correo_electronico,',
'        nombre_persona_reportada,',
'        apellido_paterno,',
'        apellido_materno,',
'        descripcion_denuncia,',
'        codusuario_alta,',
'        fec_alta,',
'        codusuario_mod,',
'        fec_modificacion,',
'        st_operacion,',
'        observaciones',
'from PLD_OPE_PREOCUPANTES',
'where rowid = v_rowid;',
'',
' tCursor c_datos%rowtype;',
'',
'',
'begin',
' begin',
'      select substr(APEX_APPLICATION.G_x02, 1, instr(APEX_APPLICATION.G_x02, '':'') - 1) p1',
'         --    substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 1) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - instr(APEX_APPLICATION.G_x02, '':'', 1, 1) - 1) p3,',
'           --  substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - 1) p3,',
'             --substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - 1) p4,',
'            -- substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 5) - instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - 1) p5',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := NUll;',
'    end;',
'',
'  if v_rowid is not null then ',
'    open c_datos;',
'    loop',
'    fetch c_datos into tCursor;',
'    exit when c_datos%notfound;',
'',
'cNOMTIPOREPORTE     := OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''CATTPREPLD'',tcursor.CODTIPOREPORTE);',
'cNOMCANALDENUNCIA   := OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''CATCANALDN'',tcursor.CODCANALDENUNCIA);',
'cNOMCOMPORTAMIENTO  := OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''CATCOMPATI'',tcursor.CODCOMPORTAMIENTO);',
'',
'    apex_json.open_object;',
'',
'      apex_json.write(''codcia'',tcursor.codcia);',
'        apex_json.write(''codempresa'',tcursor.codempresa);',
'        apex_json.write(''iddenuncia'',tcursor.iddenuncia);',
'        apex_json.write(''folio_denuncia'',tcursor.folio_denuncia);',
'        apex_json.write(''codtiporeporte'',cNOMTIPOREPORTE); --tcursor.codtiporeporte);',
'        apex_json.write(''codcanaldenuncia'', cNOMCANALDENUNCIA); --tcursor.codcanaldenuncia);',
'        apex_json.write(''fec_reporte'',TO_CHAR(tcursor.fec_reporte,''DD/MM/RRRR''));',
'        apex_json.write(''codcomportamiento'', cNOMCOMPORTAMIENTO); --tcursor.codcomportamiento);',
'        apex_json.write(''numpolunico'',tcursor.numpolunico);',
'        apex_json.write(''monto_denuncia'',tcursor.monto_denuncia);',
'        apex_json.write(''fec_deteccion'',TO_CHAR(tcursor.fec_deteccion,''DD/MM/RRRR''));',
'        apex_json.write(''nom_reporta'',tcursor.nom_reporta);',
'        apex_json.write(''correo_electronico'',tcursor.correo_electronico);',
'        apex_json.write(''nombre_persona_reportada'',tcursor.nombre_persona_reportada);',
'        apex_json.write(''apellido_paterno'',tcursor.apellido_paterno);',
'        apex_json.write(''apellido_materno'',tcursor.apellido_materno);',
'        apex_json.write(''descripcion_denuncia'',tcursor.descripcion_denuncia);',
'        apex_json.write(''codusuario_alta'',tcursor.codusuario_alta);',
'        apex_json.write(''fec_alta'',tcursor.fec_alta);',
'        apex_json.write(''codusuario_mod'',tcursor.codusuario_mod);',
'        apex_json.write(''fec_modificacion'',tcursor.fec_modificacion);',
'        apex_json.write(''st_operacion'',tcursor.st_operacion);',
'        apex_json.write(''observaciones'',tcursor.observaciones);',
'         apex_json.write(''record_id'',v_rowid);',
'',
'',
' BEGIN',
'    SELECT P.IDPOLIZA',
'      INTO nIDPOLIZA',
'      FROM POLIZAS P',
'     WHERE P.NUMPOLUNICO = tcursor.NUMPOLUNICO',
'       AND P.CODCIA      = tcursor.CODCIA;',
'  EXCEPTION',
'    WHEN OTHERS THEN',
'        nIDPOLIZA := 0;',
'  END;',
'',
'  lv_CODTIPOREPORTE          := ''OIP'';',
'  lv_NUMPOLUNICO             := tcursor.numpolunico;',
'  lv_IDOPERACION             := 1;',
'  lv_NOMBRE_REPORTADA        := tcursor.nombre_persona_reportada;',
'  lv_APE_PATERNO_REPORTADA  :=  tcursor.apellido_paterno;',
'  lv_APE_MATERNO_REPORTADA  :=  tcursor.apellido_materno;',
'',
'BEGIN',
' SELECT APEX_PAGE.GET_URL  (p_page   => ''15'',',
'                            p_clear_cache => ''15'', ',
'                            p_items  => ''P15_P_IDPOLIZA,''||',
'                                        ''P15_P_CODTIPOREPORTE,''||',
'                                        ''P15_P_NUMPOLUNICO,''||',
'                                        ''P15_P_CODCIA,''||',
'                                        ''P15_P_IDOPERACION,''||',
'                                        ''P15_P_NOMBRE_REPORTADA,''||',
'                                        ''P15_P_APE_PATERNO_REPORTADA,''||',
'                                        ''P15_P_APE_MATERNO_REPORTADA'',',
'                            p_values =>  nIDPOLIZA||'',''||lv_CODTIPOREPORTE||'',''||lv_NUMPOLUNICO||'',''||tcursor.CODCIA||'',''||lv_IDOPERACION ||'',''||lv_NOMBRE_REPORTADA||'',''||lv_APE_PATERNO_REPORTADA||'',''||lv_APE_MATERNO_REPORTADA,',
'                            p_triggering_element => ''$("#CNSF")'') f_url_1',
' INTO vUrl',
' FROM DUAL;',
'END;',
'  apex_json.write(''url'', vUrl);',
'',
'',
'         apex_json.close_object;',
'    end loop;',
'    close c_datos;',
'  else ',
'    apex_json.write(''codcia'','''');',
'apex_json.write(''codempresa'','''');',
'apex_json.write(''iddenuncia'','''');',
'apex_json.write(''folio_denuncia'','''');',
'apex_json.write(''codtiporeporte'','''');',
'apex_json.write(''codcanaldenuncia'','''');',
'apex_json.write(''fec_reporte'','''');',
'apex_json.write(''codcomportamiento'','''');',
'apex_json.write(''numpolunico'','''');',
'apex_json.write(''monto_denuncia'','''');',
'apex_json.write(''fec_deteccion'','''');',
'apex_json.write(''nom_reporta'','''');',
'apex_json.write(''correo_electronico'','''');',
'apex_json.write(''nombre_persona_reportada'','''');',
'apex_json.write(''apellido_paterno'','''');',
'apex_json.write(''apellido_materno'','''');',
'apex_json.write(''descripcion_denuncia'','''');',
'apex_json.write(''codusuario_alta'','''');',
'apex_json.write(''fec_alta'','''');',
'apex_json.write(''codusuario_mod'','''');',
'apex_json.write(''fec_modificacion'','''');',
'apex_json.write(''st_operacion'','''');',
'apex_json.write(''observaciones'','''');',
'  apex_json.close_object;',
'  end if;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>34272128463424923
);
