,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select CODCIA,',
'       ID_PROCESO,',
'       IDPOLIZA,',
'       IDETPOL,',
'       TP_PERSONA,',
'       ORIGEN,',
'       CODCLIENTE,',
'       CODASEGURADO,',
'       IDFACTURA,',
'       IDTIPOSEG,',
'       COD_MONEDA,',
'       FORMPAGO,',
'       TIPO_PERSONA,',
'       CODACTIVIDAD,',
'       ASEGURADOS_EMI,',
'       ASEGURADOS_END,',
'       SUMAASEG_EMI,',
'       SUMAASEG_END,',
'       ST_RIESGO,',
'       OBSERVACIONES,',
'       FE_PROCESO,',
'       FE_HORA_PROCESO,',
'       FE_ACTUALIZACION,',
'       USUARIO_ACTUA,',
'       IMPTE_MOVTO_REG,',
'       FE_ALTA_REG,',
'       HISTORICO_MOVTOS_REG,',
'       IDENDOSO,',
'       TIPO_DOC_IDENTIFICACION,',
'       NUM_DOC_IDENTIFICACION,',
'          apex_item.radiogroup(1,ROWID ||'':'')Selecionar,',
'          apex_item.checkbox2 (2,ROWID||'':'')Selecionar_procesar',
'  from ADMON_ACTIVI',
'  where (IDPOLIZA = :P17_B_IDPOLIZA OR :P17_B_IDPOLIZA IS NULL)',
'    and (ST_RIESGO = :P17_B_ST_RIESGO OR :P17_B_ST_RIESGO IS NULL)',
'    and (TP_PERSONA = :P17_B_TP_PERSONA OR :P17_B_TP_PERSONA IS NULL)',
'    and (ORIGEN = :P17_B_ORIGEN OR :P17_B_ORIGEN IS NULL)',
'AND (:P17_FECHA_DESDE IS NULL OR FE_PROCESO >= TO_CHAR(TO_DATE(:P17_FECHA_DESDE, ''DD/MM/YYYY''), ''MM/DD/YYYY''))',
'AND (:P17_FECHA_HASTA IS NULL OR FE_PROCESO <= TO_CHAR(TO_DATE(:P17_FECHA_HASTA, ''DD/MM/YYYY''), ''MM/DD/YYYY''))',
'  order by FE_PROCESO DESC',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P17_B_IDPOLIZA,P17_B_TP_PERSONA,P17_B_ORIGEN,P17_FECHA_DESDE,P17_FECHA_HASTA,P17_B_ST_RIESGO_INICIAL,P17_B_ST_RIESGO'
