'var seqid = $(elem).parent().find("input[name=''f01'']").val();',
'',
'console.log(''marcado '' + marcado);',
'console.log(''seqid '' + seqid);',
'',
'// Enviar el cambio a PL/SQL',
'apex.server.process("Registro Seleccionado", {',
'    x01: marcado,',
'    x02: seqid',
'}, {',
'    success: function(data) {',
'        $s("P17_NOMBRE", data.nombre);',
'        $s("P17_OBSERVACIONES", data.observaciones);',
'        $s("P17_D_OBSERVACIONES", data.observaciones);',
'        $s("P17_POLIZA", data.idpoliza);',
'        $s("P17_DETALLE_POLIZA", data.idetpol);',
'        $s("P17_TIPO_SEGURO", data.idtiposeg);',
'        $s("P17_FACTURA", data.idfactura);',
'        $s("P17_MONEDA", data.cod_moneda);',
'        $s("P17_TIPO_PERSONA", data.tipo_persona);',
'        $s("P17_FORMA_PAGO", data.formpago);',
'        $s("P17_IMPORTE", data.impte_movto_reg);',
'        $s("P17_TIPO_MOVIMIENTO", data.tp_persona);',
'        $s("P17_ORIGEN", data.origen);',
'        $s("P17_D_NOMBRE", data.nombre);',
'        $s("P17_TIPO_DCTO", data.tipo_doc_identificacion);',
'        $s("P17_ASEGURADO", data.ws_asegurado);',
'        $s("P17_NUM_DCTO", data.num_doc_identificacion);',
'        $s("P17_ACTIVIDAD", data.nomactividad);',
'        $s("P17_RIESGO_ACTIVIDAD", data.riesgo_actividad);',
'        $s("P17_ESTATUS", data.st_riesgo);',
'        $s("P17_NUM_ENDOSO", data.idendoso);',
'        $s("P17_SUMA_ASEGURADA_EMISION", data.sumaaseg_emi);',
'        $s("P17_ASEGURADOS_EMISION", data.asegurados_emi);',
'        $s("P17_SUMA_ASEGURADA_ENDOSO", data.sumaaseg_end);',
