wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(248122783852197993)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Actualiza Masivo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'',
'  v_rowid rowid;',
'',
'    cursor c_datos is ',
'  select rowid record_Id, ',
'       CODCIA,',
'       ID_PROCESO,',
'       IDPOLIZA,',
'       IDETPOL,',
'       TP_PERSONA,',
'       ORIGEN,',
'       CODCLIENTE,',
'       CODASEGURADO,',
'       IDFACTURA,',
'       IDTIPOSEG,',
'       COD_MONEDA,',
'       FORMPAGO,',
'       TIPO_PERSONA,',
'       CODACTIVIDAD,',
'       ASEGURADOS_EMI,',
'       ASEGURADOS_END,',
'       SUMAASEG_EMI,',
'       SUMAASEG_END,',
'       ST_RIESGO,',
'       OBSERVACIONES,',
'       FE_PROCESO,',
'       FE_HORA_PROCESO,',
'       FE_ACTUALIZACION,',
'       USUARIO_ACTUA,',
'       IMPTE_MOVTO_REG,',
'       FE_ALTA_REG,',
'       HISTORICO_MOVTOS_REG,',
'       IDENDOSO,',
'       TIPO_DOC_IDENTIFICACION,',
'       NUM_DOC_IDENTIFICACION',
'  from ADMON_ACTIVI',
'  where rowid = v_rowid; ',
'',
'  tCursor c_datos%rowtype;',
'   ',
'   ',
'begin',
'FOR i IN 1 .. APEX_APPLICATION.G_F02.COUNT LOOP',
'',
'  begin',
'      select substr(APEX_APPLICATION.G_F02(i), 1, instr(APEX_APPLICATION.G_F02(i), '':'') - 1) p1',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := NUll;',
'    end;',
'',
'    if v_rowid is not null then ',
'    open c_datos;',
'    loop',
'    fetch c_datos into tCursor;',
'    exit when c_datos%notfound;',
'',
'',
'      BEGIN',
'        update ADMON_ACTIVI',
'           set ST_RIESGO = :P17_WS_ESTATUS,',
'               OBSERVACIONES = OBSERVACIONES||'' - ''||:P17_WS_OBSERVACIONES',
'         WHERE ROWID = tCursor.RECORD_ID;',
'      END;',
'',
'    end loop;',
'    close c_datos;',
'    end if;',
'END LOOP;',
':P17_WS_OBSERVACIONES := '''';',
':P17_WS_ESTATUS := '''';',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(247771564630529981)
,p_internal_uid=>35557208886876510
);
end;
/
begin
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(248124154005198006)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Periodos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	W_FE_INICIO  DATE;',
'	W_FE_FIN     DATE;',
'	W_IMPORTE    NUMBER;',
'	W_CAGE_CD_CLAVE_SEG SAI_CAT_GENERAL.CAGE_CD_CLAVE_SEG%TYPE;',
'  W_CAGE_CD_CLAVE_TER SAI_CAT_GENERAL.CAGE_CD_CLAVE_TER%TYPE;',
'  W_PROCESADOS NUMBER;',
'  dummy        NUMBER;',
'  ',
'   ',
'CURSOR FACTURAS IS',
'  SELECT F.CODCIA,',
'         F.IDPOLIZA,',
'         F.IDETPOL,',
'         F.CODCLIENTE,',
'         F.COD_MONEDA,',
'         F.FORMPAGO,',
'         SUM(F.MONTO_FACT_LOCAL) IMPORTE',
'    FROM FACTURAS F',
'   WHERE F.STSFACT = ''PAG''',
'     AND F.FORMPAGO = ''EFEC''',
'     AND F.FECVENC  BETWEEN W_FE_INICIO ',
'                        AND W_FE_FIN',
'   GROUP BY F.CODCIA,',
'            F.IDPOLIZA,',
'            F.IDETPOL,',
'            F.CODCLIENTE,',
'            F.COD_MONEDA,',
'            F.FORMPAGO',
'  ;',
'--',
'BEGIN',
'',
'     W_FE_INICIO  := '''';',
'     W_FE_FIN     := '''';',
'     W_IMPORTE    := 0;',
'     W_PROCESADOS := 0;',
'     BEGIN',
'       SELECT TO_DATE(A.CAGE_VALOR_CORTO||''01'',''YYYYMMDD''),',
'              LAST_DAY(TO_DATE(A.CAGE_VALOR_CORTO||''01'',''YYYYMMDD'')),',
'              CAGE_CD_CLAVE_SEG,',
'              CAGE_CD_CLAVE_TER',
'         INTO W_FE_INICIO,',
'              W_FE_FIN,',
'              W_CAGE_CD_CLAVE_SEG,',
'              W_CAGE_CD_CLAVE_TER',
'         FROM SAI_CAT_GENERAL A   ',
'        WHERE A.CAGE_CD_CATALOGO = 8',
'          AND A.CAGE_VALOR_CORTO = :P17_PERIODOS',
'          AND A.CAGE_CD_ESTATUS  = ''A'';',
'     EXCEPTION',
'       WHEN OTHERS THEN ',
'            RAISE_APPLICATION_ERROR(-2100, ''PERIODO CON PROBLEMAS'');',
'     END;',
'     --',
'	   FOR F IN FACTURAS LOOP',
'         IF F.IMPORTE >= 1000000 THEN',
'            --',
'            INSERT INTO ADMON_ACTIVI ',
'              (CODCIA,                              ID_PROCESO,',
'               IDPOLIZA,                            IDETPOL,',
'               TP_PERSONA,                          ORIGEN,',
'               CODCLIENTE,                          CODASEGURADO,',
'               IDFACTURA,                           IDTIPOSEG,',
'               COD_MONEDA,                          FORMPAGO,',
'               TIPO_PERSONA,                        CODACTIVIDAD,',
'               ASEGURADOS_EMI,                      ASEGURADOS_END,',
'               SUMAASEG_EMI,                        SUMAASEG_END,',
'               ST_RIESGO,                           OBSERVACIONES,',
'               FE_PROCESO,                          FE_HORA_PROCESO,',
'               FE_ACTUALIZACION,                    USUARIO_ACTUA,',
'               IMPTE_MOVTO_REG,                     FE_ALTA_REG,',
'               HISTORICO_MOVTOS_REG',
'              )',
'            VALUES',
'              (F.CODCIA,                            1,',
'               F.IDPOLIZA,                          F.IDETPOL,  ',
'               ''ACTIVI'',                            ''EFELIM'',',
'               F.CODCLIENTE,                        '''',',
'               '''',                                  '''',',
'               F.COD_MONEDA,                        F.FORMPAGO,',
'               '''',                                  '''',',
'               0,                                   0,',
'               0,                                   0,',
'               ''PEND'',                              ''POLIZA CON ACUMULADO EN ''||:P17_PERIODOS||'' MAYOR O IGUAL A 1,000,000'',',
'               TRUNC(SYSDATE),                      SYSDATE,',
'               '''',                                  :APP_USER,',
'               F.IMPORTE,                           '''',',
'               ''''',
'               );',
'            --',
'            COMMIT;',
'            --   ',
'            W_PROCESADOS := W_PROCESADOS + 1;',
'         END IF;',
'         --',
'     END LOOP;',
'     --',
'--  END IF;',
'  --',
'  IF W_PROCESADOS = 0 THEN',
'  	 --',
'       apex_application.g_print_success_message := ''No hubo registros a procesar'';',
'     --',
'  ELSE',
'  apex_application.g_print_success_message := ''Proceso Terminado,Procesados - ''||W_PROCESADOS;',
'  ',
'  END IF;',
'',
'END;',
'--',
'    ',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(248123469707197999)
,p_internal_uid=>35558579039876523
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(257021608846293110)
