wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(248288212112074239)
,p_event_id=>wwv_flow_imp.id(248287720056074237)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var elem = this.triggeringElement || event.target || this;  // fallback robusto',
'',
'console.log($(elem).val());',
'',
'var marcado = $(elem).is('':checked'');',
'var seqid = $(elem).parent().find("input[name=''f01'']").val();',
'',
'console.log(''marcado '' + marcado);',
'console.log(''seqid '' + seqid);',
'',
'// Enviar el cambio a PL/SQL',
'apex.server.process("Registro Seleccionado", {',
'    x01: marcado,',
'    x02: seqid',
'}, {',
'    success: function(data) {',
'     // alert(data.observaciones )',
'$s("P18_CODIGO_NOMBRE",data.codcliente);',
'$s("P18_CODACTIVIDAD",data.codactividad);',
'$s("P18_CODASEGURADO",data.codasegurado);',
'$s("P18_CODIGO_ESTATUS",data.cod_estatus);',
'',
'$s("P18_NOMBRE",data.nombre);',
'$s("P18_OBSERVACIONES", data.observaciones);',
'$s("P18_D_OBSERVACIONES", data.observaciones);',
'$s("P18_POLIZA",data.idpoliza);',
'$s("P18_DETALLE_POLIZA",data.idetpol);',
'$s("P18_TIPO_SEGURO",data.idtiposeg);',
'$s("P18_FACTURA",data.idfactura);',
'$s("P18_MONEDA",data.cod_moneda);',
'$s("P18_TIPO_PERSONA",data.tipo_persona);',
'$s("P18_FORMA_PAGO",data.formpago);',
'$s("P18_IMPORTE",data.impte_movto_reg);',
'$s("P18_TIPO_MOVIMIENTO",data.tp_persona);',
'$s("P18_ORIGEN",data.origen);',
'$s("P18_D_NOMBRE",data.nombre);',
'$s("P18_TIPO_DCTO",data.tipo_doc_identificacion);',
'$s("P18_ASEGURADO",data.ws_asegurado);',
'$s("P18_NUM_DCTO",data.num_doc_identificacion);',
'$s("P18_ACTIVIDAD",data.nomactividad);',
'$s("P18_RIESGO_ACTIVIDAD",data.riesgo_actividad);',
'$s("P18_ESTATUS",data.st_riesgo);',
'$s("P18_NUM_ENDOSO",data.idendoso);',
'',
'$s("P18_SUMA_ASEGURADA_EMISION",data.sumaaseg_emi);',
'$s("P18_ASEGURADOS_EMISION",data.asegurados_emi);',
'$s("P18_SUMA_ASEGURADA_ENDOSO",data.sumaaseg_end);',
'$s("P18_ASEGURADOS_ENDOSO",data.asegurados_end);',
'$s("P18_FECHA_PROCESO",data.fe_hora_proceso);',
'$s("P18_USUARIO",data.usuario_actua);',
'$s("P18_FECHA_ACTUALIZACION",data.fe_actualizacion);',
'$s("P18_URL", data.url);',
'',
'    }',
'});'))
);
