wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(248284066290074231)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Registro Seleccionado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'  v_numpol    POLIZAS.NUMPOLUNICO%type;',
'',
'  lv_CODTIPOREPORTE          PLD_OPE_PREOCUPANTES.CODTIPOREPORTE%type;',
'lv_NUMPOLUNICO             PLD_OPE_PREOCUPANTES.NUMPOLUNICO%type;',
'lv_IDOPERACION             number(20);',
'lv_NOMBRE_REPORTADA        varchar2(200);',
'lv_APE_PATERNO_REPORTADA   varchar2(50);',
'lv_APE_MATERNO_REPORTADA   varchar2(50);',
'',
'  v_rowid rowid;',
'  vUrl    varchar2(4000);',
'  ',
'  v_ws_nombre varchar2(400);',
'  WS_TP_PERSONA varchar2(400);',
'  WS_ORIGEN varchar2(400);',
'  WS_ST_RIESGO varchar2(400);',
'',
'  cursor c_datos is ',
'  select CODCIA,',
'        ID_PROCESO,',
'       IDPOLIZA,',
'       IDETPOL,',
'       TP_PERSONA,',
'       ORIGEN,',
'       CODCLIENTE,',
'       CODASEGURADO,',
'       IDFACTURA,',
'       IDTIPOSEG,',
'       COD_MONEDA,',
'       FORMPAGO,',
'       TIPO_PERSONA,',
'       CODACTIVIDAD,',
'       ASEGURADOS_EMI,',
'       ASEGURADOS_END,',
'       SUMAASEG_EMI,',
'       SUMAASEG_END,',
'       ST_RIESGO,',
'       OBSERVACIONES,',
'       FE_PROCESO,',
'       FE_HORA_PROCESO,',
'       FE_ACTUALIZACION,',
'       USUARIO_ACTUA,',
'       IMPTE_MOVTO_REG,',
'       FE_ALTA_REG,',
'       HISTORICO_MOVTOS_REG,',
'       IDENDOSO,',
'       TIPO_DOC_IDENTIFICACION,',
'       NUM_DOC_IDENTIFICACION',
'  from ADMON_ACTIVI_RELEVANTES',
'  where rowid = v_rowid; ',
'',
'  tCursor c_datos%rowtype;',
'',
'begin',
'',
'',
'  begin',
'      select substr(APEX_APPLICATION.G_x02, 1, instr(APEX_APPLICATION.G_x02, '':'') - 1) p1',
'     into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := NUll;',
'    end;',
'',
'  if v_rowid is not null then ',
'    open c_datos;',
'    loop',
'    fetch c_datos into tCursor;',
'    exit when c_datos%notfound;',
'',
'    IF tCursor.TP_PERSONA = ''PRODUC'' THEN',
'	 v_ws_nombre := tCursor.IDTIPOSEG||'' - ''||OC_TIPOS_DE_SEGUROS.TIPO_DE_SEGURO(tCursor.CODCIA,tCursor.CODCIA,tCursor.IDTIPOSEG);',
'ELSIF tCursor.TP_PERSONA = ''ACTIVI'' THEN',
'	v_ws_nombre := tCursor.CODACTIVIDAD||'' - ''||OC_ACTIVIDADES_ECONOMICAS.DESCRIPCION(tCursor.CODACTIVIDAD);',
'ELSE',
'   v_ws_nombre := OC_CLIENTES.NOMBRE_CLIENTE(tCursor.CODCLIENTE);',
'END IF;',
'',
'begin  ',
'SELECT DESCVALLST',
'  INTO WS_TP_PERSONA',
'  FROM VALORES_DE_LISTAS ',
' WHERE CODLISTA = ''CATTPPER''',
'   AND CODVALOR = tcursor.TP_PERSONA;',
' exception ',
' when others then ',
' WS_TP_PERSONA := null;',
'end;',
'',
'begin',
'SELECT DESCVALLST',
'  INTO WS_ORIGEN',
'  FROM VALORES_DE_LISTAS ',
' WHERE CODLISTA = ''CATORIAC''',
'   AND CODVALOR = tcursor.ORIGEN;',
'exception ',
'when others then ',
'  WS_ORIGEN := null;',
'end;',
'',
'begin ',
'SELECT DESCVALLST',
'  INTO WS_ST_RIESGO',
'  FROM VALORES_DE_LISTAS ',
' WHERE CODLISTA = ''CATSTRIE''',
'   AND CODVALOR = tcursor.ST_RIESGO;',
' exception ',
' when others then ',
' WS_ST_RIESGO := null;',
'end;',
'     apex_json.open_object;',
'    apex_json.write(''codcia'',tcursor.codcia);',
'    apex_json.write(''nombre'',v_ws_nombre);',
'    apex_json.write(''id_proceso'',tcursor.id_proceso);',
'    apex_json.write(''idpoliza'',tcursor.idpoliza);',
'    apex_json.write(''idetpol'',tcursor.idetpol);',
'    apex_json.write(''tp_persona'', WS_TP_PERSONA); --tcursor.tp_persona);',
'    apex_json.write(''origen'',WS_ORIGEN ); --tcursor.origen);',
'    apex_json.write(''codcliente'',tcursor.codcliente);',
'    apex_json.write(''codasegurado'',tcursor.codasegurado);',
'    apex_json.write(''ws_asegurado'', OC_ASEGURADO.NOMBRE_ASEGURADO(tcursor.CODCIA,tcursor.CODCIA, tcursor.CODASEGURADO));',
'',
'    apex_json.write(''idfactura'',tcursor.idfactura);',
'    apex_json.write(''idtiposeg'',tcursor.idtiposeg);',
'    apex_json.write(''cod_moneda'',tcursor.cod_moneda);',
'    apex_json.write(''formpago'',tcursor.formpago);',
'    apex_json.write(''tipo_persona'',tcursor.tipo_persona);',
'    apex_json.write(''codactividad'',tcursor.CODACTIVIDAD);',
'    apex_json.write(''nomactividad'',OC_ACTIVIDADES_ECONOMICAS.DESCRIPCION(tcursor.CODACTIVIDAD));',
'    apex_json.write(''riesgo_actividad'',OC_ACTIVIDADES_ECONOMICAS.TIPORIESGO(tcursor.CODACTIVIDAD));',
'',
'    apex_json.write(''asegurados_emi'',tcursor.asegurados_emi);',
'    apex_json.write(''asegurados_end'',tcursor.asegurados_end);',
'    apex_json.write(''sumaaseg_emi'',tcursor.sumaaseg_emi);',
'    apex_json.write(''sumaaseg_end'',tcursor.sumaaseg_end);',
'    apex_json.write(''cod_estatus'', tcursor.st_riesgo);',
'    apex_json.write(''st_riesgo'', WS_ST_RIESGO); --tcursor.st_riesgo);',
'    apex_json.write(''observaciones'',tcursor.observaciones);',
'    apex_json.write(''fe_proceso'',tcursor.fe_proceso);',
'    apex_json.write(''fe_hora_proceso'', to_char(tcursor.fe_hora_proceso,''dd/mm/rrrr''));',
'    apex_json.write(''fe_actualizacion'',to_char(tcursor.fe_actualizacion,''dd/mm/rrrr''));',
'    apex_json.write(''usuario_actua'',tcursor.usuario_actua);',
'    apex_json.write(''impte_movto_reg'',tcursor.impte_movto_reg);',
'    apex_json.write(''fe_alta_reg'',tcursor.fe_alta_reg);',
'    apex_json.write(''historico_movtos_reg'',tcursor.historico_movtos_reg);',
'    apex_json.write(''idendoso'',tcursor.idendoso);',
'    apex_json.write(''tipo_doc_identificacion'',tcursor.tipo_doc_identificacion);',
'    apex_json.write(''num_doc_identificacion'',tcursor.num_doc_identificacion);',
'',
'  BEGIN',
'    SELECT P.NUMPOLUNICO',
'      INTO v_numpol',
'      FROM POLIZAS P',
'     WHERE P.IDPOLIZA = tcursor.IDPOLIZA',
'       AND P.CODCIA   =  tcursor.CODCIA;',
'  EXCEPTION',
'    WHEN OTHERS THEN',
'         v_numpol := tcursor.IDPOLIZA;',
'  END;',
'',
'lv_CODTIPOREPORTE          := ''OR'';',
'lv_IDOPERACION             := 1;',
'',
'    BEGIN',
' SELECT APEX_PAGE.GET_URL  (p_page   => ''15'',',
'                            p_clear_cache => ''15'', ',
'                            p_items  => ''P15_P_IDPOLIZA,''||',
'                                        ''P15_P_CODTIPOREPORTE,''||',
'                                        ''P15_P_NUMPOLUNICO,''||',
'                                        ''P15_P_CODCIA,''||',
'                                        ''P15_P_IDOPERACION,''||',
'                                        ''P15_P_NOMBRE_REPORTADA,''||',
'                                        ''P15_P_APE_PATERNO_REPORTADA,''||',
'                                        ''P15_P_APE_MATERNO_REPORTADA'',',
'                            p_values =>  tcursor.IDPOLIZA||'',''||lv_CODTIPOREPORTE||'',''||v_numpol||'',''||tcursor.CODCIA||'',''||lv_IDOPERACION ||'',''||lv_NOMBRE_REPORTADA||'',''||lv_APE_PATERNO_REPORTADA||'',''||lv_APE_MATERNO_REPORTADA,',
'                            p_triggering_element => ''$("#CNSF")'') f_url_1',
' INTO vUrl',
' FROM DUAL;',
'END;',
'  apex_json.write(''url'', vUrl);',
'',
'',
'    apex_json.close_object;',
'    end loop;',
'    close c_datos;',
'   else ',
' apex_json.open_object;',
'   apex_json.write(''codcia'','''');',
'   apex_json.write(''nombre'','''');',
'apex_json.write(''id_proceso'','''');',
'apex_json.write(''idpoliza'','''');',
'apex_json.write(''idetpol'','''');',
'apex_json.write(''tp_persona'','''');',
'apex_json.write(''origen'','''');',
'apex_json.write(''codcliente'','''');',
'apex_json.write(''codasegurado'','''');',
'apex_json.write(''idfactura'','''');',
'apex_json.write(''idtiposeg'','''');',
'apex_json.write(''cod_moneda'','''');',
'apex_json.write(''formpago'','''');',
'apex_json.write(''tipo_persona'','''');',
'apex_json.write(''codactividad'','''');',
'apex_json.write(''asegurados_emi'','''');',
'apex_json.write(''asegurados_end'','''');',
'apex_json.write(''sumaaseg_emi'','''');',
'apex_json.write(''sumaaseg_end'','''');',
'apex_json.write(''st_riesgo'','''');',
'apex_json.write(''observaciones'','''');',
'apex_json.write(''fe_proceso'','''');',
'apex_json.write(''fe_hora_proceso'','''');',
'apex_json.write(''fe_actualizacion'','''');',
'apex_json.write(''usuario_actua'','''');',
'apex_json.write(''impte_movto_reg'','''');',
'apex_json.write(''fe_alta_reg'','''');',
'apex_json.write(''historico_movtos_reg'','''');',
'apex_json.write(''idendoso'','''');',
'apex_json.write(''tipo_doc_identificacion'','''');',
'apex_json.write(''num_doc_identificacion'','''');',
' apex_json.close_object;',
'   end if; ',
'',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>35718491324752748
);
end;
