,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Preparar Url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'  APEX_UTIL.PREPARE_URL(',
'    p_url => ''f?p='' || :APP_ID || '':0:'' || :APP_SESSION || '':APPLICATION_PROCESS=GET_FILE_APEX:::FILE_ID:&P19_FILE_ID.'',',
'    p_checksum_type => ''SESSION'') AS secure_url',
'INTO :P19_URL',
