wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(248331052666579289)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Registro Seleccionado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'',
'lv_NOMBRE_REPORTADA        varchar2(200);',
'lv_APE_PATERNO_REPORTADA   varchar2(50);',
'lv_APE_MATERNO_REPORTADA   varchar2(50);',
'',
'vUrl    varchar2(4000);',
'',
'v_rowid rowid;',
'',
'cursor c_datos is ',
'select apex_item.radiogroup(1,ROWID ||'':'')Selecionar,',
'        CODCIA,',
'       IDOPERACION,',
'       CODTIPOREPORTE,',
'       ID_PERIODO,',
'       FOLIO,',
'       COD_ORGANO_SUPER,',
'       ID_OBLIGADO,',
'       ID_LOCALIDAD,',
'       ID_SUCURSAL,',
'       ID_TIP_OPERACION,',
'       COD_INSTRU_MONEDA,',
'       NUMPOLUNICO,',
'       NUMCUENTABANCARIA,',
'       ID_OPE_IMSS,',
'       MONTO,',
'       COD_MONEDA,',
'       FEC_OPERACION,',
'       COD_NACIONALIDAD,',
'       TIPO_PERSONA,',
'       RAZONSOCIAL,',
'       NOMBRE_REPORTADA,',
'       APE_PATERNO_REPORTADA,',
'       APE_MATERNO_REPORTADA,',
'       NUM_TRIBUTARIO,',
'       CURP,',
'       FECNACIMIENTO,',
'       DIRECRES,',
'       CODPAIS,',
'       CODESTADO,',
'       CODCIUDAD,',
'       CODMUNICIPIO,',
'       CODIGO_POSTAL,',
'       CODIGO_COLONIA,',
'       TELRES,',
'       CODACTIVIDAD,',
'       NOM_AGE_APO,',
'       APE_PATERNO_AGE_APO,',
'       APE_MATERNO_AGE_APO,',
'       NUM_TRIBUTARIO_AGE_APO,',
'       CURP_AGE_APO,',
'       NUM_CONSECUTIVO,',
'       CVE_OBLIGADO,',
'       NOM_TITULAR,',
'       NOM_TITULAR||'' ''||APE_PATERNO_TITULAR||'' ''|| APE_MATERNO_TITULAR NOMTITULAR,',
'       APE_PATERNO_TITULAR,',
'       APE_MATERNO_TITULAR,',
'       DESCRIPCION_DENUNCIA,',
'       RAZONES,',
'       CODUSUARIO_ALTA,',
'       FEC_ALTA',
'  from PLD_REP_OPERACIONES',
'  where rowid = v_rowid;',
'',
'  ',
' tCursor c_datos%rowtype;',
'',
'begin',
' begin',
'      select substr(APEX_APPLICATION.G_x02, 1, instr(APEX_APPLICATION.G_x02, '':'') - 1) p1',
'         --    substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 1) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - instr(APEX_APPLICATION.G_x02, '':'', 1, 1) - 1) p3,',
'           --  substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - 1) p3,',
'             --substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - 1) p4,',
'            -- substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 5) - instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - 1) p5',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := NUll;',
'    end;',
'',
'  if v_rowid is not null then ',
'    open c_datos;',
'    loop',
'    fetch c_datos into tCursor;',
'    exit when c_datos%notfound;',
'       apex_json.open_object;',
'       apex_json.write(''descripcion_denuncia'', tcursor.descripcion_denuncia);',
'       apex_json.write(''codcia'',tcursor.codcia);',
'       apex_json.write(''idoperacion'',tcursor.idoperacion);',
'',
'           BEGIN',
'           SELECT APEX_PAGE.GET_URL  (p_page   => ''16'',',
'                            p_clear_cache => ''16'', ',
'                            p_items  => ''P16_CODCIA,''||',
'                                        ''P16_IDOPERACION,''||',
'                                        ''P16_EDITAR,'',',
'                            p_values =>  tcursor.CODCIA||'',''||tcursor.IDOPERACION ||'',''||''S'',',
'                            p_triggering_element => ''$("#Detalle_Operacion")'') f_url_1',
' INTO vUrl',
' FROM DUAL;',
'/* SELECT APEX_PAGE.GET_URL  (p_page   => ''15'',',
'                            p_clear_cache => ''15'', ',
'                            p_items  => ''P15_P_IDPOLIZA,''||',
'                                        ''P15_P_CODTIPOREPORTE,''||',
'                                        ''P15_P_NUMPOLUNICO,''||',
'                                        ''P15_P_CODCIA,''||',
'                                        ''P15_P_IDOPERACION,''||',
'                                        ''P15_P_NOMBRE_REPORTADA,''||',
'                                        ''P15_P_APE_PATERNO_REPORTADA,''||',
'                                        ''P15_P_APE_MATERNO_REPORTADA'',',
'                            p_values =>  NULL||'',''||NULL||'',''||NULL||'',''||tcursor.CODCIA||'',''||tcursor.IDOPERACION ||'',''||lv_NOMBRE_REPORTADA||'',''||lv_APE_PATERNO_REPORTADA||'',''||lv_APE_MATERNO_REPORTADA,',
'                            p_triggering_element => ''$("#Detalle_Operacion")'') f_url_1',
' INTO vUrl',
' FROM DUAL;*/',
'END;',
'  apex_json.write(''url'', vUrl);',
'',
'       apex_json.close_object;',
'    end loop;',
'    close c_datos;',
'  else ',
'       apex_json.open_object;',
'       apex_json.write(''descripcion_denuncia'','''');',
'       apex_json.write(''codcia'','''');',
'       apex_json.write(''idoperacion'','''');',
'       apex_json.close_object;',
'  end if;',
'exception ',
'when others then ',
'       apex_json.open_object;',
'       apex_json.write(''descripcion_denuncia'','''');',
'       apex_json.write(''codcia'','''');',
'       apex_json.write(''idoperacion'','''');',
'       apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>35765477701257806
);
end;
