prompt --application/pages/page_00020
begin
wwv_flow_imp_page.create_page(
 p_id=>20
,p_name=>unistr('Administraci\00F3n de Listas Negras')
,p_alias=>unistr('ADMINISTRACI\00D3N-DE-LISTAS-NEGRAS')
,p_step_title=>unistr('Administraci\00F3n de Listas Negras')
,p_reload_on_submit=>'A'
,p_warn_on_unsaved_changes=>'N'
,p_first_item=>'AUTO_FIRST_ITEM'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Espera a que la p\00E1gina est\00E9 lista'),
'$(document).ready(function () {',
'  // Delegar evento change sobre radio buttons dentro del reporte',
'  $("#Lista").on("change", "input[name=''f01'']", function (event) {',
'    ',
