 p_id=>wwv_flow_imp.id(248335304237579332)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Imprimir'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_context apex_exec.t_context;',
'    l_export  apex_data_export.t_export;',
'    WI_ARCHIVO_REPORTE      VARCHAR2(4000);',
'    W_LINEA_REPORTE         VARCHAR2(4000);',
'    cCadena         VARCHAR2(4000);',
'    nLinea          NUMBER; ',
'    cCodUser        VARCHAR2(30); ',
'    cNomArchivo     VARCHAR2(1000);',
'    cCopy           BOOLEAN;  ',
'',
'    C_REPORTE VARCHAR2(4000) := ''',
'        SELECT ID_LISTA,',
'               TP_MOVIMIENTO,',
'               DESCR_TP_MOVIMIENTO,',
'               TO_CHAR(FEC_MOVIMIENTO,''''DD/MM/YYYY'''') AS FEC_MOVIMIENTO,',
'               LISTA_ORIGEN,',
'               OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''''LISTAO'''',LISTA_ORIGEN) AS NOM_LISTA_ORIGEN,',
'               TO_CHAR(FEC_COMUNICADO,''''DD/MM/YYYY'''') AS FEC_COMUNICADO,',
'               TIPO_PERSONA_CNSF,',
'               OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''''TIPPCN'''',TIPO_PERSONA_CNSF) AS NOM_TIPO_PERS_CNSF,',
'               NOMBRE_1,',
'               NOMBRE_2,',
'               NOMBRE_3,',
'               NOMBRE_4,',
'               NOMBRE_5,',
'               FEC_NACIMIENTO,',
'               PAIS_PROCEDENCIA,',
'               OC_PAIS.BUSCA_CLAVE_CNSF(PAIS_PROCEDENCIA) AS CVE_PAIS_CNSF,',
'               OC_PAIS.NOMBRE_PAIS(PAIS_PROCEDENCIA) AS NOM_PAIS_PROCEDENCIA,',
'               ALIAS_1,',
'               ALIAS_2,',
'               ALIAS_3,',
'               ALIAS_4,',
'               ALIAS_5,',
'               ALIAS_6,',
'               ALIAS_7,',
'               ALIAS_8,',
'               ALIAS_9,',
'               ALIAS_10,',
'               COD_NACIONALIDAD,',
'               OC_VALORES_DE_LISTAS.BUSCA_CLAVE_CNSF(''''NACION'''',COD_NACIONALIDAD) AS CVE_NACIONALIDAD_CNSF,',
'               OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''''NACION'''',COD_NACIONALIDAD) AS NOM_NACIONALIDAD,',
'               ID_PASAPORTE,',
'               ID_NACIONAL,',
'               DIRECCION,',
'               FEC_ADHESION,',
'               OBSERVACIONES,',
'               CODUSUARIO_ALTA,',
'               TO_CHAR(FEC_ALTA,''''DD/MM/YYYY'''') AS FEC_ALTA',
'          FROM PLD_LISTAS_CNSF A',
'         WHERE (A.FEC_MOVIMIENTO BETWEEN TO_DATE(''''''||:P20_FECHA_DESDE_MOVIMIENTO ||'''''',''''DD/MM/YYYY'''') AND TO_DATE(''''''||:P20_FECHA_HASTA_MOVIMIENTO||'''''',''''DD/MM/YYYY''''))''||',
'             '' OR (A.FEC_COMUNICADO BETWEEN TO_DATE(''''''||:P20_FECHA_DESDE_COMUNICADO ||'''''',''''DD/MM/YYYY'''') AND TO_DATE(''''''||:P20_FECHA_HASTA_COMUNICADO||'''''',''''DD/MM/YYYY''''));'';',
'',
'    BEGIN',
'',
'        IF (:P20_FECHA_DESDE_MOVIMIENTO IS NOT NULL AND :P20_FECHA_HASTA_MOVIMIENTO IS NOT NULL )',
'            OR (:P20_FECHA_DESDE_COMUNICADO IS NOT NULL AND :P20_FECHA_HASTA_COMUNICADO IS NOT NULL ) THEN',
'',
'                htp.p(''<style>',
'                body { cursor: busy !important; }',
'                </style>'');',
'',
'                :P20_TI_FE_INICIO := TO_CHAR(SYSDATE,''DD/MM/YYYY HH24:MI:SS'');',
'',
'                -- 1. Abrir el contexto con la consulta SQL',
'                l_context := apex_exec.open_query_context(',
'                    p_location  => apex_exec.c_location_local_db,',
unistr('                    p_sql_query => C_REPORTE -- Tu consulta aqu\00ED'),
'                );',
'',
unistr('                -- 2. Configurar la exportaci\00F3n a formato XLSX'),
'                l_export := apex_data_export.export (',
'                    p_context   => l_context,',
'                    p_format    => apex_data_export.c_format_csv,',
'                    p_file_name => ''LISTAS_CNSF_''||:P20_TI_FE_INICIO',
'                );',
'',
unistr('                -- 3. Cerrar el contexto de ejecuci\00F3n'),
'                apex_exec.close(l_context);',
'',
'                -- 4. Descargar el archivo directamente en el navegador',
'                apex_data_export.download( p_export => l_export );',
'                :P20_TI_FE_FIN     := TO_CHAR(SYSDATE,''DD/MM/YYYY HH24:MI:SS'');',
'        ELSE',
unistr('            RAISE_APPLICATION_ERROR(-20000,''Es necesario ingresar una fecha de inicio y una de finalizaci\00F3n.'');'),
'        END IF;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_exec.close(l_context);',
'        RAISE_APPLICATION_ERROR(-20000,''Error: ''||SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('Ocurri\00F3 un error al descargar el archivo, favor de ingresar una fecha inicio y una fecha fin')
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(248335060838579329)
,p_process_when=>'P20_FECHA_HASTA_COMUNICADO'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_process_success_message=>unistr('Archivo descargado con \00E9xito')
,p_internal_uid=>35769729272257849
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(169077976661078329)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Layout_Vacio'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_context         apex_exec.t_context;',
'    l_export          apex_data_export.t_export;',
'    l_columns         apex_data_export.t_columns; ',
unistr('    l_column          apex_exec.t_column; -- SE CORRIGI\00D3 EL TIPO DE DATO AQU\00CD'),
'    l_column_count    PLS_INTEGER;',
'    l_heading         VARCHAR2(4000);',
'    ',
'    C_REPORTE VARCHAR2(32767) := ''SELECT ''''0'''' AS ID_LISTA,''''|'''' AS "|" , ''''BAJA'''' AS TP_MOVIMIENTO,''''|'''' AS "| " , ''''TEXTO ABIERTO'''' AS DESCR_TP_MOVIMIENTO,''''|'''' AS "|  " , ''''01/01/2000'''' AS FEC_MOVIMIENTO,''''|'''' AS "|   " , ''''CNSF'''' AS LISTA_ORIGEN,'
||'''''|'''' AS "|    " , ''''COMISION NACIONAL DE SEGUROS Y FIANZAS'''' AS NOM_LISTA_ORIGEN,''''|'''' AS "|     " , ''''01/01/2000'''' AS FEC_COMUNICADO,''''|'''' AS "|      ", ''''FISICA'''' AS TIPO_PERSONA_CNSF,''''|'''' AS "|       ", ''''PERSONA FISICA'''' AS NOM_TIPO_PERS_CNSF,'''
||'''|'''' AS "|        ", ''''TEXTO ABIERTO'''' AS NOMBRE_1,''''|'''' AS "|         ", ''''TEXTO ABIERTO'''' AS NOMBRE_2,''''|'''' AS "|          ", ''''TEXTO ABIERTO'''' AS NOMBRE_3,''''|'''' AS "|           ", ''''TEXTO ABIERTO'''' AS NOMBRE_4,''''|'''' AS "|            ", ''''TEXTO ABI'
||'ERTO'''' AS NOMBRE_5,''''|'''' AS "|             ", ''''01/01/2000'''' AS FEC_NACIMIENTO,''''|'''' AS "|              ", ''''001'''' AS PAIS_PROCEDENCIA,''''|'''' AS "|               ", ''''001'''' AS CVE_PAIS_CNSF,''''|'''' AS "|                ", ''''TEXTO ABIERTO'''' AS NOM_PAIS_P'
||'ROCEDENCIA,''''|'''' AS "|                 ", ''''TEXTO ABIERTO'''' AS ALIAS_1,''''|'''' AS "|                  ", ''''TEXTO ABIERTO'''' AS ALIAS_2,''''|'''' AS "|                   ", ''''TEXTO ABIERTO'''' AS ALIAS_3,''''|'''' AS "|                    ", ''''TEXTO ABIERTO'''' AS A'
||'LIAS_4,''''|'''' AS "|                     ", ''''TEXTO ABIERTO'''' AS ALIAS_5,''''|'''' AS "|                      ", ''''TEXTO ABIERTO'''' AS ALIAS_6,''''|'''' AS "|                       ", ''''TEXTO ABIERTO'''' AS ALIAS_7,''''|'''' AS "|                        ", ''''TEXTO AB'
||'IERTO'''' AS ALIAS_8,''''|'''' AS "|                         ", ''''TEXTO ABIERTO'''' AS ALIAS_9,''''|'''' AS "|                          ", ''''TEXTO ABIERTO'''' AS ALIAS_10,''''|'''' AS "|                           ", ''''MEX'''' AS COD_NACIONALIDAD,''''|'''' AS "|             '
||'               ", ''''MX'''' AS CVE_NACIONALIDAD_CNSF,''''|'''' AS "|                             ", ''''MEXICANA'''' AS NOM_NACIONALIDAD,''''|'''' AS "|                              ", ''''TEXTO ABIERTO'''' AS ID_PASAPORTE,''''|'''' AS "|                               ", '''
||'''TEXTO ABIERTO'''' AS ID_NACIONAL,''''|'''' AS "|                                ", ''''TEXTO ABIERTO'''' AS DIRECCION,''''|'''' AS "|                                 ", ''''01/01/2000'''' AS FEC_ADHESION,''''|''''AS "|                                  ", ''''TEXTO ABIERTO'''
||''' AS OBSERVACIONES,''''|'''' AS "|                                   ", ''''''||:APP_USER||'''''' AS CODUSUARIO_ALTA,''''|'''' AS "|                                    ", ''''01/01/2000'''' AS FEC_ALTA FROM DUAL;'';',
'BEGIN',
'    -- 1. Abrir el contexto con la consulta SQL',
'    l_context := apex_exec.open_query_context(',
'        p_location  => apex_exec.c_location_local_db,',
'        p_sql_query => C_REPORTE',
'    );',
'',
unistr('    -- 2. Obtener el n\00FAmero de columnas totales de la consulta'),
'    l_column_count := apex_exec.get_column_count( p_context => l_context );',
'    ',
unistr('    -- 3. Mapear din\00E1micamente las columnas limpiando los alias "pipe"'),
'    FOR i IN 1 .. l_column_count LOOP',
unistr('        -- SE CORRIGI\00D3 LA FUNCI\00D3N AQU\00CD'),
'        l_column := apex_exec.get_column( p_context => l_context, p_column_idx => i );',
'        ',
unistr('        -- Si al quitar los espacios el alias es un pipe ''|'', el encabezado final en Excel ser\00E1 exactamente ''|'''),
'        IF TRIM(l_column.name) = ''|'' THEN',
'            l_heading := ''|'';',
'        ELSE',
'            l_heading := l_column.name;',
'        END IF;',
'',
unistr('        -- Agregar la columna procesada a la lista de exportaci\00F3n'),
'        apex_data_export.add_column (',
'            p_columns => l_columns,',
unistr('            p_name    => l_column.name, -- Vincula con el alias SQL \00FAnico (con espacios)'),
unistr('            p_heading => l_heading          -- Nombre limpio que ver\00E1 el usuario en Excel'),
'        );',
'    END LOOP;',
'',
unistr('    -- 4. Configurar la exportaci\00F3n a formato XLSX pasando el par\00E1metro p_columns'),
'    l_export := apex_data_export.export (',
'        p_context   => l_context,',
'        p_format    => apex_data_export.c_format_xlsx,',
'        p_columns   => l_columns, ',
'        p_file_name => ''Layout_ListasNegras_''||TO_CHAR(SYSDATE,''DDMMYYYY_HH24MISS'')||''.xlsx''',
'    );',
'',
unistr('    -- 5. Cerrar el contexto de ejecuci\00F3n'),
'    apex_exec.close(l_context);',
'',
'    -- 6. Descargar el archivo directamente en el navegador',
'    apex_data_export.download( p_export => l_export );',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_exec.close(l_context);',
'        RAISE_APPLICATION_ERROR(-20000,''Error en reporte: ''||SQLERRM);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('Ocurri\00F3 un error al descargar el Layout')
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(169077919805078328)
,p_process_success_message=>unistr('Layout descargado con \00E9xito')
,p_internal_uid=>104568806133271215
);
