'	v_TP_MOVIMIENTO				VARCHAR2(4000);',
'	v_DESCR_TP_MOVIMIENTO		VARCHAR2(4000);',
'	v_FEC_MOVIMIENTO			DATE;',
'	v_LISTA_ORIGEN				VARCHAR2(4000);',
'	v_NOM_LISTA_ORIGEN			VARCHAR2(4000);',
