'	v_NOMBRE_3					VARCHAR2(4000);',
'	v_NOMBRE_4					VARCHAR2(4000);',
'	v_NOMBRE_5					VARCHAR2(4000);',
'	v_FEC_NACIMIENTO			DATE;',
'	v_PAIS_PROCEDENCIA			VARCHAR2(4000);',
'	v_CVE_PAIS_CNSF				VARCHAR2(4000);',
'	v_NOM_PAIS_PROCEDENCIA	    VARCHAR2(4000);',
'	v_ALIAS_1					VARCHAR2(4000);',
'	v_ALIAS_2					VARCHAR2(4000);',
'	v_ALIAS_3					VARCHAR2(4000);',
'	v_ALIAS_4					VARCHAR2(4000);',
'	v_ALIAS_5					VARCHAR2(4000);',
'	v_ALIAS_6					VARCHAR2(4000);',
'	v_ALIAS_7			        VARCHAR2(4000);',
'	v_ALIAS_8				    VARCHAR2(4000);',
'	v_ALIAS_9					VARCHAR2(4000);',
'	v_ALIAS_10					VARCHAR2(4000);',
'	v_COD_NACIONALIDAD			VARCHAR2(4000);',
'	v_CVE_NACIONALIDAD_CNSF     VARCHAR2(4000);',
