'        FROM nls_session_parameters ',
'       WHERE parameter = ''NLS_DATE_FORMAT'';',
'',
'        EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_DATE_FORMAT = ''''DD/MM/YYYY'''''';',
'    ',
'    IF :P20_CRUCE IS NOT NULL THEN ',
'    ',
unistr('        -- 1. Obtener el BLOB del archivo reci\00E9n subido'),
'        SELECT blob_content',
'        INTO l_blob',
'        FROM apex_application_temp_files',
'        WHERE name = :P20_CRUCE;',
'        ',
'        DELETE FROM SICAS_OC.TA_CARGALYTPLD ',
'        WHERE CODCIA =1 ',
'   	        AND CODEMPRESA =1;',
'   	',
'       COMMIT;',
'',
'        -- 2. Convertir BLOB a CLOB (Texto)',
