'',
'        APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(''MI_EXCEL'');',
'        ',
'        l_clob := apex_util.blob_to_clob(l_blob);',
'',
unistr('        l_lineas := apex_string.split(l_clob, chr(10)); -- Divide por salto de l\00EDnea'),
'        nRegsTot := 0;',
'',
'        FOR i IN 2 .. l_lineas.count LOOP',
'            IF trim(l_lineas(i)) IS NOT NULL THEN',
'            nRegsTot := nRegsTot +1;',
'            l_linea_limpia := l_lineas(i);',
'            ',
'            l_linea_limpia := REPLACE(l_linea_limpia, chr(9), '''');',
'            ',
'            -- Corregir caracteres especiales (UTF-8 a Latino)',
'            l_linea_limpia := REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(l_linea_limpia,',
unistr('                    ''\00C3\00B3'',''\00F3''),''\00C3\00BC'',''\00FC''),''\00C3\00B1'',''\00F1''),''\00C3\00A9'',''\00E9''),''\00C3\00AD'',''\00ED''),''\00C3\00A1'',''\00E1''),''\00C3\00BA'',''\00FA''),''\00C3\2018'',''\00D1''),''\00C3\00BF'',''\00CD''),''\00C3\201C'',''\00D3'');'),
'',
'            l_campos := apex_string.split(l_linea_limpia, ''|'');',
'',
'            -- 6. Asignar a variables (Validando que existan los campos)',
'                IF l_campos.exists(1) THEN ',
'                    v_ID_LISTA := (l_campos(1)); ',
'                    SELECT (NVL(MAX(ID_LISTA), 0) + 1)',
'    				INTO v_ID_LISTA',
'    				FROM SICAS_OC.PLD_LISTAS_CNSF;',
'                END IF;',
'                IF l_campos.exists(2) THEN v_TP_MOVIMIENTO := l_campos(2); END IF;',
'                IF l_campos.exists(3) THEN v_DESCR_TP_MOVIMIENTO := l_campos(3); END IF;',
'                IF l_campos.exists(4) AND l_campos(4)IS NOT NULL THEN ',
'                    v_FEC_MOVIMIENTO := TO_DATE(REGEXP_REPLACE(l_campos(4), ''[^0-9/]'', '''') DEFAULT NULL ON CONVERSION ERROR, ''DD/MM/YYYY'', ''NLS_DATE_LANGUAGE = SPANISH'');',
'                END IF;',
'                IF l_campos.exists(5) THEN v_LISTA_ORIGEN := l_campos(5); END IF;',
'                IF l_campos.exists(6) THEN v_NOM_LISTA_ORIGEN := l_campos(6); END IF;',
'                IF l_campos.exists(7) AND l_campos(7)IS NOT NULL  THEN ',
'                    v_FEC_COMUNICADO := TO_DATE(REGEXP_REPLACE(l_campos(7), ''[^0-9/]'', '''') DEFAULT NULL ON CONVERSION ERROR, ''DD/MM/YYYY'', ''NLS_DATE_LANGUAGE = SPANISH'');',
'                END IF;',
'                IF l_campos.exists(8) THEN v_TIPO_PERSONA_CNSF := l_campos(8); END IF;',
'                IF l_campos.exists(9) THEN v_NOM_TIPO_PERS_CNSF := l_campos(9); END IF;',
'                IF l_campos.exists(10) THEN v_NOMBRE_1 := l_campos(10); END IF;',
'                IF l_campos.exists(11) THEN v_NOMBRE_2 := l_campos(11); END IF;',
'                IF l_campos.exists(12) THEN v_NOMBRE_3 := l_campos(12); END IF;',
'                IF l_campos.exists(13) THEN v_NOMBRE_4 := l_campos(13); END IF;',
'                IF l_campos.exists(14) THEN v_NOMBRE_5 := l_campos(14); END IF;',
'                IF l_campos.exists(15) AND l_campos(15) IS NOT NULL THEN ',
'                    v_FEC_NACIMIENTO := TO_DATE(REGEXP_REPLACE(l_campos(15), ''[^0-9/]'', '''') DEFAULT NULL ON CONVERSION ERROR, ''DD/MM/YYYY'', ''NLS_DATE_LANGUAGE = SPANISH'');',
'                END IF;',
'                IF l_campos.exists(16) THEN v_PAIS_PROCEDENCIA := TO_CHAR(l_campos(16)); END IF;',
'                IF l_campos.exists(17) THEN v_CVE_PAIS_CNSF := TO_CHAR(l_campos(17)); END IF;',
'                IF l_campos.exists(18) THEN v_NOM_PAIS_PROCEDENCIA := l_campos(18); END IF;',
'                IF l_campos.exists(19) THEN v_ALIAS_1 := l_campos(19); END IF;',
'                IF l_campos.exists(20) THEN v_ALIAS_2 := l_campos(20); END IF;',
'                IF l_campos.exists(21) THEN v_ALIAS_3 := l_campos(21); END IF;',
'                IF l_campos.exists(22) THEN v_ALIAS_4 := l_campos(22); END IF;',
'                IF l_campos.exists(23) THEN v_ALIAS_5 := l_campos(23); END IF;',
'                IF l_campos.exists(24) THEN v_ALIAS_6 := l_campos(24); END IF;',
'                IF l_campos.exists(25) THEN v_ALIAS_7 := l_campos(25); END IF;',
'                IF l_campos.exists(26) THEN v_ALIAS_8 := l_campos(26); END IF;',
'                IF l_campos.exists(27) THEN v_ALIAS_9 := l_campos(27); END IF;',
'                IF l_campos.exists(28) THEN v_ALIAS_10 := l_campos(28); END IF;',
'                IF l_campos.exists(29) THEN v_COD_NACIONALIDAD := l_campos(29); END IF;',
'                IF l_campos.exists(30) THEN v_CVE_NACIONALIDAD_CNSF := l_campos(30); END IF;',
'                IF l_campos.exists(31) THEN v_NOM_NACIONALIDAD := l_campos(31); END IF;',
'                IF l_campos.exists(32) THEN v_ID_PASAPORTE := l_campos(32); END IF;',
'                IF l_campos.exists(33) THEN v_ID_NACIONAL := l_campos(33); END IF;',
'                IF l_campos.exists(34) THEN v_DIRECCION := l_campos(34); END IF;',
'                IF l_campos.exists(35) AND l_campos(35) IS NOT NULL THEN ',
'                    v_FEC_ADHESION := TO_DATE(REGEXP_REPLACE(l_campos(35), ''[^0-9/]'', '''') DEFAULT NULL ON CONVERSION ERROR, ''DD/MM/YYYY'', ''NLS_DATE_LANGUAGE = SPANISH'');',
'                END IF;',
'                IF l_campos.exists(36) THEN v_OBSERVACIONES := l_campos(36); END IF;',
'                IF l_campos.exists(37) THEN v_CODUSUARIO_ALTA := :APP_USER; END IF;',
'                IF l_campos.exists(38) AND l_campos(38) IS NOT NULL THEN ',
'                    v_FEC_ALTA := TO_DATE(REGEXP_REPLACE(l_campos(38), ''[^0-9/]'', '''') DEFAULT NULL ON CONVERSION ERROR, ''DD/MM/YYYY'', ''NLS_DATE_LANGUAGE = SPANISH'');',
'                END IF;',
'',
'            END IF;',
'        --END LOOP;',
'',
'        vl_Existe := 0;',
'        	',
'        SELECT COUNT(1)',
'        INTO vl_Existe',
'        FROM SICAS_OC.PLD_LISTAS_CNSF',
'        WHERE NOMBRE_1 = v_NOMBRE_1;',
'',
'        IF vl_Existe = 0 THEN  --CRUCE CON ADMIN LISTAS',
'        	--NO EXISTE - SE DA DE ALTA ',
'        	SELECT COUNT(1) ',
'        	INTO vl_Existe',
'			FROM SICAS_OC.VALORES_DE_LISTAS ',
'			WHERE CODLISTA=''LISTAO'' ',
'			    AND CODVALOR=v_LISTA_ORIGEN;',
'						',
'			IF vl_Existe > 0 THEN',
'    ',
'	        	BEGIN',
'		        	INSERT INTO SICAS_OC.PLD_LISTAS_CNSF (Codcia,ID_LISTA,	TP_MOVIMIENTO,DESCR_TP_MOVIMIENTO,',
'			        	FEC_MOVIMIENTO,LISTA_ORIGEN,NOM_LISTA_ORIGEN,FEC_COMUNICADO,TIPO_PERSONA_CNSF,NOM_TIPO_PERS_CNSF,',
'			        	NOMBRE_1,	NOMBRE_2,NOMBRE_3,NOMBRE_4,NOMBRE_5,FEC_NACIMIENTO,PAIS_PROCEDENCIA,CVE_PAIS_CNSF,',
'			        	NOM_PAIS_PROCEDENCIA,ALIAS_1,ALIAS_2,	ALIAS_3,ALIAS_4,ALIAS_5,ALIAS_6,ALIAS_7,ALIAS_8,ALIAS_9,',
'						ALIAS_10,	COD_NACIONALIDAD,	CVE_NACIONALIDAD_CNSF,NOM_NACIONALIDAD,ID_PASAPORTE,ID_NACIONAL,DIRECCION,',
'						FEC_ADHESION,OBSERVACIONES,CODUSUARIO_ALTA,FEC_ALTA) ',
'					VALUES (v_Codcia,v_ID_LISTA,	v_TP_MOVIMIENTO,v_DESCR_TP_MOVIMIENTO,',
'			        	TO_DATE(TO_CHAR(v_FEC_MOVIMIENTO,''DD/MM/YYYY''),''DD/MM/YYYY''),v_LISTA_ORIGEN,v_NOM_LISTA_ORIGEN,',
'                        TO_DATE(TO_CHAR(v_FEC_COMUNICADO,''DD/MM/YYYY''),''DD/MM/YYYY''),v_TIPO_PERSONA_CNSF,v_NOM_TIPO_PERS_CNSF,',
'			        	v_NOMBRE_1,	v_NOMBRE_2,v_NOMBRE_3,v_NOMBRE_4,v_NOMBRE_5,',
'                        TO_DATE(TO_CHAR(v_FEC_NACIMIENTO,''DD/MM/YYYY''),''DD/MM/YYYY''),v_PAIS_PROCEDENCIA,v_CVE_PAIS_CNSF,',
'			        	v_NOM_PAIS_PROCEDENCIA,v_ALIAS_1,v_ALIAS_2,	v_ALIAS_3,v_ALIAS_4,v_ALIAS_5,v_ALIAS_6,v_ALIAS_7,v_ALIAS_8,v_ALIAS_9,',
'						v_ALIAS_10,	v_COD_NACIONALIDAD,	v_CVE_NACIONALIDAD_CNSF,v_NOM_NACIONALIDAD,v_ID_PASAPORTE,v_ID_NACIONAL,v_DIRECCION,',
'						TO_DATE(TO_CHAR(v_FEC_ADHESION,''DD/MM/YYYY''),''DD/MM/YYYY''),v_OBSERVACIONES,v_CODUSUARIO_ALTA,',
'                        TO_DATE(TO_CHAR(v_FEC_ALTA,''DD/MM/YYYY''),''DD/MM/YYYY''));',
'								-- nRegsIns     := nRegsIns + 1;',
'                    BEGIN',
'					    INSERT INTO SICAS_OC.TA_CARGALYTPLD VALUES(1,1,nRegsIns,v_NOMBRE_1,SYSDATE,:APP_USER);',
'					EXCEPTION',
'                        WHEN OTHERS THEN',
'                            NULL;',
'                    END;',
'',
'	        	EXCEPTION',
'	        		WHEN OTHERS THEN',
'	        			vl_DescError := SQLERRM;',
'                        BEGIN',
'	        			    INSERT INTO SICAS_OC.TA_CARGALYTPLD VALUES(1,1,v_ID_LISTA,''Error: ''||v_NOMBRE_1||''   ''||vl_DescError,SYSDATE,:APP_USER);',
'                        EXCEPTION',
'                            WHEN OTHERS THEN',
'                                vl_DescError := SQLERRM;',
'                        END;',
'                END;',
'			ELSE --LA LISTA NO EXISTE ',
'                BEGIN',
unistr('				    INSERT INTO SICAS_OC.TA_CARGALYTPLD VALUES(1,1,v_ID_LISTA,''Error: El valor ''||v_LISTA_ORIGEN||'' no existe en el cat\00E1logo de SICAS.'',SYSDATE,:APP_USER);'),
'                EXCEPTION',
'                    WHEN OTHERS THEN',
'                        vl_DescError := SQLERRM;',
'                END;',
'            END IF;',
'        ELSE',
'        	--YA EXISTE, SE ACTUALIZA EL TIPO DE MOVIMIENTO ',
'        	SELECT MAX(ID_LISTA)',
'        	INTO vl_Existe',
'        	FROM SICAS_OC.PLD_LISTAS_CNSF',
'        	WHERE NOMBRE_1 = v_NOMBRE_1;',
'        	BEGIN',
'        	    INSERT INTO SICAS_OC.TA_CARGALYTPLD VALUES(1,1,vl_Existe,''ACTUALIZADO'',SYSDATE,:APP_USER);',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                        vl_DescError := SQLERRM;',
'            END;',
'        	BEGIN',
unistr('        		SELECT TP_MOVIMIENTO --Obtenemos el \00FAltimo estatus'),
'        		INTO vl_MovAnterior',
'				FROM SICAS_OC.PLD_LISTAS_CNSF ',
'				WHERE (NOMBRE_1 = v_NOMBRE_1',
'					OR ID_LISTA = vl_Existe)',
'           			AND ROWNUM <=1',
'                ORDER BY ID_LISTA DESC;',
'',
'        	EXCEPTION ',
'        		WHEN OTHERS THEN ',
'        		    vl_MovAnterior := v_TP_MOVIMIENTO;',
'        	END;',
'        		',
'			IF vl_MovAnterior <> v_TP_MOVIMIENTO THEN',
'	        	UPDATE SICAS_OC.PLD_LISTAS_CNSF',
'	        	SET TP_MOVIMIENTO = v_TP_MOVIMIENTO',
'	        	WHERE (NOMBRE_1 = v_NOMBRE_1',
'	        		OR ID_LISTA = vl_Existe);',
'        	END IF;',
'        END IF;',
'END LOOP;',
'      ',
'',
'        nRegsIns := 0;',
'        nRegsTot :=	0;',
'        nRegsErr := 0;',
'        d:=0;',
'',
'        nRegsIns     := nRegsIns + 1;',
'',
'        APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(''MI_EXCEL'');',
'',
'      	vl_PosIni := 0;',
'	    vl_PosFin := INSTR(cLinea,''|'',1,1)-1;',
'							    ',
'        FOR i IN 2 .. l_lineas.count LOOP',
unistr('            -- Omitir l\00EDneas vac\00EDas'),
'            IF trim(l_lineas(i)) IS NOT NULL THEN',
'                ',
'                l_linea_limpia := l_lineas(i);',
'            ',
'                l_linea_limpia := REPLACE(l_linea_limpia, chr(9), '''');',
'            ',
'                -- Corregir caracteres especiales (UTF-8 a Latino)',
'                l_linea_limpia := REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(l_linea_limpia,',
unistr('                                ''\00C3\00B3'',''\00F3''),''\00C3\00BC'',''\00FC''),''\00C3\00B1'',''\00F1''),''\00C3\00A9'',''\00E9''),''\00C3\00AD'',''\00ED''),''\00C3\00A1'',''\00E1''),''\00C3\00BA'',''\00FA''),''\00C3\2018'',''\00D1''),''\00C3\00BF'',''\00CD''),''\00C3\201C'',''\00D3'');'),
'',
'                l_campos := apex_string.split(l_linea_limpia, ''|'');',
'',
'                IF l_campos.exists(1) THEN v_ID_LISTA := (l_campos(1)); ',
'                    SELECT (NVL(MAX(ID_LISTA), 0) + 1)',
'    				INTO v_ID_LISTA',
'    				FROM SICAS_OC.PLD_LISTAS_CNSF;',
'                END IF;',
'                IF l_campos.exists(2) THEN v_TP_MOVIMIENTO := l_campos(2); END IF;',
'                IF l_campos.exists(3) THEN v_DESCR_TP_MOVIMIENTO := l_campos(3); END IF;',
'                IF l_campos.exists(4) AND l_campos(4) IS NOT NULL THEN ',
'                    v_FEC_MOVIMIENTO := TO_DATE(REGEXP_REPLACE(l_campos(4), ''[^0-9/]'', '''') DEFAULT NULL ON CONVERSION ERROR, ''DD/MM/YYYY'', ''NLS_DATE_LANGUAGE = SPANISH'');',
'                END IF;',
'                IF l_campos.exists(5) THEN v_LISTA_ORIGEN := l_campos(5); END IF;',
'                IF l_campos.exists(6) THEN v_NOM_LISTA_ORIGEN := l_campos(6); END IF;',
'                IF l_campos.exists(7) AND l_campos(7)IS NOT NULL THEN ',
'                    v_FEC_COMUNICADO := TO_DATE(REGEXP_REPLACE(l_campos(7), ''[^0-9/]'', '''') DEFAULT NULL ON CONVERSION ERROR, ''DD/MM/YYYY'', ''NLS_DATE_LANGUAGE = SPANISH'');',
'                END IF;',
'                IF l_campos.exists(8) THEN v_TIPO_PERSONA_CNSF := l_campos(8); END IF;',
'                IF l_campos.exists(9) THEN v_NOM_TIPO_PERS_CNSF := l_campos(9); END IF;',
'                IF l_campos.exists(10) THEN v_NOMBRE_1 := l_campos(10);',
'                    BEGIN',
'						SELECT MAX(ID_LISTA) --Obtenemos el ID que se le asigno en la carga',
'						INTO v_ID_LISTA',
'						FROM SICAS_OC.PLD_LISTAS_CNSF',
'						WHERE NOMBRE_1 = v_NOMBRE_1;',
'					EXCEPTION',
'						WHEN OTHERS THEN',
'							v_ID_LISTA := 0;',
'					END;',
'                END IF;',
'                IF l_campos.exists(11) THEN v_NOMBRE_2 := l_campos(11); END IF;',
'                IF l_campos.exists(12) THEN v_NOMBRE_3 := l_campos(12); END IF;',
'                IF l_campos.exists(13) THEN v_NOMBRE_4 := l_campos(13); END IF;',
'                IF l_campos.exists(14) THEN v_NOMBRE_5 := l_campos(14); END IF;',
'                IF l_campos.exists(15) AND l_campos(15) IS NOT NULL THEN ',
'                    v_FEC_NACIMIENTO := TO_DATE(REGEXP_REPLACE(l_campos(15), ''[^0-9/]'', '''') DEFAULT NULL ON CONVERSION ERROR, ''DD/MM/YYYY'', ''NLS_DATE_LANGUAGE = SPANISH'');',
'                END IF;',
'                IF l_campos.exists(16) THEN v_PAIS_PROCEDENCIA := TO_CHAR(l_campos(16)); END IF;',
'                IF l_campos.exists(17) THEN v_CVE_PAIS_CNSF := TO_CHAR(l_campos(17)); END IF;',
'                IF l_campos.exists(18) THEN v_NOM_PAIS_PROCEDENCIA := l_campos(18); END IF;',
'                IF l_campos.exists(19) THEN v_ALIAS_1 := l_campos(19); END IF;',
'                IF l_campos.exists(20) THEN v_ALIAS_2 := l_campos(20); END IF;',
'                IF l_campos.exists(21) THEN v_ALIAS_3 := l_campos(21); END IF;',
'                IF l_campos.exists(22) THEN v_ALIAS_4 := l_campos(22); END IF;',
'                IF l_campos.exists(23) THEN v_ALIAS_5 := l_campos(23); END IF;',
'                IF l_campos.exists(24) THEN v_ALIAS_6 := l_campos(24); END IF;',
'                IF l_campos.exists(25) THEN v_ALIAS_7 := l_campos(25); END IF;',
'                IF l_campos.exists(26) THEN v_ALIAS_8 := l_campos(26); END IF;',
'                IF l_campos.exists(27) THEN v_ALIAS_9 := l_campos(27); END IF;',
'                IF l_campos.exists(28) THEN v_ALIAS_10 := l_campos(28); END IF;',
'                IF l_campos.exists(29) THEN v_COD_NACIONALIDAD := l_campos(29); END IF;',
'                IF l_campos.exists(30) THEN v_CVE_NACIONALIDAD_CNSF := l_campos(30); END IF;',
'                IF l_campos.exists(31) THEN v_NOM_NACIONALIDAD := l_campos(31); END IF;',
'                IF l_campos.exists(32) THEN v_ID_PASAPORTE := l_campos(32); END IF;',
'                IF l_campos.exists(33) THEN v_ID_NACIONAL := l_campos(33); END IF;',
'                IF l_campos.exists(34) THEN v_DIRECCION := l_campos(34); END IF;',
'                IF l_campos.exists(35) AND l_campos(35) IS NOT NULL THEN ',
'                    v_FEC_ADHESION := TO_DATE(REGEXP_REPLACE(l_campos(35), ''[^0-9/]'', '''') DEFAULT NULL ON CONVERSION ERROR, ''DD/MM/YYYY'', ''NLS_DATE_LANGUAGE = SPANISH'');',
'                END IF;',
'                IF l_campos.exists(36) THEN v_OBSERVACIONES := l_campos(36); END IF;',
'                IF l_campos.exists(37) THEN v_CODUSUARIO_ALTA := :APP_USER; END IF;',
'                IF l_campos.exists(38) AND l_campos(38) IS NOT NULL THEN ',
'                    v_FEC_ALTA := TO_DATE(REGEXP_REPLACE(l_campos(38), ''[^0-9/]'', '''') DEFAULT NULL ON CONVERSION ERROR, ''DD/MM/YYYY'', ''NLS_DATE_LANGUAGE = SPANISH'');',
'                END IF;',
'',
'            END IF;',
'							',
'			vl_Existe := 0;',
'					',
'			SELECT ID_LISTA',
'        	INTO vl_IDREG',
'        	FROM SICAS_OC.PLD_LISTAS_CNSF',
'        	WHERE NOMBRE_1 = v_NOMBRE_1',
'        		AND ROWNUM <= 1',
'            ORDER BY ID_LISTA DESC;	',
'        	',
'            BEGIN',
'            	UPDATE SICAS_OC.TA_CARGALYTPLD',
'            	SET IDREGISTRO = v_ID_LISTA',
'            	WHERE ESTATUS = v_NOMBRE_1;',
'            	',
'            	COMMIT;',
'        	EXCEPTION',
'                WHEN OTHERS THEN',
'                    NULL;',
'            END;',
'',
'        	SELECT COUNT(1)',
'        	INTO vl_Existe',
'        	FROM SICAS_OC.TA_CARGALYTPLD',
'        	WHERE ESTATUS = v_NOMBRE_1',
'        		AND IDREGISTRO = vl_IDREG',
'        		AND ROWNUM <= 1;	',
'        	',
'        	IF vl_Existe = 1 THEN--EL ESTATUS = A NOMBRE, FUE CORRECTO Y NUEVO ',
'        		v_Color := ''Nuevo''; --''#f22b2b'' ; --NARANJA',
'        	ELSE',
'        		SELECT COUNT(1)',
'	        	INTO vl_Existe',
'	        	FROM SICAS_OC.TA_CARGALYTPLD',
'	        	WHERE ESTATUS = ''ACTUALIZAD0''',
'	        		AND IDREGISTRO = vl_IDREG',
'	        		AND ROWNUM <= 1;	',
'	        	IF vl_Existe = 1 THEN--EL ESTATUS = ACTUALIZADO, YA EXISTIA',
'	        		v_Color := ''Existente''; --''#0de340'';--VERDE',
'	        	ELSE',
'	        		v_Color := ''Existente'';--VERDE',
'	        	END IF;',
'        	END IF;',
'',
'            nRegsIns     := nRegsIns + 1;',
'  	',
'            nLinea := nLinea + csg_1;',
'',
'            --Aqui se va llenando el excel de salida',
'            APEX_COLLECTION.ADD_MEMBER(',
'                p_collection_name => ''MI_EXCEL'',',
'                p_c001 => v_ID_LISTA,',
'                p_c002 => v_TP_MOVIMIENTO,',
'                p_c003 => v_DESCR_TP_MOVIMIENTO,',
'                p_c004 => v_FEC_MOVIMIENTO,',
'                p_c005 => v_LISTA_ORIGEN,',
'                p_c006 => v_NOM_LISTA_ORIGEN,',
'                p_c007 => v_FEC_COMUNICADO,',
