'                p_c013 => v_NOMBRE_4,',
'                p_c014 => v_NOMBRE_5,',
'                p_c015 => v_FEC_NACIMIENTO,',
'                p_c016 => v_PAIS_PROCEDENCIA,',
'                p_c017 => v_CVE_PAIS_CNSF,',
'                p_c018 => v_NOM_PAIS_PROCEDENCIA,',
'                p_c019 => v_ALIAS_1,',
'                p_c020 => v_ALIAS_2,',
'                p_c021 => v_ALIAS_3,',
'                p_c022 => v_ALIAS_4,',
'                p_c023 => v_ALIAS_5,',
'                p_c024 => v_ALIAS_6,',
'                p_c025 => v_ALIAS_7,',
'                p_c026 => v_ALIAS_8,',
'                p_c027 => v_ALIAS_9,',
'                p_c028 => v_ALIAS_10,',
'                p_c029 => v_COD_NACIONALIDAD,',
'                p_c030 => v_CVE_NACIONALIDAD_CNSF,',
'                p_c031 => v_NOM_NACIONALIDAD,',
'                p_c032 => v_ID_PASAPORTE,',
'                p_c033 => v_ID_NACIONAL,',
'                p_c034 => v_DIRECCION,',
'                p_c035 => v_FEC_ADHESION,',
'                p_c036 => v_OBSERVACIONES,',
'                p_c037 => v_CODUSUARIO_ALTA,',
'                p_c038 => v_FEC_ALTA,',
'                --p_c039 => vl_DescError,',
'                p_c040 => v_Color',
'            );',
'            ',
'        END LOOP;',
'        ',
'        l_context := apex_exec.open_query_context(',
'        p_location => apex_exec.c_location_local_db,',
'        p_sql_query => ''SELECT DISTINCT c001 AS ID_LISTA, ',
'                    c002 AS TP_MOVIMIENTO,',
'                    c003 AS DESC_TP_MOVIMIENTO, ',
'                    c004 AS FEC_MOVIMIENTO,',
'                    c005 AS LISTA_ORIGEN, ',
'                    c006 AS NOM_LISTA_ORIGEN,',
'                    c007 AS FEC_COMUNICADO,',
'                    c008 AS TIPO_PERSONA_CNSF,',
'                    c009 AS NOM_TIPO_PERSONA,',
'                    c010 AS NOMBRE_1,',
'                    c011 AS NOMBRE_2,',
'                    c012 AS NOMBRE_3,',
'                    c013 AS NOMBRE_4,',
'                    c014 AS NOMBRE_5,',
'                    c015 AS FEC_NACIMIENTO,',
'                    c016 AS PAIS_PROCEDENCIA,',
'                    c017 AS CVE_PAIS_CNSF,',
'                    c018 AS NOM_PAIS_PROCEDENCIA,',
'                    c019 AS ALIAS1,',
'                    c020 AS ALIAS2,',
'                    c021 AS ALIAS3,',
'                    c022 AS ALIAS4,',
'                    c023 AS ALIAS5,',
