'                    c027 AS ALIAS9,',
'                    c028 AS ALIAS10,',
'                    c029 AS COD_NACIONALIDAD,',
'                    c030 AS CVE_NACIONALIDAD,',
'                    c031 AS NOM_NACIONALIDAD,',
