'        apex_exec.close( l_context );',
'',
'        -- 4. Descargar el archivo (detiene el motor de APEX)',
'        apex_data_export.download( p_export => l_export );',
'    ELSE',
'        apex_error.add_error (',
unistr('            p_message          => ''No se ha seleccionado ning\00FAn archivo o este no es valido.'','),
'            p_display_location => apex_error.c_inline_with_field,',
'            p_page_item_name   => ''P20_CRUCE''',
'        );',
'        EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_DATE_FORMAT = '''''' || vl_nls_original || '''''''';',
unistr('        RAISE_APPLICATION_ERROR(-20000,''No se ha seleccionado ning\00FAn archivo o este no es valido.'');'),
'    END IF;',
'    EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_DATE_FORMAT = '''''' || vl_nls_original || '''''''';',
' EXCEPTION',
'    WHEN OTHERS THEN',
'        EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_DATE_FORMAT = '''''' || vl_nls_original || '''''''';',
'        RAISE_APPLICATION_ERROR(-20000,''Error: ''||SQLERRM);',
'        apex_error.add_error (',
'            p_message          => ''Error: ''||SQLERRM,',
'            p_display_location => apex_error.c_inline_with_field,',
'            p_page_item_name   => ''P20_CRUCE''',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(169077792091078327)
