begin
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(248333618342579315)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Registro Seleccionado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'v_rowid rowid;',
'vUrl    varchar2(4000);',
'',
'cursor c_datos is ',
'select ',
'        CODCIA,',
'       ID_LISTA,',
'       TP_MOVIMIENTO,',
'       DESCR_TP_MOVIMIENTO,',
'       FEC_MOVIMIENTO,',
'       LISTA_ORIGEN,',
'       FEC_COMUNICADO,',
'       TIPO_PERSONA_CNSF,',
'       NOMBRE_1,',
'       NOMBRE_2,',
'       NOMBRE_3,',
'       NOMBRE_4,',
'       NOMBRE_5,',
'       FEC_NACIMIENTO,',
'       PAIS_PROCEDENCIA,',
'       ALIAS_1,',
'       ALIAS_2,',
'       ALIAS_3,',
'       ALIAS_4,',
'       ALIAS_5,',
'       ALIAS_6,',
'       ALIAS_7,',
'       ALIAS_8,',
'       ALIAS_9,',
'       ALIAS_10,',
'       COD_NACIONALIDAD,',
'       ID_PASAPORTE,',
'       ID_NACIONAL,',
'       DIRECCION,',
'       FEC_ADHESION,',
'       OBSERVACIONES,',
'       CODUSUARIO_ALTA,',
'       FEC_ALTA',
'  from PLD_LISTAS_CNSF',
'  where rowid = v_rowid;',
'',
'tCursor c_datos%rowtype;',
'',
'begin',
' begin',
'      select APEX_APPLICATION.G_x02 --substr(APEX_APPLICATION.G_x02, 1, instr(APEX_APPLICATION.G_x02, '':'') - 1) p1',
'         --    substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 1) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - instr(APEX_APPLICATION.G_x02, '':'', 1, 1) - 1) p3,',
'           --  substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - 1) p3,',
'             --substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - 1) p4,',
'            -- substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 5) - instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - 1) p5',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := NULL;',
'    end;',
' ',
'  if v_rowid is not null then ',
'    open c_datos;',
'    loop',
'    fetch c_datos into tCursor;',
'    exit when c_datos%notfound;',
'       apex_json.open_object;',
'       apex_json.write(''observaciones'',tcursor.observaciones);',
'       apex_json.write(''descr_tp_movimiento'',tcursor.TP_MOVIMIENTO);',
'',
'               SELECT APEX_PAGE.GET_URL (',
'            p_page   => ''21'',',
'            p_clear_cache => ''21'', ',
'            p_items  => ''P21_CODCIA,P21_ID_LISTA,P21_EDICION'',',
'            p_values =>  tcursor.codcia ||'',''|| tcursor.id_lista||'',''||''N'',',
'            p_triggering_element => ''$("#SR_Detalle")'') f_url_1',
'     INTO vUrl',
'     FROM DUAL;',
'  apex_json.write(''url'', vUrl);',
'',
'       ',
'       apex_json.close_object;',
'    end loop;',
'    close c_datos;',
'  else',
'       apex_json.open_object;',
'       apex_json.write(''observaciones'','''');',
'       apex_json.write(''descr_tp_movimiento'','''');',
'       :P21_EDICION := ''N'';',
'       apex_json.close_object;',
'  end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>35768043377257832
);
null;
end;
