wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(248685359439306913)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Iniciar P\00E1gina')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P22_COMPANIA := oc_empresas.nombre_compania(nvl(:codcia,1));',
'',
'BEGIN',
'   IF :P22_FECHA_DESDE IS NULL AND',
'   	  :P22_FECHA_HASTA IS NULL THEN',
'   	  IF TO_NUMBER(TO_CHAR(TRUNC(SYSDATE),''DD'')) <= 4 THEN',
'   	     :P22_FECHA_DESDE := TO_DATE(''01/''|| TO_CHAR(TRUNC(ADD_MONTHS(SYSDATE,-1)),''MM/YYYY''),''DD/MM/YYYY'');',
'   	  ELSE',
'   	     :P22_FECHA_DESDE := TO_DATE(''01/''|| TO_CHAR(TRUNC(SYSDATE),''MM/YYYY''),''DD/MM/YYYY'');',
'      END IF;',
'      :P22_FECHA_HASTA := LAST_DAY(:P22_FECHA_DESDE);',
'   END IF;',
'   :P22_FECHA_DESDE_A := :P22_FECHA_DESDE;',
'   :P22_FECHA_HASTA_A :=  :P22_FECHA_HASTA;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>36119784473985430
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(251073322063042708)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generar Reporte Detalle'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P22_TRANSACPOLPRODALTO_FILE_ID  := NULL;',
':P22_PRODNIVRIESALTO_FILE_ID := NULL;',
':P22_POLIZASNIVRIESALTO_FILE_ID := NULL;',
':P22_CLIENTERIESGOALTO_FILE_ID  := NULL;',
':P22_POLCLIENIVRIESGOALTO_FILE_ID:= NULL;',
':P22_SINIAPROBPEND_FILE_ID := NULL;',
':P22_EVALUACION_FILE_ID := NULL;',
':P22_TRANSACPOLPRODALTO_URL_ID := NULL;',
':P22_PRODNIVRIESALTO_URL_ID := NULL;',
':P22_POLIZASNIVRIESALTO_URL_ID := NULL;',
':P22_CLIENTERIESGOALTO_URL_ID := NULL;',
':P22_POLCLIENIVRIESGOALTO_URL_ID := NULL;',
':P22_SINIAPROBPEND_URL_ID := NULL; ',
':P22_EVALUACION_URL_ID := NULL;',
'',
'IF :P22_IND_TRANSACPOLPRODALTO = ''S'' THEN',
'         GENERAR_TRANSAC_POL_PROD_ALTO(:P22_ARCH_TRANSPOLPRODNIVALTO,',
'                                       :P22_FORMATO_D,',
'                                       TO_DATE(:P22_FECHA_DESDE_A,''DD/MM/YYYY''), ',
'                                       TO_DATE(:P22_FECHA_HASTA_A,''DD/MM/YYYY''),',
'                                       :CODCIA,',
'                                       :P22_TRANSACPOLPRODALTO_FILE_ID);',
'     END IF;',
'     ',
'     IF :P22_IND_PRODNIVRIESALTO = ''S'' THEN',
'         GENERAR_PROD_NIV_RIES_ALTO(:P22_ARCH_PRODNIVRIESALTO,',
'                                       TO_DATE(:P22_FECHA_DESDE_A,''DD/MM/YYYY''), ',
'                                       TO_DATE(:P22_FECHA_HASTA_A,''DD/MM/YYYY''),',
'                                    :P22_FORMATO_D,',
'                                    :CODCIA,',
'                                    :P22_PRODNIVRIESALTO_FILE_ID);',
'     END IF;',
'',
'      IF :P22_IND_POLIZASNIVRIESALTO = ''S'' THEN',
'         GENERAR_POL_NIV_RIES_ALTO(:P22_ARCH_POL_NIVRIESALTO,',
'                                       TO_DATE(:P22_FECHA_DESDE_A,''DD/MM/YYYY''), ',
'                                       TO_DATE(:P22_FECHA_HASTA_A,''DD/MM/YYYY''),',
'                                   :P22_PRODUCTOS,',
'                                   :P22_FORMATO_D,',
'                                   :CODCIA,',
'                                   :P22_POLIZASNIVRIESALTO_FILE_ID);',
'      END IF;',
'      --     ',
'      IF :P22_IND_CLIENTERIESGOALTO = ''S'' THEN',
'          GENERAR_CLIENTES_RIESGO_ALTO(:P22_ARCH_CLIENTERIESGOALTO,',
'                                       TO_DATE(:P22_FECHA_DESDE_A,''DD/MM/YYYY''), ',
'                                       TO_DATE(:P22_FECHA_HASTA_A,''DD/MM/YYYY''),',
'                                       :P22_FORMATO_D,',
'                                       :CODCIA,',
'                                       :P22_CLIENTERIESGOALTO_FILE_ID);',
'      END IF;',
'      --',
' ',
'      IF :P22_IND_POLCLIENIVRIESGOALTO = ''S'' THEN',
'         GENERAR_POL_CLIEN_NIV_RIES_ALT(:P22_ARCH_POLCLIENIVRIESALTO,',
'                                       TO_DATE(:P22_FECHA_DESDE_A,''DD/MM/YYYY''), ',
'                                       TO_DATE(:P22_FECHA_HASTA_A,''DD/MM/YYYY''),',
'                                        :P22_CLIENTES,',
'                                        :P22_FORMATO_D,',
'                                        :CODCIA,',
'                                        :P22_POLCLIENIVRIESGOALTO_FILE_ID);',
'      END IF;',
'      --',
'      IF :P22_IND_SINIAPROBPEND = ''S'' THEN',
'         MOVTOS_APRO_PEND_SINIESTROS(:P22_ARCH_SINIAPROPEND,',
'                                       TO_DATE(:P22_FECHA_DESDE_A,''DD/MM/YYYY''), ',
'                                       TO_DATE(:P22_FECHA_HASTA_A,''DD/MM/YYYY''),',
'                                     :P22_FORMATO_D,',
'                                     :CODCIA,',
'                                     :P22_SINIAPROBPEND_FILE_ID);',
'      END IF; ',
'      --',
'      IF :P22_IND_EVALUACION = ''S'' THEN',
'         MOVTOS_EVALUACION_RIESGOS(:P22_ARCH_EVALUACION,',
'                                       TO_DATE(:P22_FECHA_DESDE_A,''DD/MM/YYYY''), ',
'                                       TO_DATE(:P22_FECHA_HASTA_A,''DD/MM/YYYY''),                                 ',
'                                   :P22_FORMATO_D,',
'                                   :CODCIA,',
'                                   :P22_EVALUACION_FILE_ID);',
'      END IF; '))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(251072708946042702)
,p_process_success_message=>'Reportes Solicitados Fueron Generados Exitosamente'
,p_internal_uid=>38507747097721225
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(251073401145042709)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generar URL Detalle'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P22_TRANSACPOLPRODALTO_FILE_ID IS NOT NULL THEN',
'    SELECT ',
'      APEX_UTIL.PREPARE_URL(',
'        p_url => ''f?p='' || :APP_ID || '':0:'' || :APP_SESSION || '':APPLICATION_PROCESS=GET_FILE_APEX:::FILE_ID:&P22_TRANSACPOLPRODALTO_FILE_ID.'',',
