 p_id=>wwv_flow_imp.id(251222379893570500)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generar Reporte'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P22_SUMAASEG_FILE_ID  := NULL;',
':P22_MOVASEG_FILE_ID  := NULL;',
':P22_COBUSD_FILE_ID  := NULL;',
':P22_LIMEFECTIVO_FILE_ID := NULL;',
':P22_LIMEFECTIVO_MES_FILE_ID := NULL;',
':P22_RIESGOALTO_FILE_ID := NULL;',
':P22_RIESGOCLIENTE_FILE_ID := NULL;',
':P22_RIESGOACTIVI_FILE_ID := NULL;',
':P22_SUMAASEG_FILE_URL := NULL;',
':P22_MOVASEG_FILE_URL := NULL;',
':P22_COBUSD_FILE_URL := NULL;',
':P22_LIMEFECTIVO_FILE_URL := NULL; ',
':P22_LIMEFECTIVO_MES_FILE_URL:= NULL;',
':P22_RIESGOALTO_FILE_URL := NULL;',
':P22_RIESGOCLIENTE_FILE_URL := NULL;',
':P22_RIESGOACTIVI_FILE_URL  := NULL;',
'',
'  IF :P22_IND_SUMAASEG = ''S'' THEN',
'         GENERAR_MOV_SUMA(:P22_ARCH_SUMAASEG,',
'                         TO_DATE(:P22_FECHA_DESDE,''DD/MM/YYYY''), ',
'                         TO_DATE(:P22_FECHA_HASTA,''DD/MM/YYYY''),',
'                         :P22_FORMATO,',
'                         :CODCIA,',
'                         :P22_SUMAASEG_FILE_ID);',
'      END IF;',
'      --',
'      IF :P22_IND_MOVASEG = ''S'' THEN',
'         GENERAR_MOV_ASEG(:P22_ARCH_MOVASEG,',
'                         TO_DATE(:P22_FECHA_DESDE,''DD/MM/YYYY''), ',
'                         TO_DATE(:P22_FECHA_HASTA,''DD/MM/YYYY''),',
'                         :P22_FORMATO,',
'                         :CODCIA,',
'                         :P22_MOVASEG_FILE_ID);',
'      END IF;',
'      --',
'      IF :P22_IND_COBUSD = ''S'' THEN',
'         GENERAR_COB_USD(:P22_ARCH_COBUSD,',
'                         TO_DATE(:P22_FECHA_DESDE,''DD/MM/YYYY''), ',
'                         TO_DATE(:P22_FECHA_HASTA,''DD/MM/YYYY''),',
'                         :P22_FORMATO,',
'                         :CODCIA,',
'                         :P22_COBUSD_FILE_ID);',
'      END IF;',
'      --',
'      IF :P22_IND_LIMEFECTIVO = ''S'' THEN',
'         GENERAR_MOVTOS_EFECTIVO(:P22_ARCH_LIMEFECTIVO,',
'                         TO_DATE(:P22_FECHA_DESDE,''DD/MM/YYYY''), ',
'                         TO_DATE(:P22_FECHA_HASTA,''DD/MM/YYYY''),',
'                                 :P22_FORMATO,',
'                                 :CODCIA,',
'                                 :P22_LIMEFECTIVO_FILE_ID);',
'      END IF;',
'      --',
'      IF :P22_IND_LIMEFECTIVO_MES = ''S'' THEN',
'         GENERAR_MOVTOS_EFECTIVO_MES(:P22_ARCH_LIMEFECTIVO_MES,',
'                         TO_DATE(:P22_FECHA_DESDE,''DD/MM/YYYY''), ',
'                         TO_DATE(:P22_FECHA_HASTA,''DD/MM/YYYY''),',
'                                     :P22_FORMATO,',
'                                     :CODCIA,',
'                                     :P22_LIMEFECTIVO_MES_FILE_ID);',
'      END IF;',
'      --',
'      IF :P22_IND_RIESGOALTO = ''S'' THEN',
'         GENERAR_RIESGO_ALTO(:P22_ARCH_RIESGOALTO,',
'                         TO_DATE(:P22_FECHA_DESDE,''DD/MM/YYYY''), ',
'                         TO_DATE(:P22_FECHA_HASTA,''DD/MM/YYYY''),',
'                             :P22_FORMATO,',
'                             :CODCIA,',
'                             :P22_RIESGOALTO_FILE_ID);',
'      END IF;',
'      --',
'      ',
'      IF :P22_IND_RIESGOCLIENTE = ''S'' THEN',
'         GENERAR_RIESGO_CLIENTE(:P22_ARCH_RIESGOCLIENTE,',
'                         TO_DATE(:P22_FECHA_DESDE,''DD/MM/YYYY''), ',
'                         TO_DATE(:P22_FECHA_HASTA,''DD/MM/YYYY''),',
'                                     :P22_FORMATO,',
'                                     :CODCIA,',
'                                     :P22_RIESGOCLIENTE_FILE_ID);',
'      END IF;',
'',
'      --',
'      IF :P22_IND_RIESGOACTIVI = ''S'' THEN',
'         GENERAR_RIESGO_ACTIVIDAD(:P22_ARCH_RIESGOACTIVI,',
'                         TO_DATE(:P22_FECHA_DESDE,''DD/MM/YYYY''), ',
'                         TO_DATE(:P22_FECHA_HASTA,''DD/MM/YYYY''),',
'                                     :P22_FORMATO,',
'                                     :CODCIA,',
'                                     :P22_RIESGOACTIVI_FILE_ID);',
'      END IF;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(250708927317269595)
,p_process_success_message=>'Reportes Solicitados Fueron Generados Exitosamente'
,p_internal_uid=>38656804928249017
);
end;
