wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(251615033165846558)
,p_plug_name=>'Consulta Asegurado'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT /*+ ALL_ROWS */',
'DISTINCT P.NUMPOLUNICO,',
'         P.IDPOLIZA,',
'         P.PLDSTBLOQUEADA,',
'         DP.IDETPOL,',
'         DP.IDTIPOSEG,',
'         TS.CODTIPOPLAN,',
'         TS.CODPLANPAGO,',
'         TS.DESCRIPCION,',
'         P.FECINIVIG,',
'         P.FECFINVIG,',
'         DP.FECINIVIG FECINIVIGDET,',
'         DP.FECFINVIG FECFINVIGDET,',
'         C.CODCLIENTE,',
'         C.TIPO_DOC_IDENTIFICACION,',
'         C.NUM_DOC_IDENTIFICACION,',
'         OC_CLIENTES.NOMBRE_CLIENTE(P.CODCLIENTE) NOM_CONTRATANTE,',
'         P.PRIMANETA_LOCAL,',
'         PNJ.TIPO_PERSONA,',
'         PNJ.FECNACIMIENTO,',
'         PNJ.CODACTIVIDAD,',
'         AE.DESCACTIVIDAD,',
'         PNJ.NACIONALIDAD,',
'         PC.DESC_PLAN,',
'         DP.CODPLANPAGO CODPLANPAGODET,',
'         PP.DESCPLAN FORMA_PAGO,',
'         SUM(NVL(F.MONTO_FACT_LOCAL, 0)) MONTO_PAGADO',
'/*         PNJ.CODPROVRES,',
'         PR.DESCESTADO,',
'         OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''TIPNEGO'', P.CODTIPONEGOCIO) TIPO_DE_NEGOCIO,',
'         P.CODRIESGOREA,',
'         MC.CODFORMACOBRO TIPO_DE_PAGO,',
'         VL.DESCVALLST DESCRIPCION_TIPO_PAGO,',
'         RA.NUMAUTORTIPSEG',
'*/',
'  FROM POLIZAS                   P,',
'       DETALLE_POLIZA            DP,',
'       TIPOS_DE_SEGUROS          TS,',
'       CLIENTES                  C,',
'       PERSONA_NATURAL_JURIDICA  PNJ,',
'       PLAN_COBERTURAS           PC,',
'       FACTURAS                  F,',
'       PROVINCIA                 PR,',
'       ACTIVIDADES_ECONOMICAS    AE,',
'       MEDIOS_DE_COBRO           MC,',
'       VALORES_DE_LISTAS         VL,',
'       REGISTRO_TIPSEG_AUTORIDAD RA,',
'       PLAN_DE_PAGOS             PP',
' WHERE P.FECFINVIG BETWEEN :P23_FECHA_DESDE AND :P23_FECHA_HASTA  ',
'   --',
'   AND DP.IDPOLIZA = P.IDPOLIZA',
'   AND DP.IDETPOL  = (SELECT MIN(IDETPOL)',
'                        FROM DETALLE_POLIZA DP1',
'                       WHERE DP1.IDPOLIZA = P.IDPOLIZA)',
'   --',
'   AND TS.IDTIPOSEG = DP.IDTIPOSEG',
'   --',
'   AND C.CODCLIENTE = P.CODCLIENTE',
'   --',
'   AND PNJ.TIPO_DOC_IDENTIFICACION = C.TIPO_DOC_IDENTIFICACION',
'   AND PNJ.NUM_DOC_IDENTIFICACION  = C.NUM_DOC_IDENTIFICACION',
'   --',
'   AND PC.IDTIPOSEG  = DP.IDTIPOSEG',
'   AND PC.CODEMPRESA = DP.CODEMPRESA',
'   AND PC.CODCIA     = DP.CODCIA',
'   AND PC.PLANCOB    = DP.PLANCOB',
'   --',
'   AND F.IDPOLIZA(+) = P.IDPOLIZA',
'   AND F.STSFACT(+)  = ''PAG''',
'   --',
'   AND PR.CODPAIS = ''001''',
'   AND PR.CODESTADO(+) = PNJ.CODPROVRES',
'   --',
'   AND AE.CODACTIVIDAD = PNJ.CODACTIVIDAD',
'   --',
'   AND MC.TIPO_DOC_IDENTIFICACION(+) = PNJ.TIPO_DOC_IDENTIFICACION',
'   AND MC.NUM_DOC_IDENTIFICACION(+)  = PNJ.NUM_DOC_IDENTIFICACION',
'   --',
'   AND VL.CODLISTA(+) = ''FORMPAGO''',
'   AND VL.CODVALOR(+) = MC.CODFORMACOBRO',
'   --',
'   AND RA.CODCIA      = TS.CODCIA',
'   AND RA.CODEMPRESA  = TS.CODEMPRESA',
'   AND RA.IDTIPOSEG   = TS.IDTIPOSEG',
'   AND RA.NUMREGISTRO = (SELECT MAX(RA2.NUMREGISTRO)',
'                           FROM REGISTRO_TIPSEG_AUTORIDAD RA2',
'                          WHERE RA2.CODCIA     = RA.CODCIA',
'                            AND RA2.CODEMPRESA = RA.CODEMPRESA',
'                            AND RA2.IDTIPOSEG  = RA.IDTIPOSEG',
'                            AND RA2.STREGISTRO IN (''APRO'', ''SUS''))',
'   --',
'   AND PP.CODCIA      = DP.CODCIA',
'   AND PP.CODEMPRESA  = DP.CODEMPRESA',
'   AND PP.CODPLANPAGO = DP.CODPLANPAGO',
' GROUP BY P.NUMPOLUNICO,',
'          P.IDPOLIZA,',
'          P.pldstbloqueada,',
'          DP.IDETPOL,',
'          DP.IDTIPOSEG,',
'          TS.CODTIPOPLAN,',
'          TS.CODPLANPAGO,',
'          TS.DESCRIPCION,',
'          P.FECINIVIG,',
'          P.FECFINVIG,',
'          DP.FECINIVIG,',
'          DP.FECFINVIG,',
'          C.CODCLIENTE,',
'          C.TIPO_DOC_IDENTIFICACION,',
'          C.NUM_DOC_IDENTIFICACION,',
'          OC_CLIENTES.NOMBRE_CLIENTE(P.CODCLIENTE),',
'          P.PRIMANETA_LOCAL,',
'          PNJ.TIPO_PERSONA,',
'          PNJ.FECNACIMIENTO,',
'          PNJ.CODACTIVIDAD,',
'          AE.DESCACTIVIDAD,',
'          PNJ.NACIONALIDAD,',
'          PC.DESC_PLAN,',
'          DP.CODPLANPAGO,',
'          PP.DESCPLAN,',
'          PNJ.CODPROVRES,',
'          PR.DESCESTADO,',
'          OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''TIPNEGO'', P.CODTIPONEGOCIO),',
'          P.CODRIESGOREA,',
'          MC.CODFORMACOBRO,',
'          VL.DESCVALLST,',
'          RA.NUMAUTORTIPSEG',
' ORDER BY P.IDPOLIZA, DP.IDETPOL',
' '))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Consulta Asegurado'
);
