wwv_flow_imp_page.create_page(
 p_id=>26
,p_name=>unistr('Consulta Gen\00E9rica de P\00F3liza')
,p_alias=>unistr('CONSULTA-GEN\00C9RICA-DE-P\00D3LIZA')
,p_step_title=>unistr('Consulta Gen\00E9rica de P\00F3liza')
,p_reload_on_submit=>'A'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Espera a que la p\00E1gina est\00E9 lista'),
'$(document).ready(function () {',
'  // Delegar evento change sobre radio buttons dentro del reporte',
'  $("#DatoGen").on("change", "input[name=''f02'']", function (event) {',
'    ',
'    var elem = event.target; // este es el radio button clicado',
'    var marcado = $(elem).is('':checked'');',
'    var seqid = $(elem).parent().find("input[name=''f02'']").val();',
'',
'    console.log(''marcado: '' + marcado);',
'    console.log(''seqid: '' + seqid);',
'',
'    ',
'apex.server.process( "Dato General Seleccionado", {',
'                x01: marcado,',
'                x02: seqid',
'    }, {',
'    // datatype: ''text'',',
'    success: function (data){',
'      //$s("P26_CODIGO_CLIENTE",data.cliente);',
'      $s("P26_CODIGO_CLIENTE",data.cliente);',
'      apex.region("Poliza").refresh();',
'      apex.region("Movimiento").refresh();',
'      apex.region("Pago").refresh();',
'      apex.region("Siniestro").refresh();',
'            }',
'    });',
'  });',
'});',
'',
unistr('// Espera a que la p\00E1gina est\00E9 lista'),
'$(document).ready(function () {',
'  // Delegar evento change sobre radio buttons dentro del reporte',
'  $("#Poliza").on("change", "input[name=''f01'']", function (event) {',
'    ',
'    var elem = event.target; // este es el radio button clicado',
'    var marcado = $(elem).is('':checked'');',
'    var seqid = $(elem).parent().find("input[name=''f01'']").val();',
'',
'    console.log(''marcado: '' + marcado);',
'    console.log(''seqid: '' + seqid);',
'',
'apex.server.process( "RegistroSeleccionado", {',
'                x01: marcado,',
'                x02: seqid',
'    }, {',
'    // datatype: ''text'',',
'    success: function (data){',
'      $s("P26_POLIZA",data.poliza);',
'      apex.region("Movimiento").refresh();',
'      apex.region("Pago").refresh();',
'      apex.region("Siniestro").refresh();',
'            }',
'    });',
'  });',
'});',
''))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'18'
