wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(251770788463046405)
,p_plug_name=>unistr('P\00F3lizas Contratadas')
,p_region_name=>'Poliza'
,p_parent_plug_id=>wwv_flow_imp.id(251768971715046386)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    SELECT  /*apex_item.radiogroup(1,P.IDPOLIZA ||'':'')Selecionar,*/',
'            OC_CLIENTES.NOMBRE_CLIENTE(C.CODCLIENTE) NOMBRE_CONTRATANTE,',
'            P.NUMPOLUNICO POLIZA_UNICO,',
'            P.IDPOLIZA POLIZA_CONSEC,',
'            OC_MONEDA.DESCRIPCION_MONEDA(P.COD_MONEDA) MONEDA,',
'            TO_CHAR(P.PRIMANETA_MONEDA,''FML999G999G999G999G990D00'') PRIMA_NETA_MON_ORIG,',
'	        TO_CHAR(P.PRIMANETA_LOCAL ,''FML999G999G999G999G990D00'') PRIMA_NETA_MON_NAC,',
'	        TO_CHAR(P.SUMAASEG_MONEDA ,''FML999G999G999G999G990D00'') SUM_ASEG_MON_ORIG,',
'	        TO_CHAR(P.SUMAASEG_LOCAL  ,''FML999G999G999G999G990D00'') SUM_ASEG_MON_NAC,',
'	        TO_CHAR(P.FECINIVIG,''DD/MM/YYYY'') INICIO_VIGENCIA,',
'	        TO_CHAR(P.FECFINVIG,''DD/MM/YYYY'') FIN_VIGENCIA,',
'	        OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'',P.STSPOLIZA) STATUS_POLIZA,',
'	        TO_CHAR(P.FECANUL,''DD/MM/YYYY'') FECHA_CANCELACION,',
'            D.IDTIPOSEG AS TIPO_SEGURO,',
'	        P.CODPLANPAGO PLAN_PAGO',
'    FROM POLIZAS P, DETALLE_POLIZA D,CLIENTES C',
'    WHERE P.IDPOLIZA = D.IDPOLIZA',
'     	AND D.IDETPOL = 1',
'        AND P.CODCLIENTE IN ( SELECT C.CODCLIENTE',
'						    FROM POLIZAS P, CLIENTES C, PERSONA_NATURAL_JURIDICA PNJ',
'							WHERE P.FECEMISION BETWEEN NVL(TO_DATE(:P26_FECHA_INICIAL,''DD/MM/YYYY''),P.FECEMISION) AND  NVL(TO_DATE(:P26_FECHA_FINAL,''DD/MM/YYYY''),P.FECEMISION)',
'								AND C.CODCLIENTE = P.CODCLIENTE',
'								AND P.CODCLIENTE = NVL(:P26_CODCLIENTEFILTRO,P.CODCLIENTE)',
'								AND PNJ.TIPO_DOC_IDENTIFICACION = C.TIPO_DOC_IDENTIFICACION',
'								AND PNJ.NUM_DOC_IDENTIFICACION  = C.NUM_DOC_IDENTIFICACION  )',
'        AND C.CODCLIENTE = P.CODCLIENTE',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P26_FECHA_FINAL,P26_FECHA_INICIAL,P26_CODCLIENTEFILTRO'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
