wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(251772475434046422)
,p_plug_name=>unistr('Movimientos a las P\00F3lizas Contradas')
,p_region_name=>'Movimiento'
,p_parent_plug_id=>wwv_flow_imp.id(251768971715046386)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
' SELECT OC_CLIENTES.NOMBRE_CLIENTE(C.CODCLIENTE) NOMBRE_CONTRATANTE,',
'	       P.NUMPOLUNICO POLIZA_UNICO,',
'	       P.IDPOLIZA POLIZA_CONSEC,',
'	       E.IDENDOSO NUM_ENDOSO,',
'	       OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''TIPENDOS'',E.TIPOENDOSO) TIPO_ENDOSO,',
'	       F.IDFACTURA NUM_RECIBO,',
'	       OC_MONEDA.DESCRIPCION_MONEDA(P.COD_MONEDA) MONEDA,',
'	       TO_CHAR(F.MONTO_FACT_MONEDA,''FML999G999G999G999G990D00'') PRIMA_NETA_MON_ORIG,',
'	       TO_CHAR(F.MONTO_FACT_LOCAL,''FML999G999G999G999G990D00'') PRIMA_NETA_MON_NAC,',
'	       TO_CHAR(E.SUMA_ASEG_LOCAL,''FML999G999G999G999G990D00'') SUM_ASEG_MON_ORIG,',
'	       TO_CHAR(E.SUMA_ASEG_LOCAL,''FML999G999G999G999G990D00'') SUM_ASEG_MON_NAC,',
'	       TO_CHAR(F.FECVENC,''DD/MM/YYYY'') INICIO_VIGENCIA,',
'	       TO_CHAR(F.FECFINVIG,''DD/MM/YYYY'') FIN_VIGENCIA,',
'	       OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'',F.STSFACT) STATUS_RECIBO,',
'	       TO_CHAR(F.FECANUL,''DD/MM/YYYY'') FECHA_CANCELACION',
'	  FROM POLIZAS  P, --1874',
'	       CLIENTES C,',
'	       ENDOSOS  E,',
'	       FACTURAS F',
'	 WHERE P.CODCLIENTE IN( SELECT C.CODCLIENTE',
'                          FROM POLIZAS P,  --46088',
'                               CLIENTES C,',
'                               PERSONA_NATURAL_JURIDICA PNJ',
'                         WHERE P.FECEMISION BETWEEN NVL(TO_DATE(:P26_FECHA_INICIAL,''DD/MM/YYYY''),P.FECEMISION) AND  NVL(TO_DATE(:P26_FECHA_FINAL,''DD/MM/YYYY''),P.FECEMISION)',
'                           AND C.CODCLIENTE = P.CODCLIENTE',
'                           AND PNJ.TIPO_DOC_IDENTIFICACION = C.TIPO_DOC_IDENTIFICACION',
'                           AND PNJ.NUM_DOC_IDENTIFICACION  = C.NUM_DOC_IDENTIFICACION)',
'	   AND C.CODCLIENTE = P.CODCLIENTE',
'	   AND E.IDPOLIZA = P.IDPOLIZA',
'	   AND P.IDPOLIZA = NVL(:P26_POLIZA,P.IDPOLIZA)',
'	   AND F.IDPOLIZA = P.IDPOLIZA',
'	   AND F.IDENDOSO = E.IDENDOSO',
'	 ORDER BY P.IDPOLIZA,E.IDENDOSO,F.IDFACTURA'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P26_FECHA_INICIAL,P26_FECHA_FINAL,P26_POLIZA'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>unistr('Movimientos a las P\00F3lizas Contradas')
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
