wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(251916959212699094)
,p_plug_name=>'Pagos Efectuados'
,p_region_name=>'Pago'
,p_parent_plug_id=>wwv_flow_imp.id(251768971715046386)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>40
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
' SELECT OC_CLIENTES.NOMBRE_CLIENTE(C.CODCLIENTE) NOMBRE_CONTRATANTE,',
'		       P.NUMPOLUNICO POLIZA_UNICO,',
'		       P.IDPOLIZA POLIZA_CONSEC,',
'		       F.IDENDOSO NUM_ENDOSO,',
'		       --E.TIPOENDOSO TIPO_ENDOSO,',
'		       F.IDFACTURA NUM_RECIBO,',
'		       P.COD_MONEDA MONEDA,',
'		       TO_CHAR(F.MONTO_FACT_MONEDA,''FML999G999G999G999G990D00'') PRIMA_NETA_MON_ORIG,',
'		       TO_CHAR(F.MONTO_FACT_LOCAL ,''FML999G999G999G999G990D00'') PRIMA_NETA_MON_NAC,',
'		       OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'',F.STSFACT) STATUS_RECIBO,',
'               (SELECT OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''TIPENDOS'',TIPOENDOSO)',
'           FROM   ENDOSOS',
'           WHERE  IDPOLIZA = P.IDPOLIZA',
'           AND    IDENDOSO =  F.IDENDOSO) TIPO_ENDOSO,',
'           M.MEDIO_PAGO,',
'           TO_CHAR(M.FECHA_PAGO,''DD/MM/YYYY'') FECHA_PAGO ,',
'		       TO_CHAR(F.FECSTS,''DD/MM/YYYY'') FECSTS',
'		  FROM POLIZAS  P, ',
'		       CLIENTES C,',
'		       FACTURAS F,',
'              (SELECT TO_DATE(OC_TRANSACCION.FECHATRANSACCION(P.IDTRANSACCION),''DD/MM/YYYY'')FECHA_PAGO,',
'		   	          OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''FORMPAGO'',P.FORMPAGO) MEDIO_PAGO,',
'                         IDFACTURA, P.FECHA',
'           FROM   PAGOS P) M',
'		  WHERE P.CODCLIENTE IN',
'		(',
'		SELECT C.CODCLIENTE',
'		  FROM POLIZAS P, CLIENTES C, PERSONA_NATURAL_JURIDICA PNJ',
'		 WHERE P.FECEMISION BETWEEN NVL(TO_DATE(:P26_FECHA_INICIAL,''DD/MM/YYYY''),P.FECEMISION) AND  NVL(TO_DATE(:P26_FECHA_FINAL,''DD/MM/YYYY''),P.FECEMISION)',
'',
'		   AND C.CODCLIENTE = P.CODCLIENTE',
'',
'		   AND PNJ.TIPO_DOC_IDENTIFICACION = C.TIPO_DOC_IDENTIFICACION',
'		   AND PNJ.NUM_DOC_IDENTIFICACION  = C.NUM_DOC_IDENTIFICACION',
'		 )',
'		   AND C.CODCLIENTE = P.CODCLIENTE',
'		   --',
'		   AND F.IDPOLIZA = P.IDPOLIZA',
'		   AND F.STSFACT  = ''PAG''',
'		   ---',
'		   AND P.IDPOLIZA = NVL(:P26_POLIZA ,P.IDPOLIZA)',
'           AND M.IDFACTURA    =  F.IDFACTURA',
'           AND    TRUNC(M.FECHA) = TRUNC(F.FECSTS)',
'		 ORDER BY P.IDPOLIZA,NUM_ENDOSO,NUM_RECIBO'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P26_POLIZA,P26_FECHA_INICIAL,P26_FECHA_FINAL'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
