 p_id=>wwv_flow_imp.id(251920177559699127)
,p_plug_name=>unistr('Siniestros de las P\00F3lizas Contratadas')
,p_region_name=>'Siniestro'
,p_parent_plug_id=>wwv_flow_imp.id(251768971715046386)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>60
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'		SELECT OC_CLIENTES.NOMBRE_CLIENTE(C.CODCLIENTE) NOMBRE_CONTRATANTE,',
'		       P.NUMPOLUNICO POLIZA_UNICO,',
'		       P.IDPOLIZA POLIZA_CONSEC,',
'		       S.IDSINIESTRO NUM_SINIESTRO,',
'		       S.COD_MONEDA MONEDA,',
'		       S.MONTO_RESERVA_LOCAL  ESTIMACIONES_MOC_NAC,',
'           S.MONTO_RESERVA_MONEDA ESTIMACIONES_MON_ORIG,',
'		       S.MONTO_PAGO_LOCAL,',
'           S.MONTO_PAGO_MONEDA ,',
'          (S.MONTO_RESERVA_LOCAL  - S.MONTO_PAGO_LOCAL) SALDO_MON_ORIG,',
'          (S.MONTO_RESERVA_MONEDA - S.MONTO_PAGO_MONEDA ) SALDO_MON_NAC,',
'           ( SELECT TO_DATE(OC_TRANSACCION.FECHATRANSACCION(MAX(IDTRANSACCION)),''MM/DD/YYYY'')',
'            FROM (		  ',
'            SELECT NVL(MAX(IDTRANSACCION),0) IDTRANSACCION',
'            FROM   COBERTURA_SINIESTRO_ASEG',
'            WHERE  IDSINIESTRO = S.IDSINIESTRO ',
'            UNION ALL',
'            SELECT NVL(MAX(IDTRANSACCION),0) IDTRANSACCION',
'            FROM   COBERTURA_SINIESTRO',
'            WHERE  IDSINIESTRO = S.IDSINIESTRO  )) FECHA_REGISTRO,',
'            (SELECT TO_DATE(OC_TRANSACCION.FECHATRANSACCION(MAX (IDTRANSACCION)),''MM/DD/YYYY'')',
'		   	   FROM (',
'		   	   SELECT NVL(MAX(IDTRANSACCION),0) IDTRANSACCION',
'		   	   FROM   APROBACIONES',
'	         WHERE  IDSINIESTRO = S.IDSINIESTRO',
'	         UNION ALL',
'	         SELECT NVL(MAX(IDTRANSACCION),0) IDTRANSACCION',
'	         FROM   APROBACION_ASEG',
'	         WHERE  IDSINIESTRO = S.IDSINIESTRO))FECHA_PAGO',
'		  FROM POLIZAS P, --1874',
'		       CLIENTES C,',
'		       SINIESTRO S',
'		  WHERE P.CODCLIENTE IN (',
'									SELECT C.CODCLIENTE',
'									  FROM POLIZAS P ,  --46088',
'									       CLIENTES C,',
'									       PERSONA_NATURAL_JURIDICA PNJ',
'									 WHERE P.FECEMISION BETWEEN NVL(TO_DATE(:P26_FECHA_INICIAL,''DD/MM/YYYY''),P.FECEMISION) AND  NVL(TO_DATE(:P26_FECHA_FINAL,''DD/MM/YYYY''),P.FECEMISION)',
'									   --',
'									   AND C.CODCLIENTE = P.CODCLIENTE',
'									   --',
'									   AND PNJ.TIPO_DOC_IDENTIFICACION = C.TIPO_DOC_IDENTIFICACION',
'									   AND PNJ.NUM_DOC_IDENTIFICACION  = C.NUM_DOC_IDENTIFICACION',
'									 )',
'		   AND C.CODCLIENTE = P.CODCLIENTE',
'		   AND S.IDPOLIZA = P.IDPOLIZA',
'		   AND S.IDPOLIZA   = NVL(:P26_POLIZA,S.IDPOLIZA)'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P26_FECHA_INICIAL,P26_FECHA_FINAL,P26_POLIZA'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>unistr('Siniestros de las P\00F3lizas Contratadas')
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
