wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(174035022447374756)
,p_event_id=>wwv_flow_imp.id(174033568952374741)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_name=>'Tab_Poliza'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var active   = apex.region("Tab_Container").widget().aTabs("getActive"),',
'    href     = active.href,',
'    staticID = href.replace(/^#SR_/, ""); ',
'',
'var codCliente = $v("P26_CODCLIENTEFILTRO");',
'',
'if (staticID === ''Poliza'') {',
'',
'    if (codCliente && codCliente.length > 0) {',
'        apex.message.clearErrors();',
'        apex.region("Poliza").refresh();',
'  ',
unistr('        //funci\00F3n que ayuda a seleccionar el primer registro de grid cuando no lo toma por defaul '),
'function seleccionarPrimerRegistro(igId, gridId) {',
'    var primeraFila = document.querySelector("#" + gridId + " .a-GV-row td");',
'    if (primeraFila) {',
'        primeraFila.click();',
'       // console.log("Registro seleccionado en " + igId);',
'    } else {',
'       // console.log("Fila no encontrada en " + igId + ", reintentando...");',
'        setTimeout(function () { seleccionarPrimerRegistro(igId, gridId); }, 300);',
'    }',
'}',
' ',
'apex.region("Poliza").widget().on("apexafterrefresh", function () {G',
'    setTimeout(function () { seleccionarPrimerRegistro("Poliza", "Poliza_ig_grid_vc"); }, 300);',
'});',
'setTimeout(function () { ',
'    seleccionarPrimerRegistro("Poliza", "Poliza_ig_grid_vc"); ',
'    }, ',
'500);',
'',
'    } else {',
'        apex.message.clearErrors();',
'        apex.message.showErrors([{',
'            type: "error",',
'            location: ["page"],',
unistr('            message: "Seleccione un Registro para ver sus P\00F3lizas.",'),
'            unsafe: false',
'        }]);',
'',
unistr('        apex.message.alert("Seleccione un Registro para ver sus P\00F3lizas.", function() {'),
'',
'});',
'',
'        apex.region("Tab_Container").widget().aTabs("getTabs")["#SR_Poliza"].movePrevious();',
'        apex.region("Tab_Container").widget().aTabs("activate", 0);',
'    }',
'} '))
