wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(174034351907374749)
,p_event_id=>wwv_flow_imp.id(174033687462374743)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cNOMBRE             VARCHAR2(4000);',
'	cAPELLIDO_PATERNO   VARCHAR2(4000);',
'	cAPELLIDO_MATERNO   VARCHAR2(4000);',
'    vl_Camino           NUMBER;',
'    vl_Rownum           NUMBER;',
'',
'    CURSOR l_cursor IS',
'        SELECT DISTINCT C.CODCLIENTE,',
'	        OC_CLIENTES.NOMBRE_CLIENTE(C.CODCLIENTE) NOMBRE_CONTRATANTE,',
'	        OC_ACTIVIDADES_ECONOMICAS.DESCRIPCION(PNJ.CODACTIVIDAD) SECTOR_ECONOMICO,',
'	        OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''NACION'',PNJ.NACIONALIDAD) NACIONALIDAD,',
'	        OC_PROVINCIA.NOMBRE_PROVINCIA(PNJ.CODPAISRES,PNJ.CODPROVRES) AREA_GEOGRAFICA,',
'            C.NUM_DOC_IDENTIFICACION,C.TIPOCLIENTE,EC.TIPORIESGO RIESGOACT , C.STSCLIENTE',
'	    FROM POLIZAS P,  ',
'	     	DETALLE_POLIZA D,',
'	        CLIENTES C,',
'	        PERSONA_NATURAL_JURIDICA PNJ,',
'            ACTIVIDADES_ECONOMICAS EC',
'	    WHERE P.CODCIA     = 1',
'	    	AND P.IDPOLIZA = D.IDPOLIZA',
'            AND D.IDETPOL = D.IDETPOL',
'            AND D.CODCIA = 1',
'            AND C.CODCLIENTE = P.CODCLIENTE ',
'            AND PNJ.TIPO_DOC_IDENTIFICACION = C.TIPO_DOC_IDENTIFICACION',
'            AND PNJ.NUM_DOC_IDENTIFICACION  = C.NUM_DOC_IDENTIFICACION',
'            AND NVL(PNJ.CODACTIVIDAD,''DESC'') = EC.CODACTIVIDAD',
'    		AND ROWNUM <=0;',
'',
'    l_collection_name CONSTANT VARCHAR2(30) := ''MI_REPORTE'';',
'',
'BEGIN',
'',
'    IF apex_collection.collection_exists(l_collection_name) THEN',
'        apex_collection.truncate_collection(l_collection_name);',
'    ELSE',
'        apex_collection.create_collection(l_collection_name);',
'    END IF;',
'',
'IF :P26_FECHA_INICIAL IS NOT NULL OR :P26_FECHA_FINAL IS NOT NULL OR :P26_CODIGO_CLIENTE IS NOT NULL OR :P26_NUM_DOC_IDENTIFICACION IS NOT NULL OR',
'    :P26_IDPOLIZA IS NOT NULL OR :P26_NUMPOLUNICO IS NOT NULL OR :P26_PRODUCTO IS NOT NULL OR :P26_CODAGRUPADOR IS NOT NULL OR :P26_NOMBRES IS NOT NULL OR',
'    :P26_APELLIDO_PATERNO IS NOT NULL OR  :P26_APELLIDO_MATERNO IS NOT NULL THEN ',
'',
'    cNOMBRE            := :P26_NOMBRES;',
'    cAPELLIDO_PATERNO  := :P26_APELLIDO_PATERNO;',
'	cAPELLIDO_MATERNO  := :P26_APELLIDO_MATERNO;',
'	',
'   :P26_CODCLIENTEFILTRO := '''';',
'   :P26_IDPOLIZA :='''';',
'',
'',
'    FOR r IN l_cursor LOOP',
'        apex_collection.add_member(',
'            p_collection_name => l_collection_name,',
'            p_n001 => r.CODCLIENTE, ',
'            p_c001 => r.NOMBRE_CONTRATANTE,  ',
'            p_c002 => r.SECTOR_ECONOMICO,',
'            p_c003 => r.NACIONALIDAD,',
'            p_c004 => r.AREA_GEOGRAFICA,',
'            p_c005 => r.NUM_DOC_IDENTIFICACION,',
'            p_c006 => r.TIPOCLIENTE,',
'            p_c007 => r.RIESGOACT,',
'            p_c008 => r.STSCLIENTE',
'        );',
'    END LOOP;',
'   ',
'ELSE',
'    apex_error.add_error (',
unistr('            p_message          => ''Debes ingresar al menos un filtro de b\00FAsqueda.'','),
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END IF;',
'EXCEPTION',
'    WHEN OTHERS THEN ',
'        apex_error.add_error (',
'            p_message          => ''Error al ejecutar la consulta: ''||SQLERRM,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;'))
,p_attribute_02=>'P26_FECHA_INICIAL,P26_FECHA_FINAL,P26_CODIGO_CLIENTE,P26_NUM_DOC_IDENTIFICACION,P26_IDPOLIZA,P26_NUMPOLUNICO,P26_PRODUCTO,P26_CODAGRUPADOR,P26_NOMBRES,P26_APELLIDO_PATERNO,P26_APELLIDO_MATERNO'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_build_option_id=>wwv_flow_imp.id(243684582477890037)
);
