wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(285281061626069394)
,p_plug_name=>unistr('Administraci\00F3n de Riesgos')
,p_region_name=>'List_Riesgo'
,p_parent_plug_id=>wwv_flow_imp.id(285236215448961278)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select CODEMPRESA,',
'       CODCIA,',
'       ID_PROCESO,',
'       ID_PERSONA,',
'       NOMBRE,',
'       PATERNO,',
'       MATERNO,',
'       CURP,',
'       RFC,',
'       FECHA_NACIMIENTO,',
'       LISTA,',
'       ESTATUS,',
'       DEPENDENCIA,',
'       PUESTO,',
'       IDDISPO,',
'       CURP_OK,',
'       IDREL,',
'       PARENTESCO,',
'       RAZONSOC,',
'       RFCMORAL,',
'       ISSSTE,',
'       IMSS,',
'       INGRESOS,',
'       NOMCOMP,',
'       APELLIDOS,',
'       ENTIDAD,',
'       SEXO,',
'       AREA,',
'       FECHA_PROCESO,',
'       ST_PROCESO,',
'       REGISTRO,',
'       USRMODIFICA,',
'       apex_item.radiogroup(1,codempresa||'':''|| codcia||'':''|| id_proceso||'':''||ID_PERSONA||'':'')Selecionar',
'  from CAT_QEQ',
'  WHERE 1 = 1',
'  AND UPPER(NVL(NOMCOMP,''NO_DATA'')) LIKE  ''%'' ||UPPER(NVL(:P27_B_NOMBRE,NVL(NOMCOMP,''NO_DATA''))) ||''%''',
'  AND UPPER(NVL(RFC,''NO_DATA'')) = UPPER(NVL(:P27_B_RFC,NVL(RFC,''NO_DATA'')))',
'  AND UPPER(NVL(FECHA_NACIMIENTO,''NO_DATA'')) = UPPER(NVL(:P27_B_FECHA_NACIMIENTO,NVL(FECHA_NACIMIENTO,''NO_DATA'')))',
'  AND UPPER(NVL(CURP,''NO_DATA'')) = UPPER(NVL(:P27_B_CURP,NVL(CURP,''NO_DATA'')))',
'  ORDER BY ID_PERSONA'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P27_B_NOMBRE,P27_B_CURP,P27_B_FECHA_NACIMIENTO,P27_B_RFC'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
