wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(252502592026246828)
,p_event_id=>wwv_flow_imp.id(252502134644246828)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'//console.log(this.triggeringElement);',
'var elem = this.triggeringElement;',
'var marcado = $(elem).is('':checked'');',
'var seqid = $(elem).parent().find("input[name=''f01'']").val();',
'',
'console.log(marcado);',
'console.log(seqid);',
'',
'  apex.server.process("Registro_Seleccionado", {',
'    x01: marcado,',
'    x02: seqid',
'}, {',
'    success: function(data) {',
'      //alert(data.idproceso )',
'',
'        $s("P27_CODEMPRESA_P",data.codempresa);',
'        $s("P27_CODCIA_P",data.codcia);',
'        $s("P27_ID_PROCESO_P",data.idproceso);',
'        $s("P27_ID_PERSONA_P",data.id_persona);',
'',
'       $s("P27_CODEMPRESA",data.codempresa);',
