wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(252496079979246683)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Registro_Seleccionado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    declare ',
'  v_codempresa     CAT_QEQ.codempresa%type;',
'  v_codcia         CAT_QEQ.codcia%type;',
'  v_id_proceso     CAT_QEQ.id_proceso%type;',
'  v_id_persona       CAT_QEQ.id_persona%type;',
'',
'  CDESC_LISTA   VARCHAR2(400);',
'  cDESC_ESTATUS_PARENTESCO VARCHAR2(400);',
'  cDESC_ESTATUS  VARCHAR2(400);',
'',
'CURSOR c_datos is',
'select CODEMPRESA,',
'        CODCIA,',
'        ID_PROCESO,',
'        ID_PERSONA,',
'        NOMBRE,',
'        PATERNO,',
'        MATERNO,',
'        CURP,',
'        RFC,',
'        FECHA_NACIMIENTO,',
'        LISTA,',
'        ESTATUS,',
'        DEPENDENCIA,',
'        PUESTO,',
'        IDDISPO,',
'        CURP_OK,',
'        IDREL,',
'        PARENTESCO,',
'        RAZONSOC,',
'        RFCMORAL,',
'        ISSSTE,',
'        IMSS,',
'        INGRESOS,',
'        NOMCOMP,',
'        APELLIDOS,',
'        ENTIDAD,',
'        SEXO,',
'        AREA,',
'        FECHA_PROCESO,',
'        ST_PROCESO,',
'        REGISTRO,',
'        USRMODIFICA',
'from CAT_QEQ',
'where   codcia = v_codcia',
'   and codempresa = v_codempresa',
'   and id_proceso = v_id_proceso',
'   and id_persona = v_id_persona;',
'',
'tdatos c_datos%rowtype;',
'',
'begin',
'',
' ',
'  begin',
'      select substr(APEX_APPLICATION.G_x02, 1, instr(APEX_APPLICATION.G_x02, '':'') - 1) p1,',
'             substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 1) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - instr(APEX_APPLICATION.G_x02, '':'', 1, 1) - 1) p3,',
'             substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - 1) p3,',
'             substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - 1) p27',
'            -- substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 5) - instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - 1) p5',
'        into v_codempresa,',
'             v_codcia,',
'             v_id_proceso,',
'             v_id_persona',
'        from dual;',
'    exception',
'      when others then',
'        v_codempresa := null;',
'         v_codcia := null;',
'         v_id_proceso := null;',
'         v_id_persona := null;',
'    end;',
'',
'open c_datos;',
'loop ',
'fetch c_datos into tdatos;',
' exit when c_datos%notfound;',
'',
'  apex_json.open_object;',
'  apex_json.write(''codempresa'', v_codempresa);',
'  apex_json.write(''codcia'', v_codcia);',
'  apex_json.write(''idproceso'', v_id_proceso);',
'  apex_json.write(''id_persona'', v_id_persona);',
'',
'  BEGIN',
'  	SELECT A.CAGE_VALOR_LARGO ',
'	  INTO CDESC_LISTA',
'      FROM SAI_CAT_GENERAL A',
'	  WHERE A.CAGE_CD_CATALOGO = 5',
'	    AND A.CAGE_NOM_CONCEP  = tdatos.LISTA;',
'  EXCEPTION ',
'    WHEN OTHERS THEN ',
'    CDESC_LISTA := NULL;',
'  END;',
'',
'begin',
'SELECT A.CAGE_VALOR_LARGO ',
'  INTO cDESC_ESTATUS',
'  FROM SAI_CAT_GENERAL A',
' WHERE A.CAGE_CD_CATALOGO = 6',
'   AND A.CAGE_NOM_CONCEP  = tdatos.ESTATUS; ',
'exception ',
'when others then ',
'  cDESC_ESTATUS := null;',
'end;',
'',
'BEGIN',
'  SELECT A.CAGE_VALOR_LARGO ',
'    INTO cDESC_ESTATUS_PARENTESCO',
'    FROM SAI_CAT_GENERAL A',
'   WHERE A.CAGE_CD_CATALOGO = 6',
'     AND A.CAGE_NOM_CONCEP  = tdatos.ESTATUS; ',
'EXCEPTION',
'	WHEN OTHERS THEN ',
'	     cDESC_ESTATUS_PARENTESCO := NULL;',
'END;',
'',
'   apex_json.write(''NOMBRE'',tdatos.NOMBRE);',
'apex_json.write(''PATERNO'',tdatos.PATERNO);',
'apex_json.write(''MATERNO'',tdatos.MATERNO);',
'apex_json.write(''CURP'',tdatos.CURP);',
'apex_json.write(''RFC'',tdatos.RFC);',
'apex_json.write(''FECHA_NACIMIENTO'',tdatos.FECHA_NACIMIENTO);',
'apex_json.write(''LISTA'',CDESC_LISTA); --tdatos.LISTA);',
'apex_json.write(''ESTATUS'', cDESC_ESTATUS); --tdatos.ESTATUS);',
'apex_json.write(''ESTATUS_PARENTESCO'', cDESC_ESTATUS_PARENTESCO);',
'apex_json.write(''DEPENDENCIA'',tdatos.DEPENDENCIA);',
'apex_json.write(''PUESTO'',tdatos.PUESTO);',
'apex_json.write(''IDDISPO'',tdatos.IDDISPO);',
'apex_json.write(''CURP_OK'',tdatos.CURP_OK);',
'apex_json.write(''IDREL'',tdatos.IDREL);',
'apex_json.write(''PARENTESCO'',tdatos.PARENTESCO);',
'apex_json.write(''RAZONSOC'',tdatos.RAZONSOC);',
'apex_json.write(''RFCMORAL'',tdatos.RFCMORAL);',
'apex_json.write(''ISSSTE'',tdatos.ISSSTE);',
'apex_json.write(''IMSS'',tdatos.IMSS);',
'apex_json.write(''INGRESOS'',tdatos.INGRESOS);',
'apex_json.write(''NOMCOMP'',tdatos.NOMCOMP);',
'apex_json.write(''APELLIDOS'',tdatos.APELLIDOS);',
'apex_json.write(''ENTIDAD'',tdatos.ENTIDAD);',
'apex_json.write(''SEXO'',tdatos.SEXO);',
'apex_json.write(''AREA'',tdatos.AREA);',
'apex_json.write(''FECHA_PROCESO'',tdatos.FECHA_PROCESO);',
'apex_json.write(''ST_PROCESO'',tdatos.ST_PROCESO);',
'apex_json.write(''REGISTRO'',tdatos.REGISTRO);',
'apex_json.write(''USRMODIFICA'',tdatos.USRMODIFICA);',
'',
'',
'  apex_json.write(''error'', '''');',
'  apex_json.close_object;',
' end loop;',
' close c_datos;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(252494340966246425)
,p_internal_uid=>39930505013925200
);
end;
