,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Espera a que la p\00E1gina est\00E9 lista'),
'$(document).ready(function () {',
'  // Delegar evento change sobre radio buttons dentro del reporte',
'  $("#Transaccion").on("change", "input[name=''f01'']", function (event) {',
'    ',
'    var elem = event.target; // este es el radio button clicado',
'    var marcado = $(elem).is('':checked'');',
'    var seqid = $(elem).parent().find("input[name=''f01'']").val();',
'',
'    console.log(''marcado: '' + marcado);',
'    console.log(''seqid: '' + seqid);',
'',
'    ',
'// Enviar el cambio a PL/SQL',
'apex.server.process("Registro", {',
'    x01: marcado,',
'    x02: seqid',
'}, {',
'    success: function(data) {',
'    //  alert(data.fecevaluacion )',
'',
'        $s("P28_OBSERVACIONES",data.OBSERVACIONES);',
'        $s("P28_NUM_APORTE_REALIZADOS",data.NUMAPORTREALFE);',
'        $s("P28_NUM_RETIROS_REALIZADOS",data.NUMRETREALFE);',
'        $s("P28_IMPTEACUMAPORFE",data.IMPTEACUMAPORFE);',
'        $s("P28_STATUS_REVISION",data.STATUSREVISION);',
'        $s("P28_RESULTADO_EVAL",data.RESULTADOEVAL);',
'        $s("P28_CODEMPRESA_S", data.codempresa);',
'        $s("P28_IDTIPOSEG_S", data.idtiposeg);',
'        $s("P28_IDPOLIZA_S", data.idpoliza);',
'        $s("P28_IDETPOL_S", data.idetpol);',
'        $s("P28_NUMSECUENCIA_S", data.numsecuencia);',
'        $s("P28_CODASEGURADO_S", data.codasegurado);',
'        $s("P28_FECEVALUACION_S", data.fecevaluacion);',
'',
'        apex.region("Historico_TR").refresh();',
'    }',
'    });',
'  });',
'});'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'18'
,p_last_updated_by=>'HRODRIGUEZ'
,p_last_upd_yyyymmddhh24miss=>'20250819131615'
);
