wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(253370170341768922)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Actualiza Masivo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'',
'v_rowid rowid;',
'',
'cursor c_datos is ',
'select CODCIA,',
'       CODEMPRESA,',
'       IDTIPOSEG,',
'       IDPOLIZA,',
'       IDETPOL,',
'       NUMSECUENCIA,',
'       CODASEGURADO,',
'       NOMBREASEGURADO,',
'       FORMPAGO,',
'       FECEVALUACION,',
'       NUMAPORTPLANFE,',
'       NUMAPORTCRITOK,',
'       NUMAPORTREALFE,',
'       IMPTEPLANAPORFE,',
'       IMPTEAPORCRITOK,',
'       IMPTEACUMAPORFE,',
'       NUMRETICRITOK,',
'       NUMRETREALFE,',
'       RESULTADOEVAL,',
'       STATUSREVISION,',
'       OBSERVACIONES,',
'       FECHAREVISION,',
'       USUARIOREVISA',
'  from ADMON_ACTIVI_FONDOS',
'  where rowid = v_rowid;',
'',
'  tcursor c_datos%rowtype;',
'',
'begin',
'',
' FOR i IN 1 .. APEX_APPLICATION.G_F02.COUNT LOOP',
'',
'    begin',
'      select substr(APEX_APPLICATION.G_F02(i), 1, instr(APEX_APPLICATION.G_F02(i), '':'') - 1) p1',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := null;',
'    end;',
'    --raise_application_error(-20100, ''vrow ''||v_rowid);',
'',
'      if v_rowid is not null then ',
'        open c_datos;',
'        loop',
'        fetch c_datos into tCursor;',
'        exit when c_datos%notfound;',
'           begin ',
'                UPDATE SICAS_OC.ADMON_ACTIVI_FONDOS',
'                 SET  STATUSREVISION = :P28_STATUS_REVISION_U,',
'                      OBSERVACIONES = :P28_WS_OBSERVACIONES',
'                WHERE CODCIA = tCursor.CODCIA',
'                  AND CODEMPRESA = tCursor.CODEMPRESA',
'                  AND IDTIPOSEG = tCursor.IDTIPOSEG',
'                  AND IDPOLIZA = tCursor.IDPOLIZA',
'                  AND IDETPOL = tCursor.IDETPOL',
'                  AND NUMSECUENCIA = tCursor.NUMSECUENCIA',
'                  AND CODASEGURADO = tCursor.CODASEGURADO',
'                  AND TRUNC(FECEVALUACION) = trunc(tCursor.FECEVALUACION);',
'            end;',
'',
'            OC_ADMON_ACTIVI_FONDOS_H.INSERTA(tCursor.CODCIA,',
'                                            tCursor.CODEMPRESA,',
'                                            tCursor.Idtiposeg,',
'                                            tCursor.Idpoliza,',
'                                            tCursor.Idetpol,',
'                                            tCursor.Numsecuencia,',
'                                            tCursor.Codasegurado,',
'                                            tCursor.NombreAsegurado,		',
'                                            tCursor.FORMPAGO,',
'                                            tCursor.FECEVALUACION,',
'                                            tCursor.NumAportPlanFE,	',
'                                            tCursor.NumAportCritOK,',
'                                            tCursor.NumAportRealfe,',
'                                            tCursor.ImptePlanAporfe,',
'                                            tCursor.ImpteAporCritOK,',
'                                            tCursor.ImpteAcumAporfe,',
'                                            tCursor.NumRetiCritOK,',
'                                            tCursor.NumRetRealfe,',
'                                            tCursor.ResultadoEval,',
'                                            :P28_STATUS_REVISION_U,',
'                                            :P28_WS_OBSERVACIONES,',
'                                            SYSDATE,',
'                                            :APP_USER);',
'',
'        end loop;',
'        close c_datos;',
'      end if;',
'  END LOOP;',
'  :P28_STATUS_REVISION_U := NULL;',
'  :P28_WS_OBSERVACIONES  := NULL;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(254239290224420809)
,p_process_success_message=>unistr('Proceso ejecutado con \00E9xito!')
,p_internal_uid=>40804595376447439
