'   ELSE',
'',
'      IF :P28_IND_TRANSACPOLAHORROINV = ''S'' THEN',
'         GENERAR_TRANSAC_POL_AHORRO_INV(:P28_ARCH_TRANSPOLAHORROINV,',
'                                        TO_DATE(:P28_FECHA_DESDE,''DD/MM/YYYY''), ',
