wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(253369770877768918)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Registro'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'',
'cDesc   varchar2(400);',
'  v_rowid rowid;',
'',
'  cursor c_datos is ',
'select CODCIA,',
'       CODEMPRESA,',
'       IDTIPOSEG,',
'       IDPOLIZA,',
'       IDETPOL,',
'       NUMSECUENCIA,',
'       CODASEGURADO,',
'       NOMBREASEGURADO,',
'       FORMPAGO,',
'       TO_CHAR(FECEVALUACION,''DD/MM/YYYY'') FECEVALUACION,',
'       NUMAPORTPLANFE,',
'       NUMAPORTCRITOK,',
'       NUMAPORTREALFE,',
'       IMPTEPLANAPORFE,',
'       IMPTEAPORCRITOK,',
'       IMPTEACUMAPORFE,',
'       NUMRETICRITOK,',
'       NUMRETREALFE,',
'       RESULTADOEVAL,',
'       STATUSREVISION,',
'       OBSERVACIONES,',
'       FECHAREVISION,',
'       USUARIOREVISA',
'  from ADMON_ACTIVI_FONDOS',
'  where rowid = v_rowid;',
'',
'  t_datos c_datos%rowtype;',
' begin',
'',
' ',
'  begin',
'      select substr(APEX_APPLICATION.G_x02, 1, instr(APEX_APPLICATION.G_x02, '':'') - 1) p1',
'        into v_rowid',
'        from dual;',
'    exception',
'      when others then',
'        v_rowid := null;',
'    end;',
'',
'    open c_datos;',
'    loop',
'    fetch c_datos into t_datos;',
'    exit when c_datos%notfound;',
'',
'begin',
'SELECT VL.DESCVALLST',
'  into cDesc',
'  FROM VALORES_DE_LISTAS VL',
' WHERE VL.CODLISTA = ''CATSTRIE''',
'  AND CODVALOR =   t_datos.STATUSREVISION;',
' exception ',
' when others then',
'   cDesc := null;',
' end;',
' ',
'',
'        apex_json.open_object;',
'',
'       apex_json.write(''NUMRETREALFE'', t_datos.NUMRETREALFE);',
'       apex_json.write(''IMPTEACUMAPORFE'', t_datos.IMPTEACUMAPORFE);',
'       apex_json.write(''NUMAPORTREALFE'', t_datos.NUMAPORTREALFE);',
'       apex_json.write(''STATUSREVISION'', cDesc); --t_datos.STATUSREVISION);',
'       apex_json.write(''OBSERVACIONES'', t_datos.OBSERVACIONES);',
'       apex_json.write(''RESULTADOEVAL'', t_datos.RESULTADOEVAL);',
'',
'       apex_json.write(''codempresa'', t_datos.CODEMPRESA);',
'       apex_json.write(''idtiposeg'', t_datos.IDTIPOSEG);',
'       apex_json.write(''idpoliza'', t_datos.IDPOLIZA);',
'       apex_json.write(''idetpol'', t_datos.IDETPOL);',
'       apex_json.write(''numsecuencia'', t_datos.NUMSECUENCIA);',
'       apex_json.write(''codasegurado'', t_datos.CODASEGURADO);',
'       apex_json.write(''fecevaluacion'', t_datos.FECEVALUACION);',
'',
'        apex_json.write(''v_rowid'', v_rowid);',
'        apex_json.close_object;',
'',
'    end loop;',
'    close c_datos;',
'',
'',
' end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>40804195912447435
);
end;
