,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT P.IDPOLIZA ,                     ',
'       P.CODCLIENTE ,',
'       TRIM(TRIM(PNJ.NOMBRE)||'' ''||TRIM(PNJ.APELLIDO_PATERNO)||'' ''||TRIM(PNJ.APELLIDO_MATERNO)) NOMBRECLI ,     ',
'       TO_CHAR(P.FECINIVIG,''DD/MM/YYYY'')   FECINIVIG ,',
'       TO_CHAR(P.FECFINVIG,''DD/MM/YYYY'')   FECFINVIG ,                                                                          ',
'       P.PRIMANETA_LOCAL PRIMANETALOCAL,                     ',
'       PP.descplan FORMAPAGO, ',
'       VL.DESCVALLST ',
'',
'FROM   POLIZAS P',
'      ,CLIENTES C',
'      ,PERSONA_NATURAL_JURIDICA      PNJ',
'      ,DETALLE_POLIZA DP',
'      ,PLAN_DE_PAGOS PP',
'      ,VALORES_DE_LISTAS VL',
'WHERE C.CODCLIENTE = P.CODCLIENTE',
'  AND PNJ.TIPO_DOC_IDENTIFICACION = C.TIPO_DOC_IDENTIFICACION',
'  AND PNJ.NUM_DOC_IDENTIFICACION = C.NUM_DOC_IDENTIFICACION ',
'  AND DP.IDPOLIZA = P.IDPOLIZA',
'  AND DP.IDETPOL = (SELECT MIN(DP2.IDETPOL )',
'                      FROM DETALLE_POLIZA DP2',
'                     WHERE DP2.IDPOLIZA = DP.IDPOLIZA)',
'  AND DP.IDTIPOSEG = :P29_LI_PRODUCTOS_CONS',
'  AND PP.CODPLANPAGO = P.CODPLANPAGO',
'  AND VL.CODLISTA = ''ESTADOS''',
'  AND VL.CODVALOR = P.STSPOLIZA ',
'  ORDER BY P.IDPOLIZA     ;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P29_LI_PRODUCTOS_CONS'
