,p_plug_display_sequence=>90
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT P.IDPOLIZA,   ',
'			 P.CODCLIENTE,                  ',
'       TS.IDTIPOSEG,',
'       TS.DESCRIPCION,',
'			 TO_CHAR(p.fecinivig,''DD/MM/YYYY'')  							FECINICIO, ',
'			 TO_CHAR(p.fecfinvig,''DD/MM/YYYY'')  							FECFIN,                                                                        ',
'       P.PRIMANETA_LOCAL PRIMANETALOCAL,                     ',
'       PP.descplan FORMAPAGO, ',
'       VL.DESCVALLST ',
'FROM   POLIZAS P',
'      ,DETALLE_POLIZA DP',
'      ,TIPOS_DE_SEGUROS TS',
'      ,PLAN_DE_PAGOS PP',
'      ,VALORES_DE_LISTAS VL',
'WHERE P.CODCLIENTE = :P29_CLIENTES_POLIZAS',
'  AND DP.IDPOLIZA = P.IDPOLIZA',
'  AND DP.IDETPOL = (SELECT MIN(DP2.IDETPOL )',
'                      FROM DETALLE_POLIZA DP2',
'                     WHERE DP2.IDPOLIZA = DP.IDPOLIZA)',
'  AND TS.IDTIPOSEG = DP.IDTIPOSEG    ',
'  AND PP.CODPLANPAGO = P.CODPLANPAGO',
'  AND VL.CODLISTA = ''ESTADOS''',
'  AND VL.CODVALOR = P.STSPOLIZA                    ',
'  ORDER BY P.IDPOLIZA '))
