wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(252574206426431814)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Iniciar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
' 	cmesanio			varchar2(7);',
'begin',
':P29_COMPANIA := oc_empresas.nombre_compania(nvl(:codcia,1));',
'',
' select TO_char(sysdate,''MM/YYYY'') into cmesanio from dual;',
'   :P29_FECHA_DESDE := TO_DATE(''01/''||cmesanio,''DD/MM/YYYY'');',
'   SELECT LAST_DAY(TO_CHAR(SYSDATE)) INTO :P29_FECHA_HASTA  FROM DUAL;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>40008631461110331
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(252712358355793629)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generar Reporte'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P29_IND_TRANSACPOLPRODALTO = ''S'' THEN ',
'GENERAR_TRANSAC_POL_PROD_ALTO (:P29_ARCH_TRANSPOLPRODNIVALTO, ',
'                               :P29_FORMATO,',
'                               TO_DATE(:P29_FECHA_DESDE,''DD/MM/YYYY''),    ',
'                               TO_DATE(:P29_FECHA_HASTA,''DD/MM/YYYY''),',
'                               :CODCIA, ',
'                               :P29_TRANSACPOLPRODALTO_FILE_ID);',
'END IF;',
'IF :P29_IND_PRODNIVRIESALTO = ''S'' THEN  ',
' GENERAR_PROD_NIV_RIES_ALTO(:P29_ARCH_PRODNIVRIESALTO,',
'                           TO_DATE(:P29_FECHA_DESDE,''DD/MM/YYYY''),    ',
'                               TO_DATE(:P29_FECHA_HASTA,''DD/MM/YYYY''),',
'                           :P29_FORMATO,',
'                           :CODCIA, ',
'                           :P29_PRODNIVRIESALTO_FILE_ID);',
'END IF;',
'IF :P29_IND_POLIZASNIVRIESALTO = ''S'' THEN',
' GENERAR_POL_NIV_RIES_ALTO(:P29_ARCH_POL_NIVRIESALTO,',
'                           TO_DATE(:P29_FECHA_DESDE,''DD/MM/YYYY''),    ',
'                               TO_DATE(:P29_FECHA_HASTA,''DD/MM/YYYY''),',
'                           :P29_PRODUCTOS,',
'                           :P29_FORMATO,',
'                           :CODCIA,',
'                           :P29_POLIZASNIVRIESALTO_FILE_ID);',
'END IF;',
'',
'IF :P29_IND_CLIENTERIESGOALTO = ''S'' THEN',
'  GENERAR_CLIENTES_RIESGO_ALTO(:P29_ARCH_CLIENTERIESGOALTO,',
'                           TO_DATE(:P29_FECHA_DESDE,''DD/MM/YYYY''),    ',
'                               TO_DATE(:P29_FECHA_HASTA,''DD/MM/YYYY''),',
'                           :P29_FORMATO,',
'                           :CODCIA,',
'                           :P29_CLIENTERIESGOALTO_FILE_ID);',
'END IF;',
'',
'IF :P29_IND_POLCLIENIVRIESGOALTO = ''S'' THEN',
