'  // Delegar evento change sobre radio buttons dentro del reporte',
'  $("#QRiesgo").on("change", "input[name=''f01'']", function (event) {',
'    ',
'    var elem = event.target; // este es el radio button clicado',
'    var marcado = $(elem).is('':checked'');',
'    var seqid = $(elem).parent().find("input[name=''f01'']").val();',
'',
'    console.log(''marcado: '' + marcado);',
'    console.log(''seqid: '' + seqid);',
'',
'    ',
'apex.server.process( "RegistroSeleccionado", {',
'                x01: marcado,',
'                x02: seqid',
'    }, {',
'    // datatype: ''text'',',
'    success: function (data){',
'      $s("P30_COD_ASEGURADO",data.asegurado);',
'      $s("P30_COD_ASEGURADO_SEND",data.asegurado);',
'      $s("P30_ASEGURADO",data.nom_asegurado);',
'       $s("P30_COD_CLIENTE",data.cliente);',
'       $s("P30_COD_CLIENTE_SEND",data.cliente);',
'      $s("P30_CLIENTE",data.nom_cliente);',
'      $s("P30_NOMBRE",data.nombre);',
'      $s("P30_OBSERVACIONES",data.observaciones);',
'',
'      $s("P30_IDPOLIZA",data.poliza);',
'      $s("P30_IDPROCESO",data.proceso);',
