wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(252571629332431788)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Libera_Poliza'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	nDummy           NUMBER;',
'BEGIN',
'    IF :P30_IDPOLIZA IS NOT NULL THEN ',
'   	  --',
'   	  UPDATE POLIZAS A',
'         SET A.STSPOLIZA       = ''SOL'',',
'             A.PLDSTAPROBADA   = ''S'',',
'             A.PLDUSUARIOAPROB = :APP_USER',
'       WHERE A.IDPOLIZA = :P30_IDPOLIZA;',
'      --       ',
'      UPDATE ADMON_RIESGO AR',
'         SET AR.OBSERVACIONES = AR.OBSERVACIONES||'' POLIZA LIBERADA POR USUARIO ''',
'       WHERE AR.CODEMPRESA = 1',
'         AND AR.CODCIA     = :CODCIA',
'         AND AR.ID_PROCESO = :P30_IDPROCESO',
'         AND AR.IDPOLIZA   = :P30_IDPOLIZA;',
'      --',
'   	  INSERT INTO ADMON_RIESGO_H ',
'   	   (CODEMPRESA,     CODCIA,',
'        ID_PROCESO,     IDPOLIZA,',
'        CODCLIENTE,     CODASEGURADO,',
'        ORIGEN,         ST_RESOLUCION,',
'        FE_ESTATUS,     TP_RESOLUCION,',
'        FECHA_PROCESO,  USUARIO',
'       )',
'       VALUES',
'       (1,  :CODCIA,',
'        :P30_IDPROCESO,  :P30_IDPOLIZA ,',
'        :P30_COD_CLIENTE_SEND,  :P30_COD_ASEGURADO_SEND,',
'        :P30_ORIGEN,      ''APRE'',',
'        SYSDATE,                   ''APRTMP'',',
'        TRUNC(SYSDATE),            :APP_USER',
'       );',
'    ELSE ',
unistr('      RAISE_APPLICATION_ERROR(-20100,''Debe Seleccionar la P\00F3liza a Liberar'');'),
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(251983978786195033)
,p_process_success_message=>unistr('P\00F3liza Liberada')
,p_internal_uid=>40006054367110305
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(251981372203195006)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'RegistroSeleccionado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'   v_poliza polizas.NUMPOLUNICO%type;',
'',
'   cursor c_datos is ',
'   select CODEMPRESA,',
'           CODCIA,',
'           ID_PROCESO,',
'           IDPOLIZA,',
'           STSPOLIZA,',
'           CODCLIENTE,',
'           CODASEGURADO,',
'           OC_ASEGURADO.NOMBRE_ASEGURADO(CODCIA,CODEMPRESA, CODASEGURADO) NOM_ASEGURADO,',
'           OC_CLIENTES.NOMBRE_CLIENTE(CODCLIENTE) NOM_CLIENTE,',
'           ORIGEN,',
'           TIPO_DOC_IDENTIFICACION,',
'           NUM_DOC_IDENTIFICACION,',
'           NOMBRE,',
'           ST_RESOLUCION,',
'           FE_ESTATUS,',
'           TP_RESOLUCION,',
'           OBSERVACIONES,',
'           FECHA_PROCESO,',
'           USUARIO',
'  from ADMON_RIESGO',
' where rowid = v_poliza;',
'',
' tdatos c_datos%rowtype;',
'',
'begin',
'',
'',
' begin',
'      select substr(APEX_APPLICATION.G_x02, 1, instr(APEX_APPLICATION.G_x02, '':'') - 1) p1',
'            -- substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 1) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - instr(APEX_APPLICATION.G_x02, '':'', 1, 1) - 1) p3,',
'            -- substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 2) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - instr(APEX_APPLICATION.G_x02, '':'', 1, 2) - 1) p3,',
'            -- substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 3) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - instr(APEX_APPLICATION.G_x02, '':'', 1, 3) - 1) p4,',
'            -- substr(APEX_APPLICATION.G_x02, instr(APEX_APPLICATION.G_x02, '':'', 1, 4) + 1, instr(APEX_APPLICATION.G_x02, '':'', 1, 5) - instr(APEX_APPLICATION.G_x02, '':'', 1, 4) - 1) p5',
'        into v_poliza',
'        from dual;',
'    exception',
'      when others then',
'        v_poliza := null;',
'    end;',
'',
'    open c_datos;',
'    loop ',
'    fetch c_datos into tdatos;',
'    exit when c_datos%notfound;',
'',
'    apex_json.open_object;',
'    apex_json.write(''poliza'', tdatos.IDPOLIZA);',
'    apex_json.write(''proceso'', tdatos.ID_PROCESO);',
'    apex_json.write(''origen'', tdatos.origen);',
'',
'',
'    apex_json.write(''asegurado'', tdatos.CODASEGURADO);',
'    apex_json.write(''nom_asegurado'', tdatos.NOM_ASEGURADO);',
'    apex_json.write(''cliente'', tdatos.CODCLIENTE);',
'    apex_json.write(''nom_cliente'', tdatos.NOM_CLIENTE);',
'    apex_json.write(''nombre'', tdatos.NOMBRE);',
'    apex_json.write(''observaciones'', tdatos.observaciones);',
'',
'    apex_json.close_object;',
'',
'    end loop;',
'    close c_datos;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>39415797237873523
);
end;
