 p_id=>wwv_flow_imp.id(369407281748265333)
,p_plug_name=>unistr('ADMINISTRACI\00D3N DE RIESGOS')
,p_parent_plug_id=>wwv_flow_imp.id(362077703048354166)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>20
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    s_qly       varchar2(4000);',
'    condiciones varchar2(4000);',
'BEGIN',
'    s_qly := ''SELECT ORIGEN_REGISTRO,',
'        ID_PROCESO,',
'        IDPOLIZA,',
'        NUMSINIESTRO,',
'        ORIGEN,',
'        NOMBRE,',
'        FECHA_PROCESO,',
'        NUM_DOC_IDENTIFICACION,',
'        ST_RESOLUCION,',
'        TP_RESOLUCION,',
'        OBSERVACIONES,',
'        CASE WHEN ORIGEN_REGISTRO = ''''SIN'''' THEN',
'            ''''AQUA''''',
'            WHEN ORIGEN_REGISTRO = ''''EMI'''' THEN',
'            ''''#258AE9''''',
'        END BG_COLOR',
'            FROM VW_ADMON_RIESGO_UNION'';',
'',
'    IF :P37_SELECT_ORI_REG IS NOT NULL THEN',
'        condiciones := '' WHERE ORIGEN_REGISTRO = ''''''||:P37_SELECT_ORI_REG||'''''''';',
'    ELSIF :P37_SER_ID_ADMON_RIESG IS NOT NULL THEN',
'        IF condiciones IS NULL THEN',
'            condiciones := '' WHERE '';',
'        ELSE',
'            condiciones := '' AND '';',
'        END IF;',
'',
'        condiciones := condiciones ||''ID_PROCESO = ''|| :P37_SER_ID_ADMON_RIESG;',
'    ELSIF (:P37_FEC_INI IS NOT NULL) AND (:P37_FEC_FIN IS NOT NULL) THEN',
'        IF condiciones IS NULL THEN',
'            condiciones := '' WHERE '';',
'        ELSE',
'            condiciones := '' AND '';',
'        END IF;',
'',
'        condiciones := condiciones ||''FECHA_PROCESO BETWEEN ''''''||:P37_FEC_INI||'''''' AND ''''''||:P37_FEC_FIN||'''''''';',
'    END IF;',
'',
'    s_qly := s_qly||condiciones;',
'',
'    return s_qly;',
'END;'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>unistr('ADMINISTRACI\00D3N DE RIESGOS')
