wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(222779053687430641)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'REP_HIST_RIESG'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_ctx       apex_exec.t_context;',
'    l_export    apex_data_export.t_export;',
'    s_qly       varchar2(2000);',
'    condiciones varchar2(2000);',
'BEGIN',
'',
'    s_qly := ''SELECT ',
'                ORIGEN_REGISTRO AS "Origen Registro",',
unistr('                IDPOLIZA AS "P\00F3liza",'),
'                NUMSINIESTRO AS "No. Siniestro",',
'                ORIGEN AS "Origen",',
'                NOMBRE AS "NOMBRE/ENTIDAD MORAL",',
'                NUM_DOC_IDENTIFICACION AS "RFC",',
'                TO_CHAR(FECHA_PROCESO, ''''DD/MM/YYYY'''') AS "Fecha Proceso",',
'                (SELECT DISTINCT VL.DESCVALLST ',
'                FROM VALORES_DE_LISTAS VL',
'                WHERE VL.CODLISTA IN (''''STSPLDES'''',''''CATSTRIE'''')',
'                AND VL.CODVALOR = ST_RESOLUCION',
unistr('                ) AS "Estatus Operaci\00F3n",'),
'                (SELECT VL.DESCVALLST  ',
'                FROM VALORES_DE_LISTAS VL',
'                WHERE VL.CODLISTA = ''''CATRESOL''''',
'                AND VL.CODVALOR = TP_RESOLUCION',
unistr('                ) AS "Tipo Resoluci\00F3n",'),
'                OBSERVACIONES AS "Observaciones"',
'            FROM VW_ADMON_RIESGO_UNION_HIST'';',
'',
'    -- ORIGEN REGISTRO',
'    IF :P37_SELECT_ORI_REG_REP IS NOT NULL THEN',
'        condiciones := '' WHERE ORIGEN_REGISTRO = :P37_SELECT_ORI_REG_REP'';',
'    END IF;',
'',
'    -- RANGO FECHAS',
'    IF :P37_FEC_INI_REP IS NOT NULL AND :P37_FEC_FIN_REP IS NOT NULL THEN',
'        IF condiciones IS NULL THEN condiciones := '' WHERE ''; ELSE condiciones := condiciones || '' AND ''; END IF;',
'        condiciones := condiciones || ''FECHA_PROCESO BETWEEN TO_DATE(:P37_FEC_INI_REP,''''DD/MM/YYYY'''') AND TO_DATE(:P37_FEC_FIN_REP,''''DD/MM/YYYY'''')''||chr(10);',
'    END IF;',
'',
unistr('    -- ESTATUS OPERACI\00D3N'),
'    IF :P37_STS_REP IS NOT NULL THEN',
'        IF condiciones IS NULL THEN condiciones := '' WHERE ''; ELSE condiciones := condiciones || '' AND ''; END IF;',
'        condiciones := condiciones || ''ST_RESOLUCION IN (',
'        SELECT column_value',
'        FROM apex_string.split(:P37_STS_REP, '''':'''')',
'        )'';',
'    END IF;',
'    ',
'    -- ORIGEN',
'    IF :P37_ORIGEN_REP IS NOT NULL THEN',
'        IF condiciones IS NULL THEN condiciones := '' WHERE ''; ELSE condiciones := condiciones || '' AND ''; END IF;',
'        condiciones := condiciones || ''ORIGEN IN (',
'        SELECT column_value',
'        FROM apex_string.split(:P37_ORIGEN_REP, '''':'''')',
'        )'';',
'    END IF;',
'',
'    -- TIPO RESOLUCION',
'    IF :P37_TP_REP IS NOT NULL THEN',
'        IF condiciones IS NULL THEN condiciones := '' WHERE ''; ELSE condiciones := condiciones || '' AND ''; END IF;',
'        condiciones := condiciones || ''TP_RESOLUCION IN (',
'        SELECT column_value',
'        FROM apex_string.split(:P37_TP_REP, '''':'''')',
'        )'';',
'    END IF;',
'',
'    s_qly := s_qly || condiciones;',
'',
'    l_ctx := apex_exec.open_query_context(',
'        p_location  => apex_exec.c_location_local_db,',
'        p_sql_query => s_qly',
'    );',
'',
'    l_export := apex_data_export.export(',
'        p_context   => l_ctx,',
'        p_format    => apex_data_export.c_format_xlsx,',
'        p_file_name => ''hist_riesg.xlsx''',
'    );',
'',
'    apex_exec.close(l_ctx);',
'    apex_data_export.download(p_export => l_export);',
'    apex_application.stop_apex_engine;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(222766963443430624)
,p_process_when=>'DL_XLSX'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>59490136880484442
);
end;
