'DECLARE',
'    s_lqy   varchar2(4000);',
'    nCount  number;',
'BEGIN',
'    SELECT MAX(IDCONSEC)',
'    INTO nCount',
'    FROM PLD_OBSERVACIONES',
'    WHERE IDPROCESO = 7',
'    AND PROCESO_ACTIVI = :P38_ID_PROCESO;',
'',
'    IF nCount IS NOT NULL THEN',
'        s_lqy := ''select  DESCRIPCION,',
'                    FECHAINSERT,',
'                    USRINSERT',
'            from PLD_OBSERVACIONES',
'            WHERE IDPROCESO = 7',
'            AND PROCESO_ACTIVI = ''||:P38_ID_PROCESO||',
'            ''AND IDCONSEC != ''||nCount||',
'            ''ORDER BY IDCONSEC DESC'';',
'    ELSE',
'        s_lqy := ''select  DESCRIPCION,',
'                    FECHAINSERT,',
'                    USRINSERT',
'            from PLD_OBSERVACIONES',
'            WHERE 1=0',
'            ORDER BY IDCONSEC DESC'';',
'    END IF;',
'    ',
'    return s_lqy;',
'END;'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
