wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(222811008602443213)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE_CHANGE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    /*IF :P38_ORIGEN_REGISTRO = ''SIN'' THEN',
'',
'        UPDATE SICAS_OC.ADMON_RIESGO_SINIESTROS',
'        SET ST_RESOLUCION   = :P38_STS_RESOLUCION,',
'            FE_ESTATUS      = SYSDATE,',
'            TP_RESOLUCION   = :P38_TP_RESOLUCION,',
'            OBSERVACIONES   = :P38_OBSERVACIONES,',
'            USUARIO = V(''APP_USER'')',
'        WHERE ID_PROCESO = :P38_ID_PROCESO',
'        AND IDPOLIZA = :P38_IDPOLIZA',
'        AND NUMSINIESTRO = :P38_IDSINIESTRO',
'        AND NUM_DOC_IDENTIFICACION =:P38_RFC;',
'',
'    ELSIF :P38_ORIGEN_REGISTRO = ''EMI'' THEN',
'',
'        UPDATE SICAS_OC.ADMON_RIESGO',
'        SET ST_RESOLUCION   = :P38_STS_RESOLUCION,',
'            FE_ESTATUS      = SYSDATE,',
'            TP_RESOLUCION   = :P38_TP_RESOLUCION,',
'            OBSERVACIONES   = :P38_OBSERVACIONES,',
'            USUARIO = V(''APP_USER'')',
'        WHERE ID_PROCESO = :P38_ID_PROCESO',
'        AND IDPOLIZA = :P38_IDPOLIZA',
'        AND NUM_DOC_IDENTIFICACION =:P38_RFC;',
'',
'    END IF;*/',
'',
'    OC_PLD_ADMONRIESGO.ACTUALIZA_REGISTRO(:P38_ORIGEN_REGISTRO,:P38_ID_PROCESO,:P38_STS_RESOLUCION,:P38_TP_RESOLUCION,:P38_OBSERVACIONES);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(222802440388443200)
,p_internal_uid=>59522091795497014
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(222811337446443214)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_CLOSE_WINDOW'
,p_process_name=>'Close Dialog'
,p_attribute_02=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
