,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>59522420639497015
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(222810530338443213)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set_Values'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    vl_Total NUMBER;',
'BEGIN',
'    IF :P38_ORIGEN_REGISTRO = ''SIN'' THEN',
'',
'        :P38_ORIGEN_REG := ''Siniestro'';',
'        :BG_COLOR := ''aqua'';',
'        ',
'        SELECT  IDPOLIZA,NUMSINIESTRO,STSPOLIZA,ORIGEN,NUM_DOC_IDENTIFICACION,',
'                NOMBRE_BENEFICIARIO,TO_CHAR(FE_ESTATUS,''DD/MM/YYYY''),OBSERVACIONES,FECHA_PROCESO,USUARIO,',
'                ST_RESOLUCION,TP_RESOLUCION',
'        INTO    :P38_IDPOLIZA, :P38_IDSINIESTRO, :P38_STS_POLIZA, :P38_ORIGEN, :P38_RFC,',
'                :P38_NOMBRE,:P38_FEC_ESTATUS,:P38_OBSERVACIONES,:P38_FECHA_PROCESO,:P38_USUARIO,',
'                :P38_STS_RESOLUCION,:P38_TP_RESOLUCION',
'        FROM  ADMON_RIESGO_SINIESTROS',
'        WHERE ID_PROCESO = :P38_ID_PROCESO;',
'',
'    ELSIF :P38_ORIGEN_REGISTRO = ''EMI'' THEN',
'',
unistr('        :P38_ORIGEN_REG := ''Emisi\00F3n'';'),
'        :BG_COLOR := ''#258ae9'';',
'        ',
'        SELECT  IDPOLIZA,''N/A'' NUMSINIESTRO,STSPOLIZA,ORIGEN,NUM_DOC_IDENTIFICACION,',
'                NOMBRE,TO_CHAR(FE_ESTATUS,''DD/MM/YYYY''),OBSERVACIONES,FECHA_PROCESO,USUARIO,',
'                ST_RESOLUCION,TP_RESOLUCION',
'        INTO    :P38_IDPOLIZA, :P38_IDSINIESTRO, :P38_STS_POLIZA, :P38_ORIGEN, :P38_RFC,',
'                :P38_NOMBRE,:P38_FEC_ESTATUS,:P38_OBSERVACIONES,:P38_FECHA_PROCESO,:P38_USUARIO,',
'                :P38_STS_RESOLUCION,:P38_TP_RESOLUCION',
'        FROM  ADMON_RIESGO',
'        WHERE ID_PROCESO = :P38_ID_PROCESO;',
'',
'    END IF;',
'',
'    IF :P38_RFC IS NOT NULL THEN --SI TENEMOS RFC, BUSCAMOS EL ROL',
'',
'        SELECT COUNT(1)',
'        INTO vl_Total',
'        FROM SICAS_OC.ASEGURADO',
'        WHERE NUM_DOC_IDENTIFICACION = :P38_RFC;',
'',
'        IF vl_Total = 0 THEN',
'            SELECT COUNT(1)',
'            INTO vl_Total',
'            FROM SICAS_OC.CLIENTES',
'            WHERE NUM_DOC_IDENTIFICACION = :P38_RFC;',
'',
'            IF vl_Total = 0 THEN',
'                SELECT COUNT(1)',
'                INTO vl_Total',
'                FROM SICAS_OC.BENEF_SIN',
'                WHERE (NOMBRE LIKE ''%''|| :P38_NOMBRE ||''%''',
'                OR NOMBRE||'' ''||APELLIDO_PATERNO||'' ''||APELLIDO_MATERNO = :P38_NOMBRE)',
'                AND NUM_DOC_TRIBUTARIO = :P38_RFC;',
'',
'                IF vl_Total > 0 THEN',
'                    :P38_ROL := ''BENEFICIARIO'';',
'                END IF;',
'            ELSE',
'                :P38_ROL := ''CLIENTE'';',
'            END IF;',
'        ELSE',
'            :P38_ROL := ''ASEGURADO'';',
'        END IF;',
'',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>59521613531497014
);
end;
