'BEGIN',
'    INSERT INTO SICAS_OC.ADMON_ACTIVI(',
'        CODCIA,',
'        ID_PROCESO,',
'        IDPOLIZA,',
'        IDETPOL,',
'        ORIGEN,',
'        CODCLIENTE,',
'        ST_RIESGO,',
'        OBSERVACIONES,',
'        FE_PROCESO,',
'        FE_HORA_PROCESO,',
'        USUARIO_ACTUA,',
'        FE_ALTA_REG,',
'        TIPO_DOC_IDENTIFICACION,',
'        NUM_DOC_IDENTIFICACION',
'    )',
'    VALUES(',
'        1,',
'        :P39_IDALERTA,',
'        :P39_IDPOLIZA,',
'        1,',
'        :P39_ORIGEN,',
'        0,',
'        ''PEND'',',
'        :P39_OBSERVACIONES,',
'        SYSDATE,',
'        SYSDATE,',
'        coalesce(sys_context(''APEX$SESSION'',''APP_USER''),user),',
'        SYSDATE,',
'        ''RFC'',',
'        :P39_RFC',
'    );',
'',
'    IF :P39_TIPO_OPER = ''SIN'' THEN',
'        UPDATE SICAS_OC.ADMON_RIESGO_SINIESTROS',
'            SET ST_RESOLUCION = ''OPIN''',
'        WHERE ID_PROCESO = :P39_IDALERTA',
'        AND NUMSINIESTRO = :P39_NUMSINIESTRO;',
'    ELSIF :P39_TIPO_OPER = ''EMI'' THEN',
'        UPDATE SICAS_OC.ADMON_RIESGO',
'            SET ST_RESOLUCION = ''OPIN''',
'        WHERE ID_PROCESO = :P39_IDALERTA',
'        AND IDPOLIZA = :P39_IDPOLIZA;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(222820484845454292)
,p_internal_uid=>59535140531508098
);
