wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(266508645407411721)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Registra Denuncia'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	dummy					NUMBER;',
'	vl_IDenuncia	NUMBER;',
'	vl_Folio			VARCHAR2(30);',
'	vl_Fecha    DATE;',
'BEGIN',
'		',
'		IF :P41_NARRACION IS NOT NULL THEN',
'			',
'			BEGIN',
'			',
'				SELECT MAX(IDDENUNCIA)',
'				INTO vl_IDenuncia',
'				FROM SICAS_OC.PLD_OPE_PREOCUPANTES;',
'				',
'				vl_IDenuncia := (vl_IDenuncia+1);',
'				',
'				SELECT LPAD(vl_IDenuncia,4,''0'')',
'				INTO  vl_Folio',
'				FROM DUAL;',
'				',
'				vl_Folio := ''ANON-''||TO_CHAR(SYSDATE,''YYYY'')||''-''||vl_Folio;',
'				vl_Fecha := TO_DATE(:P41_FECHAREPORTE,''DD/MM/YYYY'');',
'',
'				INSERT INTO SICAS_OC.PLD_OPE_PREOCUPANTES',
'					(CODCIA,CODEMPRESA,ST_OPERACION,FEC_ALTA,NOM_REPORTA,FEC_DETECCION,FEC_REPORTE,',
'					CODCANALDENUNCIA,CODTIPOREPORTE,DESCRIPCION_DENUNCIA,IDDENUNCIA,FOLIO_DENUNCIA,CODUSUARIO_ALTA,',
'					NOMBRE_PERSONA_REPORTADA,CODCOMPORTAMIENTO	) ',
'					',
'					VALUES (1,1,''PEND'',SYSDATE,:P41_NOMBRE,vl_Fecha,SYSDATE,''SICAS'',''ANONIM'',:P41_NARRACION,',
'					vl_IDenuncia,vl_Folio,''SICAS_OC'',:P41_REPORTADA,''MALPRA'');',
'					',
unistr('					--Envia correo de notificaci\00F3n'),
'					SICAS_OC.OC_RIESGOS_PLD.CORREO_PLD_ANONIMO(vl_Folio);',
'					',
'			END;',
'			',
'		ELSE',
'			RAISE_APPLICATION_ERROR(-20000,''El campo de denuncia es obligatorio.'');		',
' 		END IF;',
'',
'',
'EXCEPTION',
'		WHEN OTHERS THEN',
'			RAISE_APPLICATION_eRROR(-20000,SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(266508179119411716)
,p_process_success_message=>unistr('Tu denuncia ha sido registrada con \00E9xito. Te recordamos que toda la informaci\00F3n proporcionada ser\00E1 tratada de manera an\00F3nima y confidencial. Gracias por tu confianza.')
,p_internal_uid=>103219728600465522
);
