wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(459504716291365837)
,p_plug_name=>'Alertamiento'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    q.IDPOLIZA,',
'    q.IDSINIESTRO,',
'    q.ASEGURADO,',
'    q.BENEFICIARIO,',
'    q.NUM_APROBACION,',
'    q.MONTO_LOCAL,',
'    q.MONTO_MONEDA,',
'    q.CTA_CLABE,',
'    q.COBERTURA,',
'    q.FECHA_PAGO',
'FROM (',
'    SELECT',
'        AA.IDPOLIZA,',
'        AA.IDSINIESTRO,',
'',
'        S.COD_ASEGURADO || '' - '' ||',
'        OC_PERSONA_NATURAL_JURIDICA.NOMBRE_PERSONA(S.COD_ASEGURADO) AS ASEGURADO,',
'',
'        AA.BENEF || '' - '' || BS.NOMBRE AS BENEFICIARIO,',
'',
'        AA.NUM_APROBACION,',
'        AA.MONTO_LOCAL,',
'        AA.MONTO_MONEDA,',
'',
'        BS.CUENTA_CLAVE AS CTA_CLABE,',
'',
'        AA.CODCOBERT AS COBERTURA,',
'',
'        AA.FECPAGO AS FECHA_PAGO,',
'',
'        ROW_NUMBER() OVER (',
'            PARTITION BY BS.CUENTA_CLAVE, AA.CODCOBERT',
'            ORDER BY AA.FECPAGO, AA.NUM_APROBACION, AA.IDSINIESTRO, AA.IDPOLIZA, AA.BENEF',
'        ) AS rn',
'',
'    FROM APROBACION_ASEG AA',
'    JOIN BENEF_SIN BS',
'      ON BS.IDSINIESTRO = AA.IDSINIESTRO',
'     AND BS.IDPOLIZA   = AA.IDPOLIZA',
'     AND BS.BENEF      = AA.BENEF',
'    LEFT JOIN SINIESTRO S',
'      ON S.IDSINIESTRO = AA.IDSINIESTRO',
'    WHERE AA.STSAPROBACION = ''PAG''',
'      AND AA.CODCOBERT IN (''FALLEC'',''MA'',''MUEACC'')',
'      AND BS.CUENTA_CLAVE IS NOT NULL',
') q',
'WHERE q.FECHA_PAGO >= DATE ''2025-12-01''',
'  AND q.rn > 1',
'ORDER BY q.FECHA_PAGO, q.CTA_CLABE, q.COBERTURA ;',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
