,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    AA.IDSINIESTRO,',
'    AA.IDPOLIZA,',
'    (SELECT DISTINCT IDTIPOSEG FROM DETALLE_POLIZA WHERE IDPOLIZA=AA.IDPOLIZA AND ROWNUM = 1',
'    ) PRODUCTO,',
'    AA.COD_ASEGURADO,',
'    AA.MONTO_LOCAL,',
'    AA.MONTO_MONEDA,',
'    AA.FECPAGO,',
'    aa.CODCOBERT,',
'    BS.BENEF || '' - '' || BS.NOMBRE AS BENEFICIARIO,',
'    BS.TIPO_ID_TRIBUTARIO,',
'    BS.NUM_DOC_TRIBUTARIO,',
'    BS.ENT_FINANCIERA,',
'    BS.CUENTA_CLAVE,',
'    BS.NUMCUENTABANCARIA',
'FROM APROBACION_ASEG AA',
'JOIN BENEF_SIN BS',
'    ON AA.IDSINIESTRO = BS.IDSINIESTRO',
'   AND AA.IDPOLIZA = BS.IDPOLIZA',
'   AND AA.BENEF = BS.BENEF',
'WHERE AA.STSAPROBACION = ''PAG'';',
''))
