wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(373168868776056324)
,p_plug_name=>'CUENTA_CLABE_IG'
,p_region_name=>'CUENTA_CLABE_IG'
,p_parent_plug_id=>wwv_flow_imp.id(373168713985056323)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>10
,p_plug_grid_column_span=>3
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  cAnioPago  varchar2(10) := trim(apex_util.get_session_state(''P302_ANIO_PAGO''));',
'  dFecIni    date;',
'  dFecFin    date;',
'  lSql       clob;',
'begin',
unistr('  -- A\00F1o v\00E1lido = 4 d\00EDgitos'),
'  if cAnioPago is not null and regexp_like(cAnioPago, ''^\d{4}$'') then',
'    dFecIni := to_date(cAnioPago || ''0101'', ''yyyymmdd'');',
'    dFecFin := add_months(dFecIni, 12);',
'',
'    lSql :=',
'      ''SELECT cuenta_clabe,',
'              pagos_anio AS numpag',
'       FROM (',
'         SELECT bs.cuenta_clave AS cuenta_clabe,',
'                SUM(CASE',
'                      WHEN aa.fecpago >= DATE '''''' || to_char(dFecIni,''yyyy-mm-dd'') || ''''''',
'                       AND aa.fecpago <  DATE '''''' || to_char(dFecFin,''yyyy-mm-dd'') || ''''''',
'                      THEN 1 ELSE 0',
'                    END) AS pagos_anio,',
'                MIN(aa.fecpago) AS min_fec',
'         FROM APROBACION_ASEG aa',
'         JOIN BENEF_SIN bs',
'           ON aa.benef       = bs.benef',
'          AND aa.idsiniestro = bs.idsiniestro',
'          AND aa.idpoliza    = bs.idpoliza',
'         WHERE bs.cuenta_clave IS NOT NULL',
'           AND aa.stsaprobacion = ''''PAG''''',
'           AND ( :P302_COBERTURA_LIST IS NULL OR aa.codcobert = :P302_COBERTURA_LIST )',
unistr('           -- rendimiento: pagos posteriores no afectan la l\00F3gica'),
'           AND aa.fecpago < DATE '''''' || to_char(dFecFin,''yyyy-mm-dd'') || ''''''',
'         GROUP BY bs.cuenta_clave',
'       )',
'       WHERE pagos_anio > 1',
'          OR ( pagos_anio >= 1 AND min_fec < DATE '''''' || to_char(dFecIni,''yyyy-mm-dd'') || '''''' )'';',
'',
'  else',
unistr('    -- Sin a\00F1o (o inv\00E1lido): total hist\00F3rico, pero solo si tiene 2+ pagos'),
'    lSql :=',
'      ''SELECT bs.cuenta_clave AS cuenta_clabe,',
'              COUNT(*) AS numpag',
'       FROM APROBACION_ASEG aa',
'       JOIN BENEF_SIN bs',
'         ON aa.benef       = bs.benef',
'        AND aa.idsiniestro = bs.idsiniestro',
'        AND aa.idpoliza    = bs.idpoliza',
'       WHERE bs.cuenta_clave IS NOT NULL',
'         AND aa.stsaprobacion = ''''PAG''''',
'         AND ( :P302_COBERTURA_LIST IS NULL OR aa.codcobert = :P302_COBERTURA_LIST )',
'       GROUP BY bs.cuenta_clave',
'       HAVING COUNT(*) > 1'';',
'  end if;',
'',
'  return lSql;',
'end;',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P302_COBERTURA_LIST,P302_ANIO_PAGO'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'CUENTA_CLABE_IG'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
