wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(547094699962411819)
,p_plug_name=>'BeneficiariosPagados_IG'
,p_region_name=>'BeneficiariosPagados_IG'
,p_parent_plug_id=>wwv_flow_imp.id(459962357789363097)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    BS.TIPO_ID_TRIBUTARIO,',
'    BS.NUM_DOC_TRIBUTARIO,',
'    COUNT(*) AS NUM_PAGOS,',
'    SUM(AA.MONTO_LOCAL) AS TOTAL_PAGADO',
'FROM APROBACION_ASEG AA',
'JOIN BENEF_SIN BS',
'    ON AA.IDSINIESTRO = BS.IDSINIESTRO',
'    AND AA.IDPOLIZA = BS.IDPOLIZA',
'    AND AA.BENEF = BS.BENEF',
'WHERE AA.STSAPROBACION = ''PAG''',
'  AND ( :P302_FECHA_INICIO IS NULL OR AA.FECPAGO >= TO_DATE(:P302_FECHA_INICIO, ''DD/MM/YYYY'') )',
'  AND ( :P302_FECHA_FIN IS NULL OR AA.FECPAGO <= TO_DATE(:P302_FECHA_FIN, ''DD/MM/YYYY'') )',
'  AND ( :P302_COBERTURA IS NULL OR AA.CODCOBERT = :P302_COBERTURA )',
'  AND BS.NUM_DOC_TRIBUTARIO IS NOT NULL',
'  AND (BS.CUENTA_CLAVE IS NOT NULL ',
'       OR BS.NUMCUENTABANCARIA IS NOT NULL)',
'GROUP BY ',
'    BS.TIPO_ID_TRIBUTARIO, ',
'    BS.NUM_DOC_TRIBUTARIO',
'HAVING COUNT(*) > 2;',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P302_COBERTURA, P302_FECHA_INICIO, P302_FECHA_FIN'
