,p_name=>'MontoPagado'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    BS.NOMBRE || '' ('' || BS.NUM_DOC_TRIBUTARIO || '')'' AS BENEFICIARIO,',
'    SUM(AA.MONTO_LOCAL) AS TOTAL_PAGADO',
'FROM APROBACION_ASEG AA',
'JOIN BENEF_SIN BS',
'  ON AA.IDSINIESTRO = BS.IDSINIESTRO',
' AND AA.IDPOLIZA = BS.IDPOLIZA',
' AND AA.BENEF = BS.BENEF',
'WHERE AA.STSAPROBACION = ''PAG''',
'  AND AA.FECPAGO >= ADD_MONTHS(TRUNC(SYSDATE), -12)',
unistr('  AND LENGTH(BS.NUM_DOC_TRIBUTARIO) = 12   -- Persona f\00EDsica'),
'  AND BS.NUM_DOC_TRIBUTARIO IS NOT NULL',
'GROUP BY BS.NOMBRE, BS.NUM_DOC_TRIBUTARIO',
'HAVING SUM(AA.MONTO_LOCAL) IS NOT NULL',
'ORDER BY TOTAL_PAGADO DESC',
'FETCH FIRST 10 ROWS ONLY;',
''))
,p_series_name_column_name=>'BENEFICIARIO'
