wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(230933233695818929)
,p_chart_id=>wwv_flow_imp.id(230933152027818928)
,p_seq=>10
,p_name=>'Grafica1'
,p_data_source_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  cModo varchar2(10) := upper(trim(apex_util.get_session_state(''P302_MODO_GRAFICA''))); -- ''ANIO'' o ''MES''',
'  lSql  clob;',
'begin',
'  if cModo = ''MES'' then',
'    lSql :=',
'      ''SELECT',
'           TO_CHAR(y.periodo_ini, ''''MM/YYYY'''') AS label,',
'           SUM(y.cnt_pagos) AS value,',
'           TO_CHAR(y.periodo_ini, ''''YYYYMM'''') AS link_value',
'       FROM (',
'         SELECT',
'             bs.cuenta_clave          AS cuenta,',
'             TRUNC(aa.fecpago,''''MM'''') AS periodo_ini,',
'             COUNT(*)                 AS cnt_pagos',
'         FROM APROBACION_ASEG aa',
'         JOIN BENEF_SIN bs',
'           ON aa.benef       = bs.benef',
'          AND aa.idsiniestro = bs.idsiniestro',
'          AND aa.idpoliza    = bs.idpoliza',
'         WHERE bs.cuenta_clave IS NOT NULL',
'           AND aa.stsaprobacion = ''''PAG''''',
'           AND aa.fecpago IS NOT NULL',
'           AND ( NULLIF(TRIM(:P302_COBERTURA_LIST_GRAFICA), '''''''') IS NULL',
'                 OR aa.codcobert = TRIM(:P302_COBERTURA_LIST_GRAFICA) )',
'         GROUP BY bs.cuenta_clave, TRUNC(aa.fecpago,''''MM'''')',
'       ) y',
'       JOIN (',
'         SELECT',
'             bs.cuenta_clave AS cuenta,',
'             MIN(aa.fecpago) AS min_fec_hist',
'         FROM APROBACION_ASEG aa',
'         JOIN BENEF_SIN bs',
'           ON aa.benef       = bs.benef',
'          AND aa.idsiniestro = bs.idsiniestro',
'          AND aa.idpoliza    = bs.idpoliza',
'         WHERE bs.cuenta_clave IS NOT NULL',
'           AND aa.stsaprobacion = ''''PAG''''',
'           AND aa.fecpago IS NOT NULL',
'           AND ( NULLIF(TRIM(:P302_COBERTURA_LIST_GRAFICA), '''''''') IS NULL',
'                 OR aa.codcobert = TRIM(:P302_COBERTURA_LIST_GRAFICA) )',
'         GROUP BY bs.cuenta_clave',
'       ) m',
'         ON m.cuenta = y.cuenta',
'       WHERE y.cnt_pagos > 1',
'          OR ( y.cnt_pagos >= 1 AND m.min_fec_hist < y.periodo_ini )',
'       GROUP BY y.periodo_ini',
'       ORDER BY y.periodo_ini'';',
'',
'  else',
'    lSql :=',
'      ''SELECT',
'           TO_CHAR(y.periodo_ini, ''''YYYY'''') AS label,',
'           SUM(y.cnt_pagos) AS value,',
'           TO_CHAR(y.periodo_ini, ''''YYYY'''') AS link_value',
'       FROM (',
'         SELECT',
'             bs.cuenta_clave            AS cuenta,',
'             TRUNC(aa.fecpago,''''YYYY'''') AS periodo_ini,',
'             COUNT(*)                   AS cnt_pagos',
'         FROM APROBACION_ASEG aa',
'         JOIN BENEF_SIN bs',
'           ON aa.benef       = bs.benef',
'          AND aa.idsiniestro = bs.idsiniestro',
'          AND aa.idpoliza    = bs.idpoliza',
'         WHERE bs.cuenta_clave IS NOT NULL',
'           AND aa.stsaprobacion = ''''PAG''''',
'           AND aa.fecpago IS NOT NULL',
'           AND ( NULLIF(TRIM(:P302_COBERTURA_LIST_GRAFICA), '''''''') IS NULL',
'                 OR aa.codcobert = TRIM(:P302_COBERTURA_LIST_GRAFICA) )',
'         GROUP BY bs.cuenta_clave, TRUNC(aa.fecpago,''''YYYY'''')',
'       ) y',
'       JOIN (',
'         SELECT',
'             bs.cuenta_clave AS cuenta,',
'             MIN(aa.fecpago) AS min_fec_hist',
'         FROM APROBACION_ASEG aa',
'         JOIN BENEF_SIN bs',
'           ON aa.benef       = bs.benef',
'          AND aa.idsiniestro = bs.idsiniestro',
'          AND aa.idpoliza    = bs.idpoliza',
'         WHERE bs.cuenta_clave IS NOT NULL',
'           AND aa.stsaprobacion = ''''PAG''''',
'           AND aa.fecpago IS NOT NULL',
'           AND ( NULLIF(TRIM(:P302_COBERTURA_LIST_GRAFICA), '''''''') IS NULL',
'                 OR aa.codcobert = TRIM(:P302_COBERTURA_LIST_GRAFICA) )',
'         GROUP BY bs.cuenta_clave',
'       ) m',
'         ON m.cuenta = y.cuenta',
'       WHERE y.cnt_pagos > 1',
'          OR ( y.cnt_pagos >= 1 AND m.min_fec_hist < y.periodo_ini )',
'       GROUP BY y.periodo_ini',
'       ORDER BY y.periodo_ini'';',
'  end if;',
'',
'  return lSql;',
'end;',
''))
,p_ajax_items_to_submit=>'P302_COBERTURA_LIST_GRAFICA,P302_PERIODO_SEL,P302_MODO_GRAFICA'
,p_items_value_column_name=>'VALUE'
,p_items_label_column_name=>'LABEL'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
,p_items_label_display_as=>'PERCENT'
,p_threshold_display=>'onIndicator'
,p_link_target=>'f?p=&APP_ID.:302:&SESSION.::&DEBUG.::P302_PERIODO_SEL,P302_MODO_GRAFICA:&LINK_VALUE.,&P302_MODO_GRAFICA.'
,p_link_target_type=>'REDIRECT_PAGE'
);
