wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(231053028974323722)
,p_chart_id=>wwv_flow_imp.id(231052943822323721)
,p_seq=>10
,p_name=>'Grafica2_cuentas'
,p_data_source_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  cPeriodoSel varchar2(10) := trim(apex_util.get_session_state(''P302_PERIODO_CTA_SEL'')); -- YYYY o YYYYMM',
'  dFecIni     date;',
'  dFecFin     date;',
'  lSql        clob;',
'begin',
unistr('  -- Periodo v\00E1lido:'),
unistr('  --  YYYY   -> a\00F1o'),
'  --  YYYYMM -> mes',
'  if cPeriodoSel is not null and regexp_like(cPeriodoSel, ''^\d{4}$'') then',
unistr('    -- A\00D1O'),
'    dFecIni := to_date(cPeriodoSel || ''0101'', ''yyyymmdd'');',
'    dFecFin := add_months(dFecIni, 12);',
'',
'  elsif cPeriodoSel is not null and regexp_like(cPeriodoSel, ''^\d{6}$'') then',
'    -- MES (YYYYMM)',
'    dFecIni := to_date(cPeriodoSel || ''01'', ''yyyymmdd'');',
'    dFecFin := add_months(dFecIni, 1);',
'',
'  else',
'    dFecIni := null;',
'    dFecFin := null;',
'  end if;',
'',
'  if dFecIni is not null then',
unistr('    -- Top 15 por pagos en el periodo seleccionado (a\00F1o o mes)'),
'    lSql :=',
'      ''SELECT label, value',
'       FROM (',
'         SELECT',
'             bs.numcuentabancaria AS label,',
'             SUM(CASE',
'                   WHEN aa.fecpago >= DATE '''''' || to_char(dFecIni,''yyyy-mm-dd'') || ''''''',
'                    AND aa.fecpago <  DATE '''''' || to_char(dFecFin,''yyyy-mm-dd'') || ''''''',
'                   THEN 1 ELSE 0',
'                 END) AS value,',
'             MIN(aa.fecpago) AS min_fec',
'         FROM APROBACION_ASEG aa',
'         JOIN BENEF_SIN bs',
'           ON aa.benef       = bs.benef',
'          AND aa.idsiniestro = bs.idsiniestro',
'          AND aa.idpoliza    = bs.idpoliza',
'         WHERE bs.numcuentabancaria IS NOT NULL',
'           AND aa.stsaprobacion = ''''PAG''''',
'           AND ( NULLIF(TRIM(:P302_COBERTURA_CTA_LIST_GRAFICA), '''''''') IS NULL',
'                 OR aa.codcobert = TRIM(:P302_COBERTURA_CTA_LIST_GRAFICA) )',
'           -- rendimiento: pagos posteriores al fin del periodo no aportan',
'           AND aa.fecpago < DATE '''''' || to_char(dFecFin,''yyyy-mm-dd'') || ''''''',
'         GROUP BY bs.numcuentabancaria',
'         HAVING',
'              -- A) duplicado en el periodo',
'              SUM(CASE',
'                    WHEN aa.fecpago >= DATE '''''' || to_char(dFecIni,''yyyy-mm-dd'') || ''''''',
'                     AND aa.fecpago <  DATE '''''' || to_char(dFecFin,''yyyy-mm-dd'') || ''''''',
'                    THEN 1 ELSE 0',
'                  END) > 1',
'           OR -- B) 1+ en el periodo y hubo pagos antes del inicio del periodo',
'              ( SUM(CASE',
'                      WHEN aa.fecpago >= DATE '''''' || to_char(dFecIni,''yyyy-mm-dd'') || ''''''',
'                       AND aa.fecpago <  DATE '''''' || to_char(dFecFin,''yyyy-mm-dd'') || ''''''',
'                      THEN 1 ELSE 0',
'                    END) >= 1',
'                AND MIN(aa.fecpago) < DATE '''''' || to_char(dFecIni,''yyyy-mm-dd'') || '''''' )',
'       )',
'       ORDER BY value DESC, label',
'       FETCH FIRST 15 ROWS ONLY'';',
'',
'  else',
unistr('    -- Periodo NULL/ inv\00E1lido: hist\00F3rico, solo cuentas con 2+ pagos'),
'    lSql :=',
'      ''SELECT label, value',
'       FROM (',
'         SELECT',
'             bs.numcuentabancaria AS label,',
'             COUNT(*) AS value',
'         FROM APROBACION_ASEG aa',
'         JOIN BENEF_SIN bs',
'           ON aa.benef       = bs.benef',
'          AND aa.idsiniestro = bs.idsiniestro',
'          AND aa.idpoliza    = bs.idpoliza',
'         WHERE bs.numcuentabancaria IS NOT NULL',
'           AND aa.stsaprobacion = ''''PAG''''',
'           AND ( NULLIF(TRIM(:P302_COBERTURA_CTA_LIST_GRAFICA), '''''''') IS NULL',
'                 OR aa.codcobert = TRIM(:P302_COBERTURA_CTA_LIST_GRAFICA) )',
'         GROUP BY bs.numcuentabancaria',
'         HAVING COUNT(*) > 1',
'       )',
'       ORDER BY value DESC, label',
'       FETCH FIRST 15 ROWS ONLY'';',
'  end if;',
'',
'  return lSql;',
'end;',
''))
,p_ajax_items_to_submit=>'P302_COBERTURA_CTA_LIST_GRAFICA,P302_MODO_CTA_GRAFICA,P302_PERIODO_CTA_SEL'
,p_items_value_column_name=>'VALUE'
,p_items_label_column_name=>'LABEL'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
,p_items_label_display_as=>'PERCENT'
,p_threshold_display=>'onIndicator'
);
