,p_prompt=>'Coberturas'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT distinct',
'    aa.codcobert AS d,',
'    aa.codcobert AS r',
'FROM APROBACION_ASEG aa',
'JOIN BENEF_SIN bs',
'  ON aa.benef       = bs.benef',
' AND aa.idsiniestro = bs.idsiniestro',
' AND aa.idpoliza    = bs.idpoliza',
'WHERE bs.cuenta_clave IS NOT NULL',
'  AND aa.stsaprobacion = ''PAG''',
'  AND aa.codcobert IS NOT NULL',
'GROUP BY aa.codcobert, bs.cuenta_clave',
'HAVING COUNT(*) > 1',
'ORDER BY aa.codcobert',
''))
,p_lov_display_null=>'YES'
