wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(230934326344818940)
,p_name=>'P302_PERIODO_SEL'
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(230932973034818926)
,p_prompt=>'Periodo'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov_language=>'PLSQL'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  cModo varchar2(10) := upper(trim(apex_util.get_session_state(''P302_MODO_GRAFICA''))); -- ''ANIO'' o ''MES''',
'  nAnioIni number := 2014;',
'  lSql clob;',
'begin',
'  if cModo = ''MES'' then',
'    -- Display: MM/YYYY | Return: YYYYMM (ej. 202512)',
'    lSql :=',
'      ''SELECT',
'           TO_CHAR(ADD_MONTHS(DATE ''''''||nAnioIni||''-01-01'''', LEVEL-1), ''''MM/YYYY'''') AS display_value,',
'           TO_CHAR(ADD_MONTHS(DATE ''''''||nAnioIni||''-01-01'''', LEVEL-1), ''''YYYYMM'''')  AS return_value',
'       FROM dual',
'       CONNECT BY ADD_MONTHS(DATE ''''''||nAnioIni||''-01-01'''', LEVEL-1) <= TRUNC(SYSDATE, ''''MM'''')',
'       ORDER BY return_value DESC'';',
'  else',
unistr('    -- Default A\00D1O. Display/Return: YYYY'),
'    lSql :=',
'      ''SELECT',
'           TO_CHAR(''||nAnioIni||'' + LEVEL - 1) AS display_value,',
'           TO_CHAR(''||nAnioIni||'' + LEVEL - 1) AS return_value',
'       FROM dual',
'       CONNECT BY ''||nAnioIni||'' + LEVEL - 1 <= EXTRACT(YEAR FROM SYSDATE)',
'       ORDER BY return_value DESC'';',
'  end if;',
'',
'  return lSql;',
'end;',
''))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'--Sin Asignar--'
,p_lov_cascade_parent_items=>'P302_MODO_GRAFICA'
,p_ajax_items_to_submit=>'P302_MODO_GRAFICA'
,p_ajax_optimize_refresh=>'N'
,p_cSize=>30
