'//Mapeo de static_id de columnas',
'const campos = [',
'    "CUENTA_CLABE_11",',
'    "NUMPAG_11",',
'    "IDSINIESTRO_12",',
'    "IDPOLIZA_12",',
'    "PRODUCTO_12",',
'    "COD_ASEGURADO_12",',
'    "MONTO_LOCAL_12",',
'    "CODCOBERT_12",',
'    "CODUSUARIO_ALTA_12",',
'    "IDTIPO_PAGO_12",',
'    "IDSINIESTRO_21",',
'    "IDPOLIZA_21",',
'    "COD_ASEGURADO_21",',
'    "MONTO_LOCAL_21",',
'    "MONTO_MONEDA_21",',
'    "TIPO_ID_TRIBUTARIO_21",',
'    "NUM_DOC_TRIBUTARIO_21",',
'    "ENT_FINANCIERA_21",',
