 p_id=>wwv_flow_imp.id(460240867555395038)
,p_plug_name=>'Pagos'
,p_region_name=>'Pagos'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(243778733172890443)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    AA.IDSINIESTRO,',
'    AA.IDPOLIZA,',
'    (SELECT DISTINCT IDTIPOSEG ',
'        FROM DETALLE_POLIZA ',
'        WHERE IDPOLIZA = AA.IDPOLIZA',
'    ) AS PRODUCTO,',
'    AA.COD_ASEGURADO,',
'    AA.MONTO_LOCAL,',
'    AA.MONTO_MONEDA,',
'    AA.FECPAGO,',
'    AA.CODCOBERT,',
'    BS.NOMBRE AS BENEFICIARIO,',
'    BS.TIPO_ID_TRIBUTARIO,',
'    BS.NUM_DOC_TRIBUTARIO,',
'    BS.ENT_FINANCIERA,',
'    BS.CUENTA_CLAVE,',
'    BS.NUMCUENTABANCARIA',
'FROM APROBACION_ASEG AA ',
'JOIN BENEF_SIN BS',
'    ON AA.IDSINIESTRO = BS.IDSINIESTRO',
'   AND AA.IDPOLIZA   = BS.IDPOLIZA',
'   AND AA.BENEF      = BS.BENEF',
'WHERE AA.STSAPROBACION = ''PAG''',
'  AND AA.CODCOBERT IS NOT NULL',
'  AND BS.NUM_DOC_TRIBUTARIO = :P303_NUM_DOC_TRIBUTARIO',
'  AND (BS.CUENTA_CLAVE IS NOT NULL ',
'       OR BS.NUMCUENTABANCARIA IS NOT NULL);',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'MILLIMETERS'
